  "{installPath}/components/control/command/_impl/core/command_widget.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:flutter/material.dart'\n    hide Theme, TextField, ErrorWidgetBuilder;\n\nimport 'command_dialog.dart';\nimport '../state/command_state.dart';\n\n/// Command palette with search input, results, and keyboard handling.\nclass Command extends StatefulWidget {\n  const Command({\n    super.key,\n    required this.builder,\n    this.autofocus = true,\n    this.debounceDuration = const Duration(milliseconds: 500),\n    this.emptyBuilder,\n    this.errorBuilder,\n    this.loadingBuilder,\n    this.surfaceOpacity,\n    this.surfaceBlur,\n    this.searchPlaceholder,\n  });\n\n  /// Search results builder.\n  final CommandBuilder builder;\n\n  /// Auto-focus the search field.\n  final bool autofocus;\n\n  /// Debounce delay for search input.\n  final Duration debounceDuration;\n\n  /// Empty state builder override.\n  final WidgetBuilder? emptyBuilder;\n\n  /// Error builder override.\n  final ErrorWidgetBuilder? errorBuilder;\n\n  /// Loading state builder.\n  final WidgetBuilder? loadingBuilder;\n\n  /// Optional surface opacity override.\n  final double? surfaceOpacity;\n\n  /// Optional surface blur override.\n  final double? surfaceBlur;\n\n  /// Placeholder widget for the search input.\n  final Widget? searchPlaceholder;\n\n  @override\n  /// Executes `createState` behavior for this component/composite.\n  State<Command> createState() => CommandState();\n}\n",
  "{installPath}/components/control/command/_impl/state/command_item_state.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:flutter/material.dart' hide Theme, TextField;\n\nimport '../../../../../shared/primitives/clickable.dart';\nimport '../../../../../shared/primitives/subfocus.dart';\nimport '../../../../../shared/theme/theme.dart';\nimport '../../../../../shared/utils/constants.dart';\nimport '../../../../../shared/utils/color_extensions.dart';\nimport '../../../../../shared/primitives/text.dart';\nimport '../core/command_item_widget.dart';\n\n/// CommandItemState defines a reusable type for this registry module.\nclass CommandItemState extends State<CommandItem> {\n  @override\n  /// Executes `build` behavior for this component/composite.\n  Widget build(BuildContext context) {\n    final themeData = Theme.of(context);\n    return Actions(\n      actions: {\n        ActivateIntent: CallbackAction<Intent>(\n          onInvoke: (intent) {\n            widget.onTap?.call();\n            return null;\n          },\n        ),\n      },\n      child: SubFocus(\n        builder: (context, state) {\n          return Clickable(\n            onPressed: widget.onTap,\n            onHover: (hovered) {\n              if (hovered) {\n                state.requestFocus();\n              }\n            },\n            child: AnimatedContainer(\n              duration: kDefaultDuration,\n              decoration: BoxDecoration(\n                color: state.isFocused\n                    ? themeData.colorScheme.accent\n                    : themeData.colorScheme.accent.withValues(alpha: 0),\n                borderRadius: BorderRadius.circular(themeData.radiusSm),\n              ),\n              padding: EdgeInsets.symmetric(\n                horizontal:\n                    themeData.density.baseGap * themeData.