  "{installPath}/components/form/form/_impl/core/min_validator.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../form.dart';\n\n/// A validator that checks if a numeric value meets a minimum threshold.\n///\n/// [MinValidator] ensures that numeric values are greater than (or equal to)\n/// a specified minimum value. Useful for enforcing minimum quantities, ages, etc.\n///\n/// Example:\n/// ```dart\n/// MinValidator<int>(\n///   18,\n///   inclusive: true,\n///   message: 'Must be at least 18 years old',\n/// )\n/// ```\nclass MinValidator<T extends num> extends Validator<T> {\n  /// The minimum acceptable value.\n  final T min;\n\n  /// Whether the minimum value itself is acceptable (true) or must be exceeded (false).\n  final bool inclusive;\n\n  /// Custom error message, or null to use default localized message.\n  final String?\n  message; // if null, use default message from ShadcnLocalizations\n\n  /// Creates a [MinValidator] with the specified minimum value.\n  const MinValidator(this.min, {this.inclusive = true, this.message});\n\n  @override\n  FutureOr<ValidationResult?> validate(\n    BuildContext context,\n    T? value,\n    FormValidationMode state,\n  ) {\n    if (value == null) {\n      return null;\n    }\n    if (inclusive) {\n      if (value < min) {\n        return InvalidResult(\n          message ??\n              Localizations.of(\n                context,\n                ShadcnLocalizations,\n              ).formGreaterThanOrEqualTo(min),\n          state: state,\n        );\n      }\n    } else {\n      if (value <= min) {\n        return InvalidResult(\n          message ??\n              Localizations.of(\n                context,\n                ShadcnLocalizations,\n              ).formGreaterThan(min),\n          state: state,\n        );\n      }\n    }\n    return null;\n