  "{installPath}/components/form/form_field/_impl/core/object_form_handler.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../form_field.dart';\n\n/// Abstract interface for controlling an object form field's state.\n///\n/// [ObjectFormHandler] provides methods to interact with an object form field,\n/// including getting/setting values and controlling the editor visibility.\nabstract class ObjectFormHandler<T> {\n  /// Gets the current value.\n  T? get value;\n\n  /// Sets the current value.\n  set value(T? value);\n\n  /// Opens the editor with an optional initial value.\n  void prompt([T? value]);\n\n  /// Closes the editor.\n  Future<void> close();\n\n  /// Finds the [ObjectFormHandler] in the widget tree.\n  static ObjectFormHandler<T> of<T>(BuildContext context) {\n    return Data.of<ObjectFormHandler<T>>(context);\n  }\n\n  /// Finds the [ObjectFormHandler] in the widget tree (alternative method).\n  static ObjectFormHandler<T> find<T>(BuildContext context) {\n    return Data.find<ObjectFormHandler<T>>(context);\n  }\n}\n",
  "{installPath}/components/form/form_field/_impl/state/_object_form_field_dialog_state.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../form_field.dart';\n\n/// _ObjectFormFieldDialogState stores and manages mutable widget state.\nclass _ObjectFormFieldDialogState<T> extends State<_ObjectFormFieldDialog<T>>\n    implements ObjectFormHandler<T> {\n  late T? _value;\n\n  /// Initializes stateful resources for this widget.\n  @override\n  void initState() {\n    super.initState();\n    _value = widget.value;\n  }\n\n  @override\n  T? get value => _value;\n\n  /// Performs `value` logic for this form component.\n  @override\n  set value(T? value) {\n    if (mounted) {\n      /// Triggers a rebuild after mutating local state.\n      setState(() {\n        _value = value;\n      });\n    } else {\n      _value = value;\n    }\n    widget.onChanged(value);\n  }\n\n  /// Performs `prompt` logic for this form component.\n  @override\n  void prompt([T? value]) {\n    widget.prompt.call(value);\n  }\n\n  /// Performs `close` logic for this form component.\n  @override\n  Future<void> close() {\n    final modalRoute = ModalRoute.of(context);\n    Navigator.of(context).pop();\n    return modalRoute?.completed ?? Future.value();\n  }\n\n  /// Builds the widget tree for this component state.\n  @override\n  Widget build(BuildContext context) {\n    if (!widget.decorate) {\n      return widget.editorBuilder(context, this);\n    }\n    final localizations = ShadcnLocalizations.of(context);\n    final theme = Theme.of(context);\n    return Data<ObjectFormHandler<T>>.inherit(\n      data: this,\n      child: AlertDialog(\n        title: widget.dialogTitle,\n        content: Padding(\n          padding: EdgeInsets.only(top: theme.density.baseGap * theme.scaling),\n          child: widget.editorBuilder(context, this),\n        ),\n        actions: [\n          if (widget.dialogActions != null)\n            ...widget.dialogActions!(context, this),\n          ObjectInputCancelButton(\n            child: Text(localizations.buttonCancel),\n            onPressed: () {\n              Navigator.of(context).pop();\n            },\n          ),\n          ObjectInputSaveButton(\n            child: Text(localizations.buttonSave),\n            onPressed: () {\n              Navigator.of(context).pop(ObjectFormFieldDialogResult(_value));\n            },\n          ),\n        ],\n      ),\n    );\n  }\n}\n",
  "{installPath}/components/form/form_field/_impl/state/_object_form_field_popup_state.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../form_field.dart';\n\n/// _ObjectFormFieldPopupState stores and manages mutable widget state.\nclass _ObjectFormFieldPopupState<T> extends State<_ObjectFormFieldPopup<T>>\n    implements ObjectFormHandler<T> {\n  late T? _value;\n\n  /// Initializes stateful resources for this widget.\n  @override\n  void initState() {\n    super.initState();\n    _value = widget.value;\n  }\n\n  @override\n  T? get value => _value;\n\n  /// Performs `value` logic for this form component.\n  @override\n  set value(T? value) {\n    if (mounted) {\n      /// Triggers a rebuild after mutating local state.\n      setState(() {\n        _value = value;\n      });\n    } else {\n      _value = value;\n    }\n    widget.onChanged?.call(value);\n  }\n\n  /// Performs `prompt` logic for this form component.\n  @override\n  void prompt([T? value]) {\n    widget.prompt.call(value);\n  }\n\n  /// Performs `close` logic for this form component.\n  @override\n  Future<void> close() {\n    return closeOverlay(context);\n  }\n\n  /// Builds the widget tree for this component state.\n  @override\n  Widget build(BuildContext context) {\n    if (!widget.decorate) {\n      return widget.editorBuilder(context, this);\n    }\n    final theme = Theme.of(context);\n    return Data<ObjectFormHandler<T>>.inherit(\n      data: this,\n      child: SurfaceCard(\n        padding:\n            widget.popoverPadding ??\n            (EdgeInsets.symmetric(\n                  vertical: theme.density.baseContentPadding,\n                  horizontal: theme.density.baseContentPadding,\n                ) *\n                theme.scaling),\n        child: widget.editorBuilder(context, this),\n      ),\n    );\n  }\n}\n",
  "{installPath}/components/form/form_field/_impl/state/object_form_field_state.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../form_field.dart';\n\n/// State class for [ObjectFormField] managing form value and user interactions.\n///\n/// Handles value updates, popover/dialog display, and integrates with the\n/// form validation system. This state also determines whether the field is\n/// enabled based on the presence of an `onChanged` callback.\nclass ObjectFormFieldState<T> extends State<ObjectFormField<T>>\n    with FormValueSupplier<T, ObjectFormField<T>> {\n  final PopoverController _popoverController = PopoverController();\n\n  /// Initializes stateful resources for this widget.\n  @override\n  void initState() {\n    super.initState();\n    formValue = widget.value;\n  }\n\n  /// Gets the current form value.\n  ///\n  /// Returns: The current value of type `T?`.\n  T? get value => formValue;\n\n  /// Sets a new form value and notifies listeners.\n  ///\n  /// Parameters:\n  /// - [value] (`T?`, required): The new value to set.\n  set value(T? value) {\n    widget.onChanged?.call(value);\n    formValue = value;\n  }\n\n  /// Performs `didReplaceFormValue` logic for this form component.\n  @override\n  void didReplaceFormValue(T value) {\n    widget.onChanged?.call(value);\n  }\n\n  /// Reacts to widget configuration updates from the parent.\n  @override\n  void didUpdateWidget(covariant ObjectFormField<T> oldWidget) {\n    super.didUpdateWidget(oldWidget);\n    if (oldWidget.value != widget.value) {\n      formValue = widget.value;\n    }\n  }\n\n  /// Whether this field is enabled.\n  ///\n  /// Returns true if explicitly enabled or if an `onChanged` callback exists.\n  bool get enabled => widget.enabled ?? widget.onChanged != null;\n\n  /// Releases resources owned by this state object.\n  @override\n  void dispose() {\n    _popoverController.dispose();\n    super.dispose();\n  }\n\n  /// Performs `_showDialog` logic for this form component.\n  void _showDialog([T? value]) {\n    value ??= formValue;\n    showDialog(\n      context: context,\n      builder: (context) {\n        return _ObjectFormFieldDialog<T>(\n          dialogTitle: widget.dialogTitle,\n          value: value,\n          editorBuilder: widget.editorBuilder,\n          dialogActions: widget.dialogActions,\n          prompt: prompt,\n          decorate: widget.decorate,\n          onChanged: (value) {\n            // by default, dialog will not immediately inform if value is changed\n            // but if its explicitly set to true, then we should inform\n            if (widget.immediateValueChange == true) {\n              this.value = value;\n            }\n          },\n        );\n      },\n    ).then((value) {\n      if (mounted &&\n          value is ObjectFormFieldDialogResult<T> &&\n          // in dialog, by default we do not inform immediate change\n          // so after dialog close, we should inform the final value\n          widget.immediateValueChange != true) {\n        this.value = value.value;\n      }\n    });\n  }\n\n  /// Performs `_showPopover` logic for this form component.\n  void _showPopover([T? value]) {\n    final theme = Theme.of(context);\n    final scaling = theme.scaling;\n    value ??= formValue;\n    T? delayedResult = value;\n    _popoverController\n        .show(\n          context: context,\n          alignment: widget.popoverAlignment ?? Alignment.topLeft,\n          anchorAlignment:\n              widget.popoverAnchorAlignment ?? Alignment.bottomLeft,\n          overlayBarrier: OverlayBarrier(\n            borderRadius: BorderRadius.circular(theme.radiusLg),\n          ),\n          modal: true,\n          offset: Offset(0, 8 * scaling),\n          builder: (context) {\n            return _ObjectFormFieldPopup<T>(\n              value: value,\n              editorBuilder: widget.editorBuilder,\n              popoverPadding: widget.popoverPadding,\n              prompt: prompt,\n              decorate: widget.decorate,\n              onChanged: (value) {\n                // by default, popover will immediately inform any changes\n                // but if its explicitly set to false, then we should not inform\n                if (mounted && widget.immediateValueChange != false) {\n                  this.value = value;\n                } else {\n                  delayedResult = value;\n                }\n              },\n            );\n          },\n        )\n        .then((_) {\n          if (mounted && widget.immediateValueChange == false) {\n            this.value = delayedResult;\n          }\n        });\n  }\n\n  /// Prompts the user to select or edit a value via dialog or popover.\n  ///\n  /// Displays the appropriate UI based on the configured [PromptMode].\n  ///\n  /// Parameters:\n  /// - [value] (`T?`, optional): An initial value to display in the prompt.\n  ///\n  /// Example:\n  /// ```dart\n  /// fieldState.prompt(initialValue);\n  /// ```\n  void prompt([T? value]) {\n    if (widget.mode == PromptMode.dialog) {\n      _showDialog(value);\n    } else {\n      _showPopover(value);\n    }\n  }\n\n  /// Performs `_decorateIcon` logic for this form component.\n  Widget? _decorateIcon(Widget? icon) {\n    if (icon == null) {\n      return null;\n    }\n    final theme = Theme.of(context);\n    return IconTheme(\n      data: theme.iconTheme.small.copyWith(\n        color: theme.colorScheme.mutedForeground,\n      ),\n      child: icon,\n    );\n  }\n\n  /// Builds the widget tree for this component state.\n  @override\n  Widget build(BuildContext context) {\n    final size = widget.size ?? ButtonSize.normal;\n    final density = widget.density ?? ButtonDensity.normal;\n    final shape = widget.shape ?? ButtonShape.rectangle;\n    return OutlineButton(\n      trailing: _decorateIcon(widget.trailing),\n      leading: _decorateIcon(widget.leading),\n      size: size,\n      density: density,\n      shape: shape,\n      onPressed: enabled && widget.onChanged != null ? prompt : null,\n      enabled: enabled,\n      child: value == null\n          ? widget.placeholder.muted()\n          : widget.builder(context, value as T),\n    );\n  }\n}\n",
  "{installPath}/components/form/form_field/form_field.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:data_widget/data_widget.dart';\nimport 'package:flutter/widgets.dart';\n\nimport '../../../shared/localizations/shadcn_localizations.dart';\nimport '../../../shared/primitives/form_value_supplier.dart';\nimport '../../../shared/primitives/overlay.dart';\nimport '../../../shared/primitives/text.dart';\nimport '../../../shared/theme/theme.dart';\nimport '../../layout/card/card.dart';\nimport '../../control/button/button.dart';\nimport '../../overlay/dialog/dialog.dart';\nimport '../../overlay/alert_dialog/alert_dialog.dart';\n\npart '_impl/core/_object_form_field_dialog.dart';\npart '_impl/state/_object_form_field_dialog_state.dart';\npart '_impl/core/_object_form_field_popup.dart';\npart '_impl/state/_object_form_field_popup_state.dart';\npart '_impl/core/object_form_field.dart';\npart '_impl/core/object_form_field_dialog_result.dart';\npart '_impl/state/object_form_field_state.dart';\npart '_impl/core/object_form_handler.dart';\n\n/// Type definition for the save button in an object input form field.\ntypedef ObjectInputSaveButton = PrimaryButton;\n\n/// Type definition for the cancel button in an object input form field.\ntypedef ObjectInputCancelButton = OutlineButton;\n\n/// Defines how a form field editor is presented to the user.\n///\n/// [PromptMode] determines whether the field editor appears in a modal\n/// dialog or a popover overlay.\nenum PromptMode {\n  /// Display the editor in a modal dialog.\n  dialog,\n\n  /// Display the editor in a popover overlay.\n  popover,\n}\n",
