  "{installPath}/components/form/formatter/_impl/utils/_integer_only_formatter.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../formatter.dart';\n\n/// _IntegerOnlyFormatter represents a form-related type in the registry.\nclass _IntegerOnlyFormatter extends TextInputFormatter {\n  /// Field storing `min` for this form implementation.\n  final int? min;\n\n  /// Field storing `max` for this form implementation.\n  final int? max;\n\n  _IntegerOnlyFormatter({this.min, this.max});\n\n  @override\n  TextEditingValue formatEditUpdate(\n    TextEditingValue oldValue,\n    TextEditingValue newValue,\n  ) {\n    String newText = newValue.text;\n    if (newText.isEmpty) {\n      return newValue;\n    }\n    bool negate = newText.startsWith('-');\n    if (negate) {\n      newText = newText.substring(1);\n    }\n    int? value = int.tryParse(newText);\n    if (value == null) {\n      if (negate) {\n        return const TextEditingValue(\n          text: '-',\n          selection: TextSelection.collapsed(offset: 1),\n        );\n      }\n      return oldValue;\n    }\n    if (min != null && value <= min!) {\n      value = min!;\n    }\n    if (max != null && value >= max!) {\n      value = max!;\n    }\n    newText = value.toString();\n    if (negate) {\n      newText = '-\$newText';\n    }\n    return TextEditingValue(\n      text: newText,\n      selection: contraintToNewText(newValue, newText),\n    );\n  }\n}\n",
  "{installPath}/components/form/formatter/_impl/utils/_math_expression_formatter.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../formatter.dart';\n\n/// _MathExpressionFormatter represents a form-related type in the registry.\nclass _MathExpressionFormatter extends TextInputFormatter {\n  /// Field storing `context` for this form implementation.\n  final Map<String, dynamic>? context;\n  const _MathExpressionFormatter({this.context});\n  @override\n  TextEditingValue formatEditUpdate(\n    TextEditingValue oldValue,\n    TextEditingValue newValue,\n  ) {\n    String newText = newValue.text;\n\n    Object? result;\n    try {\n      Expression expression = Expression.parse(newText);\n      ExpressionEvaluator evaluator = const ExpressionEvaluator();\n      result = evaluator.eval(expression, context ?? {});\n      if (result is! num) {\n        result = '';\n      }\n    } catch (e) {\n      result = '';\n    }\n    String resultText = result.toString();\n    if (resultText.contains('.')) {\n      while (resultText.endsWith('0')) {\n        resultText = resultText.substring(0, resultText.length - 1);\n      }\n      if (resultText.endsWith('.')) {\n        resultText = resultText.substring(0, resultText.length - 1);\n      }\n    }\n    return TextEditingValue(\n      text: resultText,\n      selection: contraintToNewText(newValue, resultText),\n    );\n  }\n}\n",
  "{installPath}/components/form/formatter/_impl/utils/_time_formatter.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../formatter.dart';\n\n/// _TimeFormatter represents a form-related type in the registry.\nclass _TimeFormatter extends TextInputFormatter {\n  /// Field storing `length` for this form implementation.\n  final int length;\n  const _TimeFormatter({required this.length});\n  @override\n  TextEditingValue formatEditUpdate(\n    TextEditingValue oldValue,\n    TextEditingValue newValue,\n  ) {\n    // make sure new value has leading zero\n    var newText = newValue.text;\n\n    int substringCount = 0;\n    if (newText.length > length) {\n      substringCount = newText.length - length;\n      newText = newText.substring(substringCount);\n    }\n\n    int padLength = length - newText.length;\n\n    var baseOffset2 = newValue.selection.baseOffset;\n\n    var extentOffset2 = newValue.selection.extentOffset;\n    if (padLength > 0) {\n      newText = newText.padLeft(length, '0');\n      baseOffset2 = baseOffset2 + padLength;\n      extentOffset2 = extentOffset2 + padLength;\n    }\n    return newValue.copyWith(\n      text: newText,\n      composing: newValue.composing.isValid\n          ? TextRange(\n              start: newValue.composing.start.clamp(\n                0,\n                min(length, newValue.text.length),\n              ),\n              end: newValue.composing.end.clamp(\n                0,\n                min(length, newValue.text.length),\n              ),\n            )\n          : newValue.composing,\n      selection: TextSelection(\n        baseOffset: baseOffset2.clamp(0, min(length, newText.length)),\n        extentOffset: extentOffset2.clamp(0, min(length, newText.length)),\n      ),\n    );\n  }\n}\n",
  "{installPath}/components/form/formatter/_impl/utils/_to_lower_case_text_formatter.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../formatter.dart';\n\n/// _ToLowerCaseTextFormatter represents a form-related type in the registry.\nclass _ToLowerCaseTextFormatter extends TextInputFormatter {\n  const _ToLowerCaseTextFormatter();\n  @override\n  TextEditingValue formatEditUpdate(\n    TextEditingValue oldValue,\n    TextEditingValue newValue,\n  ) {\n    return TextEditingValue(\n      text: newValue.text.toLowerCase(),\n      selection: newValue.selection,\n    );\n  }\n}\n",
  "{installPath}/components/form/formatter/_impl/utils/_to_upper_case_text_formatter.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../formatter.dart';\n\n/// _ToUpperCaseTextFormatter represents a form-related type in the registry.\nclass _ToUpperCaseTextFormatter extends TextInputFormatter {\n  const _ToUpperCaseTextFormatter();\n  @override\n  TextEditingValue formatEditUpdate(\n    TextEditingValue oldValue,\n    TextEditingValue newValue,\n  ) {\n    return TextEditingValue(\n      text: newValue.text.toUpperCase(),\n      selection: newValue.selection,\n    );\n  }\n}\n",
  "{installPath}/components/form/formatter/formatter.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'dart:math';\n\nimport 'package:expressions/expressions.dart';\nimport 'package:flutter/services.dart';\n\npart '_impl/utils/_double_only_formatter.dart';\npart '_impl/utils/_hex_text_formatter.dart';\npart '_impl/utils/_integer_only_formatter.dart';\npart '_impl/utils/_math_expression_formatter.dart';\npart '_impl/utils/_time_formatter.dart';\npart '_impl/utils/_to_lower_case_text_formatter.dart';\npart '_impl/utils/_to_upper_case_text_formatter.dart';\n\n/// Constrains the text selection to fit within the new text length.\n///\n/// Helper function that ensures selection offsets don't exceed the bounds\n/// of the updated text.\nTextSelection contraintToNewText(TextEditingValue newValue, String newText) {\n  return TextSelection(\n    baseOffset: newValue.selection.baseOffset.clamp(0, newText.length),\n    extentOffset: newValue.selection.extentOffset.clamp(0, newText.length),\n  );\n}\n\n/// Provides factory methods for common text input formatters.\n///\n/// [TextInputFormatters] is a utility class that creates various pre-configured\n/// [TextInputFormatter] instances for common formatting needs like uppercase/lowercase\n/// conversion, numeric input, time formatting, and more.\n///\n/// Example:\n/// ```dart\n/// TextField(\n///   inputFormatters: [\n///     TextInputFormatters.toUpperCase,\n///     TextInputFormatters.integerOnly(min: 0, max: 100),\n///   ],\n/// )\n/// ```\nclass TextInputFormatters {\n  /// Converts all input text to uppercase.\n  static const TextInputFormatter toUpperCase = _ToUpperCaseTextFormatter();\n\n  /// Converts all input text to lowercase.\n  static const TextInputFormatter toLowerCase = _ToLowerCaseTextFormatter();\n\n  /// Creates a formatter for time input with leading zeros.\n  ///\n  /// Parameters:\n  /// - [length]: The fixed length of the time string.\n  static TextInputFormatter time({required int length}) {\n    return _TimeFormatter(length: length);\n  }\n\n  /// Creates a formatter that only allows integer input with optional min/max bounds.\n  ///\n  /// Parameters:\n  /// - [min]: Optional minimum value.\n  /// - [max]: Optional maximum value.\n  static TextInputFormatter integerOnly({int? min, int? max}) {\n    return _IntegerOnlyFormatter(min: min, max: max);\n  }\n\n  /// Creates a formatter that only allows decimal numeric input.\n  ///\n  /// Parameters:\n  /// - [min]: Optional minimum value.\n  /// - [max]: Optional maximum value.\n  /// - [decimalDigits]: Optional fixed number of decimal places.\n  static TextInputFormatter digitsOnly({\n    double? min,\n    double? max,\n    int? decimalDigits,\n  }) {\n    return _DoubleOnlyFormatter(\n      min: min,\n      max: max,\n      decimalDigits: decimalDigits,\n    );\n  }\n\n  /// Creates a formatter that evaluates mathematical expressions.\n  ///\n  /// Parameters:\n  /// - [context]: Optional context variables for expression evaluation.\n  static TextInputFormatter mathExpression({Map<String, dynamic>? context}) {\n    return _MathExpressionFormatter(context: context);\n  }\n\n  /// Creates a formatter for hexadecimal input.\n  ///\n  /// Parameters:\n  /// - [hashPrefix]: Whether to require/add a '#' prefix.\n  static TextInputFormatter hex({bool hashPrefix = false}) {\n    return _HexTextFormatter(hashPrefix: hashPrefix);\n  }\n\n  const TextInputFormatters._();\n}\n",
  "{installPath}/components/form/history/_impl/core/color_history_storage.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../history.dart';\n\n/// An abstract interface for storing and managing color history.\n///\n/// [ColorHistoryStorage] defines the contract for color history management,\n/// including adding new colors, clearing history, and accessing recent colors.\n/// Implementations should provide storage mechanisms (in-memory, persistent, etc.).\nabstract class ColorHistoryStorage implements Listenable {\n  /// Adds a color to the history.\n  ///\n  /// Parameters:\n  /// - [color]: The color to add to the history.\n  void addHistory(Color color);\n\n  /// Replaces the entire color history with a new list.\n  ///\n  /// Parameters:\n  /// - [colors]: The new list of colors to set as the history.\n  void setHistory(List<Color> colors);\n\n  /// Clears all colors from the history.\n  void clear();\n\n  /// The maximum number of colors that can be stored in the history.\n  int get capacity;\n\n  /// The list of recent colors, ordered from most to least recent.\n  List<Color> get recentColors;\n\n  /// Finds and listens the [ColorHistoryStorage] in the widget tree.\n  static ColorHistoryStorage of(BuildContext context) {\n    return Data.of<ColorHistoryStorage>(context);\n  }\n\n  /// Finds the [ColorHistoryStorage] in the widget tree.\n  static ColorHistoryStorage find(BuildContext context) {\n    return Data.maybeFind<ColorHistoryStorage>(context) ??\n        Data.maybeFindMessenger<ColorHistoryStorage>(context) ??\n        (throw FlutterError(\n          'No ColorHistoryStorage found in context. Make sure to wrap your widget tree with a RecentColorsScope.',\n        ));\n  }\n}\n",
  "{installPath}/components/form/history/_impl/core/recent_colors_scope.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../history.dart';\n\n/// Provides color history storage in the widget tree.\n///\n/// [RecentColorsScope] manages a list of recently used colors and makes it\n/// available to descendant widgets through [ColorHistoryStorage]. It supports\n/// a configurable maximum capacity and notifies listeners of changes.\nclass RecentColorsScope extends StatefulWidget {\n  /// Initial colors to populate the history.\n  final List<Color> initialRecentColors;\n\n  /// Maximum number of colors to keep in the history.\n  final int maxRecentColors;\n\n  /// Called when the recent colors list changes.\n  final ValueChanged<List<Color>>? onRecentColorsChanged;\n\n  /// The child widget.\n  final Widget child;\n\n  /// Creates a [RecentColorsScope].\n  const RecentColorsScope({\n    super.key,\n    this.initialRecentColors = const [],\n    this.maxRecentColors = 50,\n    this.onRecentColorsChanged,\n    required this.child,\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  State<RecentColorsScope> createState() => RecentColorsScopeState();\n}\n",
  "{installPath}/components/form/history/_impl/state/recent_colors_scope_state.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../history.dart';\n\n/// State class for [RecentColorsScope] implementing color history storage.\n///\n/// Manages the list of recently used colors and provides storage functionality\n/// for color history tracking.\nclass RecentColorsScopeState extends State<RecentColorsScope>\n    implements ColorHistoryStorage {\n  late _ColorListNotifier _recentColors;\n\n  @override\n  int get capacity => widget.maxRecentColors;\n\n  /// Initializes stateful resources for this widget.\n  @override\n  void initState() {\n    super.initState();\n    _recentColors = _ColorListNotifier(List.from(widget.initialRecentColors));\n  }\n\n  @override\n  List<Color> get recentColors =>\n      List.unmodifiable(_recentColors._recentColors);\n\n  /// Performs `addHistory` logic for this form component.\n  @override\n  void addHistory(Color color) {\n    var recentColors = _recentColors._recentColors;\n    if (recentColors.contains(color)) {\n      recentColors.remove(color);\n    }\n    recentColors.insert(0, color);\n    if (recentColors.length > widget.maxRecentColors) {\n      recentColors.removeLast();\n    }\n    widget.onRecentColorsChanged?.call(recentColors);\n    _recentColors._notify();\n  }\n\n  /// Releases resources owned by this state object.\n  @override\n  void dispose() {\n    super.dispose();\n    _recentColors.dispose();\n  }\n\n  /// Performs `clear` logic for this form component.\n  @override\n  void clear() {\n    _recentColors._recentColors.clear();\n    widget.onRecentColorsChanged?.call(recentColors);\n    _recentColors._notify();\n  }\n\n  /// Performs `setHistory` logic for this form component.\n  @override\n  void setHistory(List<Color> colors) {\n    _recentColors._recentColors = colors;\n    widget.onRecentColorsChanged?.call(recentColors);\n    _recentColors._notify();\n  }\n\n  /// Builds the widget tree for this component state.\n  @override\n  Widget build(BuildContext context) {\n    return ForwardableData<ColorHistoryStorage>(\n      data: this,\n      child: Data<ColorHistoryStorage>.inherit(data: this, child: widget.child),\n    );\n  }\n\n  /// Performs `addListener` logic for this form component.\n  @override\n  void addListener(VoidCallback listener) {\n    _recentColors.addListener(listener);\n  }\n\n  /// Performs `removeListener` logic for this form component.\n  @override\n  void removeListener(VoidCallback listener) {\n    _recentColors.removeListener(listener);\n  }\n}\n",
  "{installPath}/components/form/history/_impl/utils/_color_list_notifier.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../history.dart';\n\n/// _ColorListNotifier represents a form-related type in the registry.\nclass _ColorListNotifier extends ChangeNotifier {\n  /// Field storing `_recentColors` for this form implementation.\n  List<Color> _recentColors;\n\n  _ColorListNotifier(this._recentColors);\n\n  /// Performs `_notify` logic for this form component.\n  void _notify() {\n    notifyListeners();\n  }\n}\n",
  "{installPath}/components/form/history/history.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:data_widget/data_widget.dart';\nimport 'package:flutter/widgets.dart';\nimport 'package:gap/gap.dart';\n\nimport '../../utility/alpha/alpha.dart';\nimport '../../control/button/button.dart';\nimport '../../../shared/theme/theme.dart';\n\npart '_impl/utils/_color_list_notifier.dart';\npart '_impl/core/color_history_storage.dart';\npart '_impl/core/recent_colors_scope.dart';\npart '_impl/state/recent_colors_scope_state.dart';\n\n/// A grid widget that displays a history of previously used colors.\n///\n/// [ColorHistoryGrid] presents colors from a [ColorHistoryStorage] in a grid\n/// layout, allowing users to quickly reuse recently selected colors. The grid\n/// can highlight the currently selected color and supports custom layouts.\nclass ColorHistoryGrid extends StatelessWidget {\n  /// The storage containing the color history.\n  final ColorHistoryStorage storage;\n\n  /// Called when a color from the history is picked.\n  final ValueChanged<Color>? onColorPicked;\n\n  /// Spacing between grid items.\n  final double? spacing;\n\n  /// Number of columns in the grid.\n  final int crossAxisCount;\n\n  /// The currently selected color to highlight.\n  final Color? selectedColor;\n\n  /// The amount of colors to display in the history.\n  final int? maxTotalColors;\n\n  /// Creates a [ColorHistoryGrid].\n  const ColorHistoryGrid({\n    super.key,\n    required this.storage,\n    this.onColorPicked,\n    this.spacing,\n    this.crossAxisCount = 10,\n    this.selectedColor,\n    this.maxTotalColors,\n  });\n\n  /// Performs `_buildGridTile` logic for this form component.\n  Widget _buildGridTile(BuildContext context, Color? color, ThemeData theme) {\n    if (color == null) {\n      return const AspectRatio(\n        aspectRatio: 1,\n        child: Button(\n          style: ButtonStyle.outline(density: ButtonDensity.compact),\n          child: SizedBox.shrink(),\n        ),\n      );\n    }\n    return Container(\n      decoration: selectedColor != null && color == selectedColor\n          ? BoxDecoration(\n              border: Border.all(\n                color: theme.colorScheme.primary,\n                width: 2 * theme.scaling,\n              ),\n              borderRadius: BorderRadius.circular(theme.radiusMd),\n            )\n          : null,\n      child: AspectRatio(\n        aspectRatio: 1,\n        child: Button(\n          style: const ButtonStyle.outline(density: ButtonDensity.compact),\n          onPressed: () {\n            onColorPicked?.call(color);\n          },\n          child: Stack(\n            children: [\n              Positioned.fill(\n                top: selectedColor != null && color == selectedColor ? -2 : 0,\n                left: selectedColor != null && color == selectedColor ? -2 : 0,\n                child: ClipRRect(\n                  borderRadius: theme.borderRadiusSm,\n                  child: CustomPaint(painter: AlphaPainter()),\n                ),\n              ),\n              Positioned.fill(child: Container(color: color)),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  /// Builds the widget tree for this component state.\n  @override\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n    final spacing =\n        this.spacing ?? (theme.density.baseGap * theme.scaling * 0.5);\n    return ConstrainedBox(\n      constraints: const BoxConstraints(minHeight: 100),\n      child: ListenableBuilder(\n        listenable: storage,\n        builder: (context, child) {\n          List<Widget> rows = [];\n          for (\n            int i = 0;\n            i < storage.capacity &&\n                (maxTotalColors == null || i < maxTotalColors!);\n            i += crossAxisCount\n          ) {\n            List<Widget> tiles = [];\n            for (int j = 0; j < crossAxisCount; j++) {\n              final index = i + j;\n              final color = index < storage.recentColors.length\n                  ? storage.recentColors[index]\n                  : null;\n              if (index >= storage.capacity ||\n                  (maxTotalColors != null && index >= maxTotalColors!)) {\n                tiles.add(const Expanded(child: SizedBox()));\n              } else {\n                tiles.add(\n                  Expanded(\n                    child: SizedBox(\n                      width: 32 * theme.scaling,\n                      height: 32 * theme.scaling,\n                      child: _buildGridTile(context, color, theme),\n                    ),\n                  ),\n                );\n              }\n              if (j < crossAxisCount - 1) {\n                tiles.add(Gap(spacing));\n              }\n            }\n            rows.add(\n              IntrinsicHeight(\n                child: Row(\n                  crossAxisAlignment: CrossAxisAlignment.stretch,\n                  children: tiles,\n                ),\n              ),\n            );\n            if (i < storage.capacity - crossAxisCount) {\n              rows.add(Gap(spacing));\n            }\n          }\n          return IntrinsicWidth(\n            child: Column(\n              mainAxisSize: MainAxisSize.min,\n              crossAxisAlignment: CrossAxisAlignment.stretch,\n              children: rows,\n            ),\n          );\n        },\n      ),\n    );\n  }\n}\n",
  "{installPath}/components/form/hsl/_impl/core/hsl_color_slider_painter.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../hsl_color_slider.dart';\n\n/// A custom painter for rendering HSL color slider gradients.\n///\n/// [HSLColorSliderPainter] draws the gradient background for HSL color sliders,\n/// showing the range of possible colors for the selected slider type. The\n/// gradient updates based on the current color and slider configuration.\nclass HSLColorSliderPainter extends CustomPainter {\n  /// The type of slider being painted.\n  final HSLColorSliderType sliderType;\n\n  /// The current HSL color.\n  final HSLColor color;\n\n  /// Whether the gradient direction is reversed.\n  final bool reverse;\n\n  /// Creates an [HSLColorSliderPainter].\n  HSLColorSliderPainter({\n    required this.sliderType,\n    required this.color,\n    this.reverse = false,\n  });\n\n  /// Performs `paint` logic for this form component.\n  @override\n  void paint(Canvas canvas, Size size) {\n    // disable anti-aliasing\n    var pp = Paint();\n    pp.isAntiAlias = false;\n    pp.style = PaintingStyle.fill;\n    var canvasHeight = size.height;\n    var canvasWidth = size.width;\n    if (sliderType == HSLColorSliderType.hueSat) {\n      // if reverse, then its sat hue\n      if (reverse) {\n        double width = canvasWidth / 360;\n        double height = canvasHeight / 100;\n        // vertical for hue and horizontal for saturation\n        for (var i = 0; i < 360; i++) {\n          for (var j = 0; j < 100; j++) {\n            final result = HSLColor.fromAHSL(\n              1,\n              i.toDouble(),\n              j / 100,\n              color.lightness,\n            );\n            final paint = pp\n              ..color = result.toColor()\n              ..style = PaintingStyle.fill;\n            canvas.drawRect(\n              Rect.fromLTWH(i * width, j * height, width, height),\n              paint,\n            );\n          }\n        }\n      } else {\n        double width = canvasWidth / 100;\n        double height = canvasHeight / 360;\n        // horizontal for hue and vertical for saturation\n        for (var i = 0; i < 100; i++) {\n          for (var j = 0; j < 360; j++) {\n            final result = HSLColor.fromAHSL(\n              1,\n              j.toDouble(),\n              i / 100,\n              color.lightness,\n            );\n            final paint = pp\n              ..color = result.toColor()\n              ..style = PaintingStyle.fill;\n            canvas.drawRect(\n              Rect.fromLTWH(i * width, j * height, width, height),\n              paint,\n            );\n          }\n        }\n      }\n    } else if (sliderType == HSLColorSliderType.hueLum) {\n      // if reverse, then its lum hue\n      if (reverse) {\n        double width = canvasWidth / 360;\n        double height = canvasHeight / 100;\n        // vertical for hue and horizontal for lightness\n        for (var i = 0; i < 360; i++) {\n          for (var j = 0; j < 100; j++) {\n            final result = HSLColor.fromAHSL(\n              1,\n              i.toDouble(),\n              color.saturation,\n              j / 100.0,\n            );\n            final paint = pp\n              ..color = result.toColor()\n              ..style = PaintingStyle.fill;\n            canvas.drawRect(\n              Rect.fromLTWH(i * width, j * height, width, height),\n              paint,\n            );\n          }\n        }\n      } else {\n        double width = canvasWidth / 100;\n        double height = canvasHeight / 360;\n        // horizontal for hue and vertical for lightness\n        for (var i = 0; i < 100; i++) {\n          for (var j = 0; j < 360; j++) {\n            final result = HSLColor.fromAHSL(\n              1,\n              j.toDouble(),\n              color.saturation