  "{installPath}/components/form/hsv/hsv_color_slider.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:flutter/material.dart' show Colors;\nimport 'package:flutter/widgets.dart';\n\nimport '../../utility/alpha/alpha.dart';\nimport '../../../shared/theme/theme.dart';\n\npart '_impl/core/hsv_color_slider_type.dart';\n\npart '_impl/state/_hsv_color_slider_state.dart';\npart '_impl/core/hsv_color_slider_painter.dart';\n\n/// A slider widget for adjusting HSV color components.\n///\n/// [HSVColorSlider] provides an interactive slider for modifying different\n/// aspects of an HSV color (hue, saturation, value, and combinations).\n/// The slider displays a gradient representing the selected color channel(s)\n/// and allows users to drag to adjust values.\n///\n/// Example:\n/// ```dart\n/// HSVColorSlider(\n///   value: HSVColor.fromColor(Colors.blue),\n///   sliderType: HSVColorSliderType.hue,\n///   onChanged: (newColor) {\n///     print('New hue: \${newColor.hue}');\n///   },\n/// )\n/// ```\nclass HSVColorSlider extends StatefulWidget {\n  /// The current HSV color value.\n  final HSVColor value;\n\n  /// Called while the slider is being dragged.\n  final ValueChanged<HSVColor>? onChanging;\n\n  /// Called when the slider interaction is complete.\n  final ValueChanged<HSVColor>? onChanged;\n\n  /// The type of HSV component(s) this slider controls.\n  final HSVColorSliderType sliderType;\n\n  /// Whether to reverse the slider direction.\n  final bool reverse;\n\n  /// Corner radius for the slider.\n  final Radius radius;\n\n  /// Padding around the slider.\n  final EdgeInsets padding;\n\n  /// Creates an [HSVColorSlider].\n  const HSVColorSlider({\n    super.key,\n    required this.value,\n    this.onChanging,\n    this.onChanged,\n    required this.sliderType,\n    this.reverse = false,\n    this.radius = const Radius.circular(0),\n    this.padding = const EdgeInsets.all(0),\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  State<HSVColorSlider> createState() => _HSVColorSliderState();\n}\n",
  "{installPath}/components/form/input/_impl/core/input_above_below_feature.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// Adds a custom widget above or below the text input area.\n///\n/// Use this feature to place helper content directly above or below the field.\nclass InputAboveBelowFeature extends InputFeature {\n  /// Widget shown above or below the input.\n  final Widget? child;\n\n  /// Position of the [child] relative to the input.\n  final InputFeaturePosition position;\n\n  /// Creates an [InputAboveBelowFeature].\n  const InputAboveBelowFeature({\n    super.visibility,\n    super.skipFocusTraversal,\n    this.child,\n    this.position = InputFeaturePosition.below,\n  });\n\n  /// Creates an [InputAboveBelowFeature] above the input.\n  const InputAboveBelowFeature.above(\n    this.child, {\n    super.visibility,\n    super.skipFocusTraversal,\n  }) : position = InputFeaturePosition.above;\n\n  /// Creates an [InputAboveBelowFeature] below the input.\n  const InputAboveBelowFeature.below(\n    this.child, {\n    super.visibility,\n    super.skipFocusTraversal,\n  }) : position = InputFeaturePosition.below;\n\n  /// Creates the `State` object for this widget.\n  @override\n  InputFeatureState createState() => _InputAboveBelowFeatureState();\n}\n",
  "{installPath}/components/form/input/_impl/core/input_auto_complete_feature.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// Adds autocomplete functionality to the input field.\n///\n/// Displays a popover with suggestions as the user types. Suggestions are\n/// provided by the [querySuggestions] callback and can be selected to fill\n/// the input.\n///\n/// Example:\n/// ```dart\n/// TextField(\n///   features: [\n///     InputAutoCompleteFeature(\n///       querySuggestions: (query) async {\n///         return ['apple', 'apricot', 'avocado']\n///             .where((s) => s.startsWith(query));\n///       },\n///       child: const Text('Fruits'),\n///     ),\n///   ],\n/// )\n/// ```\nclass InputAutoCompleteFeature extends InputFeature {\n  /// Callback to provide suggestions for a given query.\n  final SuggestionBuilder querySuggestions;\n\n  /// Child widget displayed in the suggestion list.\n  final Widget child;\n\n  /// Constraints for the popover size.\n  final BoxConstraints? popoverConstraints;\n\n  /// Width constraint for the popover.\n  final PopoverConstraint? popoverWidthConstraint;\n\n  /// Anchor alignment for the popover.\n  final AlignmentDirectional? popoverAnchorAlignment;\n\n  /// Popover alignment relative to the anchor.\n  final AlignmentDirectional? popoverAlignment;\n\n  /// Autocomplete mode (e.g., popover or inline).\n  final AutoCompleteMode mode;\n\n  /// Creates an [InputAutoCompleteFeature].\n  ///\n  /// Parameters:\n  /// - [querySuggestions] (`SuggestionBuilder`, required): Provides suggestions.\n  /// - [child] (`Widget`, required): Content for suggestion items.\n  /// - [popoverConstraints] (`BoxConstraints?`, optional): Size constraints.\n  /// - [popoverWidthConstraint] (`PopoverConstraint?`, optional): Width constraint.\n  /// - [popoverAnchorAlignment] (`AlignmentDirectional?`, optional): Anchor alignment.\n  /// - [popoverAlignment] (`AlignmentDirectional?`, optional): Popover alignment.\n  /// - [mode] (`AutoCompleteMode`, required): Autocomplete display mode.\n  /// - [visibility] (`InputFeatureVisibility`, optional): Controls visibility.\n  /// - [skipFocusTraversal] (`bool`, optional): Whether to skip in focus order.\n  const InputAutoCompleteFeature({\n    super.visibility,\n    super.skipFocusTraversal,\n    required this.querySuggestions,\n    required this.child,\n    this.popoverConstraints,\n    this.popoverWidthConstraint,\n    this.popoverAnchorAlignment,\n    this.popoverAlignment,\n    this.mode = AutoCompleteMode.replaceWord,\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  InputFeatureState createState() => _AutoCompleteFeatureState();\n}\n",
