  "{installPath}/components/form/input/_impl/state/_input_copy_feature_state.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// _InputCopyFeatureState stores and manages mutable widget state.\nclass _InputCopyFeatureState extends InputFeatureState<InputCopyFeature> {\n  /// Performs `_copy` logic for this form component.\n  void _copy() {\n    Actions.invoke(context, const TextFieldSelectAllAndCopyIntent());\n  }\n\n  @override\n  Iterable<Widget> buildTrailing() sync* {\n    if (feature.position == InputFeaturePosition.trailing) {\n      yield IconButton.text(\n        icon: feature.icon ?? const Icon(LucideIcons.copy),\n        onPressed: _copy,\n        density: ButtonDensity.compact,\n      );\n    }\n  }\n\n  @override\n  Iterable<Widget> buildLeading() sync* {\n    if (feature.position == InputFeaturePosition.leading) {\n      yield IconButton.text(\n        icon: feature.icon ?? const Icon(LucideIcons.copy),\n        onPressed: _copy,\n        density: ButtonDensity.compact,\n      );\n    }\n  }\n}\n",
  "{installPath}/components/form/input/_impl/state/_input_hint_feature_state.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../input.dart';\n\n/// _InputHintFeatureState stores and manages mutable widget state.\nclass _InputHintFeatureState extends InputFeatureState<InputHintFeature> {\n  final _popoverController = PopoverController();\n\n  /// Performs `_showPopup` logic for this form component.\n  void _showPopup(BuildContext context) {\n    _popoverController.show(\n      context: context,\n      builder: feature.popupBuilder,\n      alignment: AlignmentDirectional.topCenter,\n      anchorAlignment: AlignmentDirectional.bottomCenter,\n    );\n  }\n\n  @override\n  Iterable<Widget> buildTrailing() sync* {\n    if (feature.position == InputFeaturePosition.trailing) {\n      yield Builder(\n        builder: (context) {\n          return IconButton.text(\n            icon: feature.icon ?? const Icon(LucideIcons.info),\n            onPressed: () => _showPopup(context),\n            density: ButtonDensity.compact,\n          );\n        },\n      );\n    }\n  }\n\n  @override\n  Iterable<Widget> buildLeading() sync* {\n    if (feature.position == InputFeaturePosition.leading) {\n      yield IconButton.text(\n        icon: feature.icon ?? const Icon(LucideIcons.info),\n        onPressed: () => _showPopup(context),\n        density: ButtonDensity.compact,\n      );\n    }\n  }\n\n  @override\n  Iterable<MapEntry<ShortcutActivator, Intent>> buildShortcuts() sync* {\n    if (feature.enableShortcuts) {\n      yield const MapEntry(\n        SingleActivator(LogicalKeyboardKey.f1),\n        InputShowHintIntent(),\n      );\n    }\n  }\n\n  @override\n  Iterable<MapEntry<Type, Action<Intent>>> buildActions() sync* {\n    if (feature.enableShortcuts) {\n      yield MapEntry(\n        InputShowHintIntent,\n        CallbackContextAction<InputShowHintIntent>(\n          onInvoke: (intent, [context]) {\n            if (context == null) {\n              throw FlutterError(\n                'CallbackContextAction was invoked without a valid BuildContext. '\n                'This likely indicates a problem in the action system. '\n                'Context must not be null when invoking InputShowHintIntent.',\n              );\n            }\n            _showPopup(context);\n            return true;\n          },\n        ),\n      );\n    }\n  }\n}\n",
