s/select_controller.dart';\npart '_impl/core/select_data.dart';\npart '_impl/core/select_group.dart';\npart '_impl/core/select_item.dart';\npart '_impl/utils/select_item_builder.dart';\npart '_impl/core/select_item_button.dart';\npart '_impl/utils/select_item_delegate.dart';\npart '_impl/core/select_item_list.dart';\npart '_impl/core/select_label.dart';\npart '_impl/core/select_popup.dart';\npart '_impl/core/select_popup_handle.dart';\npart '_impl/state/select_state.dart';\n\n/// Builder function for select popup content.\n///\n/// Returns the widget tree for the dropdown/popup menu.\ntypedef SelectPopupBuilder = Widget Function(BuildContext context);\n\n/// Builder function for rendering selected values.\n///\n/// Parameters:\n/// - [context] (`BuildContext`): Build context.\n/// - [value] (`T`): The selected value.\n///\n/// Returns: Widget representation of the value.\ntypedef SelectValueBuilder<T> = Widget Function(BuildContext context, T value);\n\n/// Handler for custom selection logic.\n///\n/// Parameters:\n/// - [oldValue] (`T?`): Previous selection.\n/// - [value] (`Object?`): Newly selected item.\n/// - [selected] (`bool`): Whether item is being selected (true) or deselected (false).\n///\n/// Returns: `T?` — the new selection state.\ntypedef SelectValueSelectionHandler<T> =\n    T? Function(T? oldValue, Object? value, bool selected);\n\n/// Predicate for testing value selection state.\n///\n/// Parameters:\n/// - [value] (`T?`): Current selection.\n/// - [test] (`Object?`): Value to test against.\n///\n/// Returns: `bool` — true if test matches selection.\ntypedef SelectValueSelectionPredicate<T> =\n    bool Function(T? value, Object? test);\n\nT? _defaultSingleSelectValueSelectionHandler<T>(\n  T? oldValue,\n  Object? value,\n  bool selected,\n) {\n  if (value is! T?) {\n    return null;\n  }\n  return selected ? value : null;\n}\n\nbool _defaultSingleSelectValueSelectionPredicate<T>(T? value, Object? test) {\n  return value == test;\n}\n\nIterable<T>? _defaultMultiSelectValueSelectionHandler<T>(\n  Iterable<T>? oldValue,\n  Object? newValue,\n  bool selected,\n) {\n  if (newValue == null) {\n    return null;\n  }\n  Iterable<T> wrappedNewValue = [newValue as T];\n  if (oldValue == null) {\n    return selected ? wrappedNewValue : null;\n  }\n  if (selected) {\n    return oldValue.followedBy(wrappedNewValue);\n  } else {\n    var newIterable = oldValue.where((element) => element != newValue);\n    return newIterable.isEmpty ? null : newIterable;\n  }\n}\n\nbool _defaultMultiSelectValueSelectionPredicate<T>(\n  Iterable<T>? value,\n  Object? test,\n) {\n  if (value == null) {\n    return test == null;\n  }\n  if (test == null) {\n    return false;\n  }\n  return value.contains(test);\n}\n\n/// A customizable dropdown selection widget for single-value selection.\n///\n/// [Select] provides a comprehensive dropdown selection experience with support for\n/// custom item rendering, keyboard navigation, search functionality, and extensive\n/// customization options. It displays a trigger button that opens a popup containing\n/// selectable options when activated.\n///\n/// Key features:\n/// - Single-value selection with optional null/unselect capability\n/// - Customizable item rendering through builder functions\n/// - Keyboard navigation and accessibility support\n/// - Configurable popup positioning and constraints\n/// - Search and filtering capabilities\n/// - Focus management and interaction handling\n/// - Theming and visual customization\n/// - Form integration and validation support\n///\n/// The widget supports various configuration modes:\n/// - Filled or outlined appearance styles\n/// - Custom popup positioning and alignment\n/// - Conditional item visibility and selection\n/// - Hover effects and interaction feedback\n/// - Auto-closing popup behavior\n///\n/// Selection behavior can be customized through:\n/// - [valueSelectionHandler]: Custom logic for handling selection\n/// - [valueSelectionPredicate]: Conditions for allowing selection\n/// - [showValuePredicate]: Conditions for displaying items\n/// - [canUnselect]: Whether to allow deselecting the current value\n///\n/// Example:\n/// ```dart\n/// Select<String>(\n///   value: selectedItem,\n///   placeholder: Text('Choose an option'),\n///   onChanged: (value) => setState(() => selectedItem = value),\n///   popup: SelectPopup.menu(\n///     children: [\n///       SelectItem(value: 'option1', child: Text('Option 1')),\n///       SelectItem(value: 'option2', child: Text('Option 2')),\n///       SelectItem(value: 'option3', child: Text('Option 3')),\n///     ],\n///   ),\n/// );\n/// ```\nclass Select<T> extends StatefulWidget with SelectBase<T> {\n  /// Default maximum height for select popups in logical pixels.\n  static const kDefaultSelectMaxHeight = 240.0;\n  @override\n  final ValueChanged<T?>? onChanged; // if null, then it's a disabled combobox\n  @override\n  final Widget? placeholder; // placeholder when value is null\n  /// Field storing `filled` for this form implementation.\n  @override\n  final bool filled;\n\n  /// Focus node/reference used by `focusNode` interactions.\n  @override\n  final FocusNode? focusNode;\n\n  /// Field storing `constraints` for this form implementation.\n  @override\n  final BoxConstraints? constraints;\n\n  /// Field storing `popupConstraints` for this form implementation.\n  @override\n  final BoxConstraints? popupConstraints;\n\n  /// Field storing `popupWidthConstraint` for this form implementation.\n  @override\n  final PopoverConstraint popupWidthConstraint;\n\n  /// The currently selected value.\n  final T? value;\n\n  /// Field storing `borderRadius` for this form implementation.\n  @override\n  final BorderRadiusGeometry? borderRadius;\n\n  /// Field storing `padding` for this form implementation.\n  @override\n  final EdgeInsetsGeometry? padding;\n\n  /// Field storing `popoverAlignment` for this form implementation.\n  @override\n  final AlignmentGeometry popoverAlignment;\n\n  /// Field storing `popoverAnchorAlignment` for this form implementation.\n  @override\n  final AlignmentGeometry? popoverAnchorAlignment;\n\n  /// Field storing `disableHoverEffect` for this form implementation.\n  @override\n  final bool disableHoverEffect;\n\n  /// Field storing `canUnselect` for this form implementation.\n  @override\n  final bool canUnselect;\n\n  /// Field storing `autoClosePopover` for this form implementation.\n  @override\n  final bool? autoClosePopover;\n\n  /// Whether the select is enabled for user interaction.\n  final bool? enabled;\n\n  /// Field storing `popup` for this form implementation.\n  @override\n  final SelectPopupBuilder popup;\n\n  /// Field storing `itemBuilder` for this form implementation.\n  @override\n  final SelectValueBuilder<T> itemBuilder;\n\n  /// Current value stored for `valueSelectionHandler`.\n  @override\n  final SelectValueSelectionHandler<T>? valueSelectionHandler;\n\n  /// Current value stored for `valueSelectionPredicate`.\n  @override\n  final SelectValueSelectionPredicate<T>? valueSelectionPredicate;\n\n  /// Current value stored for `showValuePredicate`.\n  @override\n  final Predicate<T>? showValuePredicate;\n\n  /// Creates a single-selection dropdown widget.\n  ///\n  /// The [popup] and [itemBuilder] parameters are required to define the\n  /// dropdown content and how selected values are displayed.\n  ///\n  /// Parameters:\n  /// - [key] (Key?): Widget key for controlling widget identity\n  /// - [onChanged] (`ValueChanged<T?>?`): Callback when selection changes; if null, select is disabled\n  /// - [placeholder] (Widget?): Widget shown when no value is selected\n  /// - [filled] (bool): Whether to use filled background style, defaults to false\n  /// - [focusNode] (FocusNode?): Focus node for keyboard interaction\n  /// - [constraints] (BoxConstraints?): Size constraints for the select button\n  /// - [popupConstraints] (BoxConstraints?): Size constraints for the popup menu\n  /// - [popupWidthConstraint] (PopoverConstraint): Width constraint mode for popup, defaults to `PopoverConstraint.anchorFixedSize`\n  /// - [value] (T?): Currently selected value\n  /// - [disableHoverEffect] (bool): Whether to disable hover visual feedback, defaults to false\n  /// - [borderRadius] (BorderRadiusGeometry?): Custom border radius\n  /// - [padding] (EdgeInsetsGeometry?): Custom padding\n  /// - [popoverAlignment] (AlignmentGeometry): Popup alignment, defaults to `Alignment.topCenter`\n  /// - [popoverAnchorAlignment] (AlignmentGeometry?): Anchor alignment for popup positioning\n  /// - [canUnselect] (bool): Whether user can deselect current value, defaults to false\n  /// - [autoClosePopover] (bool?): Whether popup closes after selection, defaults to true\n  /// - [enabled] (bool?): Whether select is enabled for interaction\n  /// - [valueSelectionHandler] (`SelectValueSelectionHandler<T>?`): Custom selection logic\n  /// - [valueSelectionPredicate] (`SelectValueSelectionPredicate<T>?`): Predicate for allowing selection\n  /// - [showValuePredicate] (`Predicate<T>?`): Predicate for showing items\n  /// - [popup] (SelectPopupBuilder): Required builder for popup content\n  /// - [itemBuilder] (`SelectValueBuilder<T>`): Required builder for selected value display\n  const Select({\n    super.key,\n    this.onChanged,\n    this.placeholder,\n    this.filled = false,\n    this.focusNode,\n    this.constraints,\n    this.popupConstraints,\n    this.popupWidthConstraint = PopoverConstraint.anchorFixedSize,\n    this.value,\n    this.disableHoverEffect = false,\n    this.borderRadius,\n    this.padding,\n    this.popoverAlignment = Alignment.topCenter,\n    this.popoverAnchorAlignment,\n    this.canUnselect = false,\n    this.autoClosePopover = true,\n    this.enabled,\n    this.valueSelectionHandler,\n    this.valueSelectionPredicate,\n    this.showValuePredicate,\n    required this.popup,\n    required this.itemBuilder,\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  SelectState<T> createState() => SelectState<T>();\n}\n\n/// Callback type for handling selection changes in select components.\n///\n/// Returns true if the change was successful, false otherwise.\ntypedef SelectValueChanged<T> = bool Function(T value, bool selected);\n\n/// Builder function type for creating select item delegates.\n///\n/// Takes the build context and optional search query, returns a delegate\n/// for rendering select items.\ntypedef SelectItemsBuilder<T> =\n    FutureOr<SelectItemDelegate> Function(\n      BuildContext context,\n      String? searchQuery,\n    );\n\n/// Builder function type for creating select item widgets.\n///\n/// Takes the build context and item index, returns the widget for that item.\ntypedef SelectItemWidgetBuilder =\n    Widget Function(BuildContext context, int index);\n",
  "{installPath}/components/form/slider/_impl/core/shad_slider_logic.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'dart:math' as math;\n\nimport 'package:flutter/material.dart';\n\nimport 'shad_slider_models.dart';\n\n/// Geometry and interaction logic for the registry slider.\nclass ShadSliderLogic {\n  /// Builds a render-state snapshot from configuration and current value.\n  ///\n  /// [thumbEdgeOffsetPx] controls horizontal thumb placement:\n  /// - `0`: fully inside-track mapping\n  /// - positive: pushes thumbs toward/outside edges\n  /// - negative: pulls thumbs further inward\n  ///\n  /// [thumbVerticalOffsetPx] controls vertical thumb center offset:\n  /// - positive: down\n  /// - negative: up\n  ShadSliderStateView buildView({\n    required double min,\n    required double max,\n    required ShadSnap snap,\n    required bool enabled,\n    required Rect trackRect,\n    required double trackRadius,\n    required double thumbInset,\n    required bool dragging,\n    required int? activeThumb,\n    required bool fillStopsAtThumbCenter,\n    required double fillEdgeBiasPx,\n    required double joinGapPx,\n    required double thumbEdgeOffsetPx,\n    required double thumbVerticalOffsetPx,\n    required ShadSegmentLayout segmentLayout,\n    required TextDirection textDirection,\n    required double? value,\n    required ShadRangeValue? rangeValue,\n    required Size thumbSize,\n  }) {\n    final isRange = rangeValue != null;\n    final baseInsideInset = math.max(thumbInset, thumbSize.width / 2);\n    final centerInset = (baseInsideInset - thumbEdgeOffsetPx).clamp(\n      0.0,\n      trackRect.width / 2,\n    );\n    final minCenterX = trackRect.left + centerInset;\n    final maxCenterX = trackRect.right - centerInset;\n    final usableW = math.max(0.0, maxCenterX - minCenterX);\n\n    double dxForT(double t) {\n      if (textDirection == TextDirection.rtl) {\n        return maxCenterX - usableW * t;\n      }\n      return minCenterX + usableW * t;\n    }\n\n    double tForValue(double v) {\n      final range = max - min;\n      if (range == 0) return 0;\n      return ((v - min) / range).clamp(0.0, 1.0);\n    }\n\n    List<ShadThumbStateView> thumbs = [];\n    double? tSingle;\n    double? t0;\n    double? t1;\n    double? vSingle = value?.clamp(min, max);\n    ShadRangeValue? rv = rangeValue;\n\n    if (!isRange) {\n      final v = vSingle ?? min;\n      final t = tForValue(v);\n      tSingle = t;\n      const eps = 0.005;\n      final nearMin = t <= eps;\n      final nearMax = t >= 1.0 - eps;\n\n      final rawCx = dxForT(t);\n      final cx = nearMin\n          ? minCenterX\n          : nearMax\n          ? maxCenterX\n          : rawCx;\n      final center = Offset(cx, trackRect.center.dy + thumbVerticalOffsetPx);\n\n      thumbs = [\n        ShadThumbStateView(\n          index: 0,\n          value: v,\n          t: t,\n          center: center,\n          size: thumbSize,\n          active: (activeThumb ?? 0) == 0 && dragging,\n          enabled: enabled,\n        ),\n      ];\n    } else {\n      rv = _normalizeRange(rv!, min, max);\n      final tStart = tForValue(rv.start);\n      final tEnd = tForValue(rv.end);\n      t0 = tStart;\n      t1 = tEnd;\n      const eps = 0.005;\n      final leftAtMin = tStart <= eps;\n      final rightAtMax = tEnd >= 1.0 - eps;\n\n      final rawCx0 = dxForT(tStart);\n      final rawCx1 = dxForT(tEnd);\n      final cx0 = leftAtMin ? minCenterX : rawCx0;\n      final cx1 = rightAtMax ? maxCenterX : rawCx1;\n\n      thumbs = [\n        ShadThumbStateView(\n          index: 0,\n          value: rv.start,\n          t: tStart,\n          center: Offset(cx0, trackRect.center.dy + thumbVerticalOffsetPx),\n          size: thumbSize,\n          active: activeThumb == 0 && dragging,\n          enabled: enabled,\n        ),\n        ShadThumbStateView(\n          index: 1,\n          value: rv.end,\n          t: tEnd,\n          center: Offset(cx1, trackRect.center.dy + thumbVerticalOffsetPx),\n          size: thumbSize,\n          active: activeThumb == 1 && dragging,\n          enabled: enabled,\n        ),\n      ];\n    }\n\n    final segments = segmentLayout.buildSegments(\n      trackRect: trackRect,\n      trackRadius: trackRadius,\n      textDirection: textDirection,\n      isRange: isRange,\n      min: min,\n      max: max,\n      value: vSingle,\n      rangeValue: rv,\n      thumbs: thumbs,\n    );\n\n    Rect? firstOf(ShadSegmentKind kind) {\n      for (final segment in segments) {\n        if (segment.kind == kind) return segment.rect;\n      }\n      return null;\n    }\n\n    Rect? nthOf(ShadSegmentKind kind, int index) {\n      var found = 0;\n      for (final segment in segments) {\n        if (segment.kind != kind) continue;\n        if (found == index) return segment.rect;\n        found++;\n      }\n      return null;\n    }\n\n    final activeRect = firstOf(ShadSegmentKind.fill);\n    final remainingRect = isRange ? null : firstOf(ShadSegmentKind.remaining);\n    final rangeRect = isRange ? firstOf(ShadSegmentKind.fill) : null;\n    final leftGapRect = firstOf(ShadSegmentKind.gap);\n    final rightGapRect = nthOf(ShadSegmentKind.gap, 1);\n    final leftRemainingRect = isRange\n        ? firstOf(ShadSegmentKind.remaining)\n        : null;\n    final rightRemainingRect = isRange\n        ? nthOf(ShadSegmentKind.remaining, 1)\n        : null;\n\n    final marks = _defaultMarks(\n      min: min,\n      max: max,\n      snap: snap,\n      trackRect: trackRect,\n      thumbInset: centerInset,\n      textDirection: textDirection,\n    );\n\n    return ShadSliderStateView(\n      min: min,\n      max: max,\n      enabled: enabled,\n      dragging: dragging,\n      activeThumb: activeThumb,\n      textDirection: textDirection,\n      trackRect: trackRect,\n      trackRadius: trackRadius,\n      thumbInset: centerInset,\n      isRange: isRange,\n      value: vSingle,\n      rangeValue: rv,\n      t: tSingle,\n      t0: t0,\n      t1: t1,\n      activeRect: activeRect,\n      remainingRect: remainingRect,\n      rangeRect: rangeRect,\n      leftGapRect: leftGapRect,\n      rightGapRect: rightGapRect,\n      leftRemainingRect: leftRemainingRect,\n      rightRemainingRect: rightRemainingRect,\n      segments: segments,\n      thumbs: thumbs,\n      marks: marks,\n    );\n  }\n\n  ShadHitResult hitTest({\n    required ShadSliderStateView view,\n    required Offset localPosition,\n  }) {\n    if (!view.isRange) return const ShadHitResult(activeThumb: 0);\n    return ShadHitResult(\n      activeThumb: pickActiveThumb(view: view, dx: localPosition.dx),\n    );\n  }\n\n  int pickActiveThumb({required ShadSliderStateView view, required double dx}) {\n    if (!view.isRange) return 0;\n    final d0 = (dx - view.thumbs[0].center.dx).abs();\n    final d1 = (dx - view.thumbs[1].center.dx).abs();\n    return d0 <= d1 ? 0 : 1;\n  }\n\n  /// Computes updated value/range for a pointer x-position.\n  ShadUpdateResult updateFromDx({\n    required ShadSliderStateView view,\n    required ShadSnap snap,\n    required double dx,\n    required int thumbIndex,\n  }) {\n    final min = view.min;\n    final max = view.max;\n\n    final t = _dxToT(dx, view);\n    final vRaw = _tToValue(t, min, max);\n    final v = _applySnap(vRaw, snap, min, max);\n\n    if (!view.isRange) return ShadUpdateResult(singleValue: v);\n\n    final rv = view.rangeValue!;\n    final start = rv.start;\n    final end = rv.end;\n\n    if (thumbIndex == 0) {\n      double ns = v;\n      double ne = end;\n      if (!rv.allowSwap) {\n        ns = math.min(ns, ne - rv.minRange);\n      } else if (ns > ne) {\n        ns = ne;\n        ne = v;\n      }\n      return ShadUpdateResult(\n        rangeValue: _normalizeRange(\n          ShadRangeValue(\n            ns,\n            ne,\n            minRange: rv.minRange,\n            allowSwap: rv.allowSwap,\n          ),\n          min,\n          max,\n        ),\n      );\n    } else {\n      double ns = start;\n      double ne = v;\n      if (!rv.allowSwap) {\n        ne = math.max(ne, ns + rv.minRange);\n      } else if (ne < ns) {\n        ne = ns;\n        ns = v;\n      }\n      return ShadUpdateResult(\n        rangeValue: _normalizeRange(\n          ShadRangeValue(\n            ns,\n            ne,\n            minRange: rv.minRange,\n            allowSwap: rv.allowSwap,\n          ),\n          min,\n          max,\n        ),\n      );\n    }\n  }\n\n  double _dxToT(double dx, ShadSliderStateView view) {\n    final w = view.trackRect.width;\n    final inset = view.thumbInset;\n    final usableW = math.max(0.0, w - inset * 2);\n    final x = view.textDirection == TextDirection.rtl ? (w - dx) : dx;\n    if (usableW == 0) return 0;\n    return ((x - inset) / usableW).clamp(0.0, 1.0);\n  }\n\n  double _tToValue(double t, double min, double max) => min + (max - min) * t;\n\n  ShadRangeValue _normalizeRange(ShadRangeValue rv, double min, double max) {\n    final s = rv.start.clamp(min, max);\n    final e = rv.end.clamp(min, max);\n    if (!rv.allowSwap) {\n      final s2 = math.min(s, e);\n      final e2 = math.max(e, s2 + rv.minRange).clamp(min, max);\n      return rv.copyWith(start: s2, end: e2);\n    }\n    return rv.copyWith(start: s, end: e);\n  }\n\n  double _applySnap(double v, ShadSnap snap, double min, double max) {\n    if (snap is ShadSnapNone) return v.clamp(min, max);\n    if (snap is ShadSnapSteps) {\n      final steps = snap.steps;\n      if ((max - min).abs() < 1e-9) return min;\n      final t = ((v - min) / (max - min)).clamp(0.0, 1.0);\n      final qt = (t * steps).round() / steps;\n      return (min + (max - min) * qt).clamp(min, max);\n    }\n    if (snap is ShadSnapValues) {\n      double best = snap.values.first;\n      double bd = (v - best).abs();\n      for (final x in snap.values.skip(1)) {\n        final d = (v - x).abs();\n        if (d < bd) {\n          bd = d;\n          best = x;\n        }\n      }\n      return best.clamp(min, max);\n    }\n    return v.clamp(min, max);\n  }\n\n  List<ShadMarkLayout> _defaultMarks({\n    required double min,\n    required double max,\n    required ShadSnap snap,\n    required Rect trackRect,\n    required double thumbInset,\n    required TextDirection textDirection,\n  }) {\n    final w = trackRect.width;\n    final usableW = math.max(0.0, w - thumbInset * 2);\n\n    double xForT(double t) {\n      final x = thumbInset + usableW * t;\n      return textDirection == TextDirection.rtl ? (w - x) : x;\n    }\n\n    if (snap is ShadSnapSteps) {\n      final n = snap.steps;\n      return List.generate(n + 1, (i) {\n        final t = i / n;\n        final v = min + (max - min) * t;\n        return ShadMarkLayout(value: v, t: t, x: xForT(t));\n      });\n    }\n    if (snap is ShadSnapValues) {\n      final out = snap.values.map((v) {\n        final t = ((v - min) / (max - min)).clamp(0.0, 1.0);\n        return ShadMarkLayout(value: v, t: t, x: xForT(t));\n      }).toList();\n      out.sort((a, b) => a.t.compareTo(b.t));\n      return out;\n    }\n    return const <ShadMarkLayout>[];\n  }\n}\n",
  "{installPath}/components/form/slider/_impl/core/shad_slider_models.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'dart:math' as math;\n\nimport 'package:flutter/material.dart';\n\n/// Builds the base track layer for the current slider state.\ntypedef ShadTrackBuilder =\n    Widget Function(BuildContext context, ShadSliderStateView state);\n\n/// Builds active/remaining fill layers for the current slider state.\ntypedef ShadFillBuilder =\n    Widget Function(BuildContext context, ShadSliderStateView state);\n\n/// Builds a single thumb widget from a thumb state snapshot.\ntypedef ShadThumbBuilder =\n    Widget Function(BuildContext context, ShadThumbStateView thumb);\n\n/// Builds ticks/marks layer.\ntypedef ShadTicksBuilder =\n    Widget Function(BuildContext context, ShadSliderStateView state);\n\n/// Builds optional overlay layer above thumbs.\ntypedef ShadOverlayBuilder =\n    Widget Function(BuildContext context, ShadSliderStateView state);\n\n/// Data payload for generic slider popover builders.\nclass ShadPopoverData {\n  const ShadPopoverData({\n    /// Denormalized value in active slider units.\n    required this.value,\n\n    /// Normalized progress in `[0..1]`.\n    required this.normalizedValue,\n\n    /// True while gesture drag is active.\n    this.isDragging = false,\n\n    /// Active thumb index when slider has multiple thumbs.\n    this.thumbIndex,\n\n    /// Full computed slider view when available.\n    this.state,\n\n    /// Active thumb snapshot when available.\n    this.thumb,\n\n    /// Arbitrary extension payload for custom slider variants.\n    this.meta = const <String, Object?>{},\n  });\n\n  /// Denormalized value in the active slider domain.\n  final double value;\n\n  /// Normalized progress value in `[0..1]`.\n  final double normalizedValue;\n\n  /// Whether pointer drag is cu