l double min;\n\n  /// Upper domain bound.\n  final double max;\n\n  /// Whether interactions are enabled.\n  final bool enabled;\n\n  /// Whether drag gesture is active.\n  final bool dragging;\n\n  /// Active thumb index when dragging.\n  final int? activeThumb;\n\n  /// Layout direction used for geometry.\n  final TextDirection textDirection;\n\n  /// Track layout rect in the slider canvas.\n  final Rect trackRect;\n\n  /// Track corner radius used by renderers.\n  final double trackRadius;\n\n  /// Effective horizontal inset used by value<->pixel mapping.\n  final double thumbInset;\n\n  /// Whether this state is for range mode.\n  final bool isRange;\n\n  /// Single value in single mode.\n  final double? value;\n\n  /// Range value in range mode.\n  final ShadRangeValue? rangeValue;\n\n  /// Normalized single value in `[0..1]`.\n  final double? t;\n\n  /// Normalized range start in `[0..1]`.\n  final double? t0;\n\n  /// Normalized range end in `[0..1]`.\n  final double? t1;\n\n  /// Single-value active segment.\n  final Rect? activeRect;\n\n  /// Single-value remaining segment.\n  final Rect? remainingRect;\n\n  /// Selected segment for range sliders.\n  final Rect? rangeRect;\n\n  /// Gap around left/single thumb.\n  final Rect? leftGapRect;\n\n  /// Gap around right thumb in range mode.\n  final Rect? rightGapRect;\n\n  /// Left remaining segment in range mode.\n  final Rect? leftRemainingRect;\n\n  /// Right remaining segment in range mode.\n  final Rect? rightRemainingRect;\n\n  /// Canonical segment model for rendering.\n  final List<ShadSegment> segments;\n\n  /// Computed thumb snapshots for rendering/hit testing.\n  final List<ShadThumbStateView> thumbs;\n\n  /// Computed mark/tick layout entries.\n  final List<ShadMarkLayout> marks;\n}\n\n/// Immutable layout/state snapshot for one thumb.\nclass ShadThumbStateView {\n  const ShadThumbStateView({\n    /// Thumb index in rendering order.\n    required this.index,\n\n    /// Denormalized thumb value.\n    required this.value,\n\n    /// Normalized thumb value in `[0..1]`.\n    required this.t,\n\n    /// Thumb center in canvas coordinates.\n    required this.center,\n\n    /// Thumb layout size.\n    required this.size,\n\n    /// Whether this thumb is currently active.\n    required this.active,\n\n    /// Whether slider is enabled.\n    required this.enabled,\n  });\n\n  /// Thumb index in rendering order.\n  final int index;\n\n  /// Denormalized thumb value.\n  final double value;\n\n  /// Normalized value in `[0..1]`.\n  final double t;\n\n  /// Thumb center point in slider canvas coordinates.\n  final Offset center;\n\n  /// Logical size used for layout and gesture hit area.\n  final Size size;\n\n  /// Whether this thumb is currently active.\n  final bool active;\n\n  /// Whether slider interactions are enabled.\n  final bool enabled;\n}\n\n/// Mark/tick layout entry.\nclass ShadMarkLayout {\n  const ShadMarkLayout({\n    /// Denormalized mark value.\n    required this.value,\n\n    /// Normalized mark value in `[0..1]`.\n    required this.t,\n\n    /// Horizontal canvas position.\n    required this.x,\n\n    /// Optional text label rendered by custom ticks.\n    this.label,\n\n    /// Whether mark should be treated as major.\n    this.isMajor = true,\n  });\n\n  /// Denormalized mark value.\n  final double value;\n\n  /// Normalized value in `[0..1]`.\n  final double t;\n\n  /// Horizontal position in canvas coordinates.\n  final double x;\n\n  /// Optional label.\n  final String? label;\n\n  /// Major/minor flag for custom tick styling.\n  final bool isMajor;\n}\n\n/// Output model for drag/tap update calculations.\nclass ShadUpdateResult {\n  const ShadUpdateResult({\n    /// Resolved single value when single mode updates.\n    this.singleValue,\n\n    /// Resolved range value when range mode updates.\n    this.rangeValue,\n  });\n\n  /// Resolved single value output.\n  final double? singleValue;\n\n  /// Resolved range value output.\n  final ShadRangeValue? rangeValue;\n}\n\n/// Output model for hit-testing which thumb is active.\nclass ShadHitResult {\n  const ShadHitResult({\n    /// Thumb index selected by hit testing.\n    required this.activeThumb,\n  });\n\n  /// Thumb index selected by hit testing.\n  final int? activeThumb;\n}\n",
  "{installPath}/components/form/slider/_impl/core/shad_slider_renderers.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'dart:math' as math;\n\nimport 'package:flutter/material.dart' hide SliderTheme, Theme;\n\nimport '../../../../../shared/theme/theme.dart';\nimport '../themes/base/slider_theme.dart';\nimport 'shad_slider_models.dart';\n\n/// Unified rendering contract for slider track layers.\nabstract class ShadTrackRenderer {\n  const ShadTrackRenderer();\n\n  /// Builds visual layers for the provided computed slider [view].\n  Widget build(BuildContext context, ShadSliderStateView view);\n}\n\n/// Adapter that renders legacy `track/fill/ticks` builders in order.\nclass ShadLegacyBuildersRenderer extends ShadTrackRenderer {\n  const ShadLegacyBuildersRenderer({\n    /// Base track layer builder.\n    required this.trackBuilder,\n\n    /// Active/remaining fill layer builder.\n    required this.fillBuilder,\n\n    /// Tick/mark layer builder.\n    required this.ticksBuilder,\n  });\n\n  /// Base track layer builder.\n  final ShadTrackBuilder trackBuilder;\n\n  /// Fill layer builder.\n  final ShadFillBuilder fillBuilder;\n\n  /// Tick layer builder.\n  final ShadTicksBuilder ticksBuilder;\n\n  /// Builds layers in legacy order: track, fill, then ticks.\n  @override\n  Widget build(BuildContext context, ShadSliderStateView view) {\n    return Stack(\n      clipBehavior: Clip.none,\n      children: [\n        trackBuilder(context, view),\n        fillBuilder(context, view),\n        ticksBuilder(context, view),\n      ],\n    );\n  }\n}\n\n/// Default segmented renderer that draws each [ShadSegment] as a capsule.\nclass ShadSegmentedCapsuleRenderer extends ShadTrackRenderer {\n  const ShadSegmentedCapsuleRenderer({\n    /// Optional per-segment style resolver.\n    ///\n    /// If null, renderer uses theme-aware defaults by segment kind.\n    this.styleResolver,\n  });\n\n  /// Optional style resolver for custom segment colors/borders/radii.\n  final ShadSegmentStyleResolver? styleResolver;\n\n  /// Builds styled segments using resolver or theme defaults.\n  @override\n  Widget build(BuildContext context, ShadSliderStateView view) {\n    final cs = Theme.of(context).colorScheme;\n    final compTheme = ComponentTheme.maybeOf<SliderTheme>(context);\n\n    ShadSegmentStyle resolve(ShadSegment s) {\n      if (styleResolver != null) return styleResolver!(context, view, s);\n      switch (s.kind) {\n        case ShadSegmentKind.fill:\n          return ShadSegmentStyle(\n            color: compTheme?.fillActiveColor ?? cs.primary,\n            radius: s.radius,\n          );\n        case ShadSegmentKind.remaining:\n          return ShadSegmentStyle(\n            color: compTheme?.fillInactiveColor ?? cs.muted,\n            radius: s.radius,\n          );\n        case ShadSegmentKind.gap:\n          return const ShadSegmentStyle(color: Colors.transparent);\n        case ShadSegmentKind.disabled:\n          return ShadSegmentStyle(\n            color: (compTheme?.fillInactiveColor ?? cs.muted).withOpacity(0.5),\n            radius: s.radius,\n          );\n        case ShadSegmentKind.custom:\n          return ShadSegmentStyle(color: cs.muted, radius: s.radius);\n      }\n    }\n\n    final ordered = [...view.segments]\n      ..sort((a, b) => a.paintOrder.compareTo(b.paintOrder));\n\n    return Stack(\n      clipBehavior: Clip.none,\n      children: [\n        for (final s in ordered)\n          if (s.rect.width > 0)\n            Positioned.fromRect(\n              rect: s.rect,\n              child: Builder(\n                builder: (context) {\n                  final style = resolve(s);\n                  final opacity = style.opacity ?? 1.0;\n                  return Opacity(\n                    opacity: opacity,\n                    child: DecoratedBox(\n                      decoration: BoxDecoration(\n                        color: style.color,\n                        gradient: style.gradient,\n                        border: style.border,\n                        borderRadius:\n                            style.radius ?? s.radius ?? BorderRadius.zero,\n                      ),\n                    ),\n                  );\n                },\n              ),\n            ),\n      ],\n    );\n  }\n}\n\n/// Renderer that adds step dots on top of a base segmented track.\nclass ShadStepDotsRenderer extends ShadTrackRenderer {\n  const ShadStepDotsRenderer({\n    /// Base renderer used before dots are painted.\n    ///\n    /// Use this to swap the underlying segment style.\n    this.base = const ShadSegmentedCapsuleRenderer(),\n  });\n\n  /// Base renderer for non-dot layers.\n  final ShadTrackRenderer base;\n\n  /// Builds base layers first, then paints progress-aware dots.\n  @override\n  Widget build(BuildContext context, ShadSliderStateView view) {\n    final cs = Theme.of(context).colorScheme;\n    final compTheme = ComponentTheme.maybeOf<SliderTheme>(context);\n    final active =\n        compTheme?.dotsActiveColor ?? cs.foreground.withOpacity(0.18);\n    final inactive =\n        compTheme?.dotsInactiveColor ?? cs.foreground.withOpacity(0.08);\n    final activeT = view.t ?? 0;\n\n    return Stack(\n      clipBehavior: Clip.none,\n      children: [\n        base.build(context, view),\n        for (final m in view.marks)\n          Positioned(\n            left: m.x - 3,\n            top: view.trackRect.center.dy - 3,\n            child: Container(\n              width: 6,\n              height: 6,\n              decoration: BoxDecoration(\n                shape: BoxShape.circle,\n                color: (m.t <= activeT) ? active : inactive,\n              ),\n            ),\n          ),\n      ],\n    );\n  }\n}\n\n/// Renderer that paints waveform-like bars over a base segmented track.\nclass ShadWaveformRenderer extends ShadTrackRenderer {\n  const ShadWaveformRenderer({\n    /// Base renderer used before waveform bars are painted.\n    this.base = const ShadSegmentedCapsuleRenderer(),\n\n    /// Number of generated bars across track width.\n    ///\n    /// `0` is invalid. Higher values increase detail and paint cost.\n    this.bars = 64,\n  });\n\n  /// Base renderer for non-wave layers.\n  final ShadTrackRenderer base;\n\n  /// Number of waveform bars to render.\n  final int bars;\n\n  /// Builds base layers first, then paints waveform bars over the track.\n  @override\n  Widget build(BuildContext context, ShadSliderStateView view) {\n    final cs = Theme.of(context).colorScheme;\n    final compTheme = ComponentTheme.maybeOf<SliderTheme>(context);\n    final w = view.trackRect.width;\n    final h = view.trackRect.height;\n    final barW = w / bars;\n    final maxBarH = h * 0.75;\n    final activeX = w * (view.t ?? 0);\n    final active =\n        compTheme?.waveformTicksActiveColor ?? cs.background.withOpacity(0.52);\n    final inactive =\n        compTheme?.waveformTicksInactiveColor ??\n        cs.foreground.withOpacity(0.40);\n\n    return Stack(\n      clipBehavior: Clip.none,\n      children: [\n        base.build(context, view),\n        Positioned.fromRect(\n          rect: view.trackRect,\n          child: ClipRRect(\n            borderRadius: BorderRadius.circular(view.trackRadius),\n            child: SizedBox(\n              width: w,\n              height: h,\n              child: Stack(\n                children: [\n                  for (int i = 0; i < bars; i++)\n                    Positioned(\n                      left: i * barW,\n                      top: () {\n                        final t = i / (bars - 1);\n                        final amp = (math.sin(t * math.pi) * 0.85 + 0.15);\n                        final bh = maxBarH * amp;\n                        return (h - bh) / 2;\n                      }(),\n                      child: Builder(\n                        builder: (_) {\n                          final t = i / (bars - 1);\n                          final amp = (math.sin(t * math.pi) * 0.85 + 0.15);\n                          final bh = maxBarH * amp;\n                          return Container(\n                            width: math.max(1, barW * 0.55),\n                            height: bh,\n                            decoration: BoxDecoration(\n                              borderRadius: BorderRadius.circular(999),\n                              color: ((i * barW) <= activeX)\n                                  ? active\n                                  : inactive,\n                            ),\n                          );\n                        },\n                      ),\n                    ),\n                ],\n              ),\n            ),\n          ),\n        ),\n      ],\n    );\n  }\n}\n",
  "{installPath}/components/form/slider/_impl/styles/shad_slider_defaults.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'dart:math' as math;\nimport 'package:flutter/material.dart' hide SliderTheme, Theme;\n\nimport '../../../../../shared/theme/theme.dart';\n\nimport '../core/shad_slider_models.dart';\nimport '../themes/base/slider_theme.dart';\n\n/// Default builders used by slider presets.\nclass ShadSliderDefaults {\n  ShadSliderDefaults({\n    /// Base track layer builder.\n    required this.trackBuilder,\n\n    /// Active/remaining fill layer builder.\n    required this.fillBuilder,\n\n    /// Thumb builder used for each resolved thumb state.\n    required this.thumbBuilder,\n\n    /// Marks/ticks layer builder.\n    required this.ticksBuilder,\n\n    /// Optional overlay layer builder.\n    required this.overlayBuilder,\n  });\n\n  /// Base track layer builder.\n  final ShadTrackBuilder trackBuilder;\n\n  /// Fill layer builder for active/remaining segments.\n  final ShadFillBuilder fillBuilder;\n\n  /// Thumb widget builder.\n  final ShadThumbBuilder thumbBuilder;\n\n  /// Tick/mark layer builder.\n  final ShadTicksBuilder ticksBuilder;\n\n  /// Overlay layer builder painted above other layers.\n  final ShadOverlayBuilder overlayBuilder;\n\n  /// Resolves default builders from current app theme tokens.\n  ///\n  /// Defaults are intentionally low-contrast and token-driven.\n  static ShadSliderDefaults of(BuildContext context) {\n    final theme = Theme.of(context);\n    final cs = theme.colorScheme;\n\n    return ShadSliderDefaults(\n      trackBuilder: (context, s) {\n        final theme = Theme.of(context);\n        final compTheme = ComponentTheme.maybeOf<SliderTheme>(context);\n        final guideHeight = (theme.density.baseGap * theme.scaling * 0.25)\n            .clamp(1.0, 3.0)\n            .toDouble();\n        final guideColor =\n            compTheme?.guideColor ?? cs.foreground.withOpacity(0.06);\n        return Positioned.fromRect(\n          rect: s.trackRect,\n          child: SizedBox(\n            width: s.trackRect.width,\n            height: s.trackRect.height,\n            child: Center(\n              child: Container(\n                height: guideHeight,\n                width: s.trackRect.width,\n                decoration: BoxDecoration(\n                  color: guideColor,\n                  borderRadius: BorderRadius.circular(999),\n                ),\n              ),\n            ),\n          ),\n        );\n      },\n      fillBuilder: (context, s) {\n        final theme = Theme.of(context);\n        final cs = theme.colorScheme;\n        final compTheme = ComponentTheme.maybeOf<SliderTheme>(context);\n        final fillColor = (compTheme?.fillActiveColor ?? cs.primary)\n            .withOpacity(s.enabled ? 0.92 : 0.35);\n        final remColor = (compTheme?.fillInactiveColor ?? cs.muted).withOpacity(\n          0.78,\n        );\n        final ordered = [...s.segments]\n          ..sort((a, b) => a.paintOrder.compareTo(b.paintOrder));\n\n        return Stack(\n          children: [\n            for (final segment in ordered)\n              if (segment.rect.width > 0.5)\n                Positioned.fromRect(\n                  rect: segment.rect,\n                  child: IgnorePointer(\n                    child: Container(\n                      decoration: BoxDecoration(\n                        color: switch (segment.kind) {\n                          ShadSegmentKind.fill => fillColor,\n                          ShadSegmentKind.remaining => remColor,\n                          ShadSegmentKind.gap => Colors.transparent,\n                          ShadSegmentKind.disabled => remColor.withOpacity(0.5),\n                          ShadSegmentKind.custom => remColor,\n                        },\n                        borderRadius:\n                            segment.radius ??\n                            BorderRadius.circular(\n                              math.min(s.trackRadius, s.trackRect.height / 2),\n                            ),\n                      ),\n                    ),\n                  ),\n                ),\n          ],\n        );\n      },\n      thumbBuilder: barThumb(),\n      ticksBuilder: (context, s) => const SizedBox.shrink(),\n      overlayBuilder: (context, s) => const SizedBox.shrink(),\n    );\n  }\n\n  /// Default bar thumb builder with optional radius override.\n  ///\n  /// The returned builder respects [ShadThumbStateView.size] for layout.\n  static ShadThumbBuilder barThumb({\n    /// Corner radius override for bar thumb body.\n    ///\n    /// `0` creates square corners; positive values round corners.\n    /// Null computes pill radius from resolved thumb width/height.\n    double? radius,\n\n    /// Horizontal inset applied to the visual thumb body in logical pixels.\n    ///\n    /// `0` keeps the body centered on the thumb anchor.\n    /// Positive values pull the body inward (LTR: left, RTL: right) while\n    /// preserving edge alignment at min/max.\n    double insideOffsetPx = 0,\n  }) {\n    return (context, t) {\n      final theme = Theme.of(context);\n      final baseGap = theme.density.baseGap * theme.scaling;\n      final barH = (t.size.height - baseGap * 0.25).clamp(2.0, 200.0);\n      final w = (t.size.width - baseGap * 0.25).clamp(2.0, 400.0);\n      final barRadius =\n          radius ?? (math.min(w, barH) / 2).clamp(1.0, 999.0).toDouble();\n      final cs = theme.colorScheme;\n      final compTheme = ComponentTheme.maybeOf<SliderTheme>(context);\n      final thumbFill = compTheme?.thumbFillColor ?? cs.background;\n      final thumbBorder =\n          compTheme?.thumbBorderColor ?? cs.foreground.withOpacity(0.10);\n\n      Widget body = IgnorePointer(\n        ignoring: true,\n        child: SizedBox(\n          width: t.size.width,\n          height: t.size.height,\n          child: Center(\n            child: Container(\n              width: w,\n              height: barH,\n              decoration: BoxDecoration(\n                color: thumbFill.withOpacity(t.enabled ? 1 : 0.7),\n                borderRadius: BorderRadius.circular(barRadius),\n                border: Border.all(color: thumbBorder, width: 1),\n              ),\n            ),\n          ),\n        ),\n      );\n\n      if (insideOffsetPx != 0) {\n        const eps = 0.005;\n        final atEdge = t.t <= eps || t.t >= 1 - eps;\n        if (!atEdge) {\n          final dir = Directionality.of(context);\n          final sign = dir == TextDirection.rtl ? 1.0 : -1.0;\n          body = Transform.translate(\n            offset: Offset(sign * insideOffsetPx, 0),\n            child: body,\n          );\n        }\n      }\n\n      return body;\n    };\n  }\n\n  /// Default drag popover for showing current value.\n  ///\n  /// Uses [ShadPopoverData.value] and applies shape/color from explicit\n  /// arguments first, then [SliderTheme], then component defaults.\n  static ShadPopoverBuilder valuePopover({\n    /// Value-to-string formatter.\n    ///\n    /// If null, formats with `toStringAsFixed(2)`.\n    String Function(double value)? formatter,\n\n    /// Popover shape override.\n    ///\n    /// Null defers to theme/default shape.\n    ShadPopoverShape? shape,\n  }) {\n    return (context, data) {\n      final compTheme = ComponentTheme.maybeOf<SliderTheme>(context);\n      final valueText =\n          formatter?.call(data.value) ?? data.value.toStringAsFixed(2);\n      final resolvedShape =\n          shape ?? compTheme?.popoverShape ?? ShadPopoverShape.rounded;\n      return _buildValuePopover(\n        context,\n        valueText: valueText,\n        shape: resolvedShape,\n      );\n    };\n  }\n\n  static Widget _buildValuePopover(\n    BuildContext context, {\n    required String valueText,\n    required ShadPopoverShape shape,\n  }) {\n    final theme = Theme.of(context);\n    final cs = theme.colorScheme;\n    final compTheme = ComponentTheme.maybeOf<SliderTheme>(context);\n    final bg = compTheme?.popoverBackgroundColor ?? cs.primary;\n    final fg = compTheme?.popoverForegroundColor ?? cs.background;\n    final radius = switch (shape) {\n      ShadPopoverShape.pill => BorderRadius.circular(999),\n      ShadPopoverShape.rounded => BorderRadius.circular(theme.radiusMd),\n      ShadPopoverShape.square => BorderRadius.circular(theme.radiusSm),\n    };\n\n    return Material(\n      color: Colors.transparent,\n      child: Container(\n        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),\n        decoration: BoxDecoration(\n          color: bg,\n          borderRadius: radius,\n          boxShadow: const [\n            BoxShadow(\n              color: Color(0x22000000),\n              blurRadius: 8,\n              offset: Offset(0, 3),\n            ),\n          ],\n        ),\n        child: Text(\n          valueText,\n          style: TextStyle(color: fg, fontWeight: FontWeight.w600),\n        ),\n      ),\n    );\n  }\n\n  /// Returns preconfigured popover helper with a pill shape.\n  static ShadPopoverBuilder valuePopoverPill({\n    /// Value-to-string formatter.\n    ///\n    /// If null, formats with `toStringAsFixed(2)`.\n    String Function(double value)? formatter,\n  }) {\n    return valuePopover(formatter: formatter, shape: ShadPopoverShape.pill);\n  }\n\n  /// Returns preconfigured popover helper with a rounded-rect shape.\n  static ShadPopoverBuilder valuePopoverRounded({\n    /// Value-to-string formatter.\n    ///\n    /// If null, formats with `toStringAsFixed(2)`.\n    String Function(double value)? formatter,\n  }) {\n    return valuePopover(formatter: formatter, shape: ShadPopoverShape.rounded);\n  }\n\n  /// Returns preconfigured popover helper with a square-like shape.\n  static ShadPopoverBuilder valuePopoverSquare({\n    /// Value-to-string formatter.\n    ///\n    /// If null, formats with `toStringAsFixed(2)`.\n    String Function(double value)? formatter,\n  }) {\n    return valuePopover(formatter: formatter, shape: ShadPopoverShape.square);\n  }\n\n  // ---- Convenience builders for presets ----\n\n  /// Ring thumb with subtle border and small center dot.\n  static Widget circleThumb(BuildContext context, ShadThumbStateView t) {\n    final cs = Theme.of(context).colorScheme;\n    final compTheme = ComponentTheme.maybeOf<SliderTheme>(context);\n    final border =\n        compTheme?.thumbBorderColor ?? cs.foreground.withOpacity(0.18);\n    final ring = cs.primary.withOpacity(t.enabled ? 0.95 : 0.45);\n    final d = t.size.width;\n\n    return IgnorePointer(\n      ignoring: true,\n      child: SizedBox(\n        width: t.size.width,\n        height: t.size.height,\n        child: Center(\n          child: SizedBox(\n            width: d,\n            height: d,\n            child: DecoratedBox(\n              decoration: BoxDecoration(\n                shape: BoxShape.circle,\n                color: Colors.transparent,\n                border: Border.all(color: border, width: 1),\n              ),\n              child: Center(\n                child: Container(\n                  width: d * 0.30,\n                  height: d * 0.30,\n                  decoration: BoxDecoration(\n                    shape: BoxShape.circle,\n                    color: ring,\n                  ),\n                ),\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n\n  /// Square-ish thumb helper that still honors theme colors and thumb size.\n  static Widget squareThumb(BuildContext context, ShadThumbStateView t) {\n    final theme = Theme.of(context);\n    final compTheme = ComponentTheme.maybeOf<SliderTheme>(context);\n    final cs = theme.colorScheme;\n    final border =\n        compTheme?.thumbBorderColor ?? cs.foreground.withOpacity(0.12);\n    final fill = compTheme?.thumbFillColor ?? cs.background;\n    final w = t.size.width;\n    final h = t.size.height * 0.85;\n\n    return IgnorePointer(\n      ignoring: true,\n      child: SizedBox(\n        width: t.size.width,\n        height: t.size.height,\n        child: Center(\n          child: SizedBox(\n            width: w,\n            height: h,\n            child: DecoratedBox(\n              decoration: BoxDecoration(\n                color: fill,\n                borderRadius: BorderRadius.circular(theme.radiusSm),\n                border: Border.all(color: border, width: 1),\n              ),\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n\n  /// Pin-style thumb helper with stem and circular head.\n  static Widget pinThumb(BuildContext context, ShadThumbStateView t) {\n    final cs = Theme.of(context).colorScheme;\n    final compTheme = ComponentTheme.maybeOf<SliderTheme>(context);\n    final border =\n        compTheme?.thumbBorderColor ?? cs.foreground.withOpacity(0.12);\n    final fill = compTheme?.thumbFillColor ?? cs.background;\n    final dot = cs.primary.withOpacity(t.enabled ? 0.95 : 0.45);\n\n    return IgnorePointer(\n      ignoring: true,\n      child: SizedBox(\n        width: 22,\n        height: 30,\n        child: Stack(\n          alignment: Alignment.topCenter,\n          children: [\n            Positioned(\n              top: 10,\n              child: Container(\n                width: 2,\n                height: 18,\n                decoration: BoxDecoration(\n                  color: border,\n                  borderRadius: BorderRadius.circular(99),\n                ),\n              ),\n            ),\n            Container(\n              width: 14,\n              height: 14,\n              decoration: BoxDecoration(\n                color: fill,\n                shape: BoxShape.circle,\n                border: Border.all(color: border, width: 1),\n              ),\n              child: Center(\n                child: Container(\n                  width: 6,\n                  height: 6,\n                  decoration: BoxDecoration(color: dot, shape: BoxShape.circle),\n                ),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  /// Softer dots (Stripe/Linear low-contrast).\n  /// Dot ticks helper that colors marks by progress position.\n  static Widget dotsTicks(BuildContext context, ShadSliderStateView s) {\n    final cs = Theme.of(context).colorScheme;\n    final compTheme = ComponentTheme.maybeOf<SliderTheme>(context);\n    final activeT = s.t ?? 0;\n    final active =\n        compTheme?.dotsActiveColor ?? cs.foreground.withOpacity(0.18);\n    final inactive =\n        compTheme?.dotsInactiveColor ?? cs.foreground.withOpacity(0.08);\n\n    return IgnorePointer(\n      child: Stack(\n        children: [\n          for (final m in s.marks)\n            Positioned(\n              left: m.x - 3,\n              top: s.trackRect.center.dy - 3,\n              child: Container(\n                width: 6,\n                height: 6,\n                decoration: BoxDecoration(\n                  shape: BoxShape.circle,\n                  color: (m.t <= activeT) ? active : inactive,\n                ),\n              ),\n            ),\n        ],\n      ),\n    );\n  }\n\n  /// Smooth, natural waveform-like bars (no patterned modulo).\n  /// Subtle bar ticks helper with waveform-like amplitude envelope.\n  static Widget subtleBarsTicks(BuildContext context, ShadSliderStateView s) {\n    final cs = Theme.of(context).colorScheme;\n    final compTheme = ComponentTheme.maybeOf<SliderTheme>(context);\n    final w = s.trackRect.width;\n    final h = s.trackRect.height;\n\n    const bars = 64;\n    final barW = w / bars;\n    final maxBarH = h * 0.75;\n\n    final activeT = s.t ?? 0;\n    final activeX = w * activeT;\n\n    // Inner bars: light on active segment, darker on inactive segment.\n    final active =\n        compTheme?.waveformTicksActiveColor ?? cs.background.withOpacity(0.52);\n    final inactive =\n        compTheme?.waveformTicksInactiveColor ??\n        cs.foreground.withOpacity(0.40);\n\n    return Positioned.fromRect(\n      rect: s.trackRect,\n      child: IgnorePointer(\n        child: ClipRRect(\n          borderRadius: BorderRadius.circular(s.trackRadius),\n          child: SizedBox(\n            width: w,\n            height: h,\n            child: Stack(\n              children: [\n                for (int i = 0; i < bars; i++)\n                  Positioned(\n                    left: i * barW,\n                    top: () {\n                      final t = i / (bars - 1);\n                      final amp =\n                          (math.sin(t * math.pi) * 0.85 + 0.15); // 0.15..1.0\n                      final bh = maxBarH * amp;\n                      return (h - bh) / 2;\n                    }(),\n                    child: Builder(\n                      builder: (_) {\n                        final t = i / (bars - 1);\n                        final amp = (math.sin(t * math.pi) * 0.85 + 0.15);\n                        final bh = maxBarH * amp;\n\n                        return Container(\n                          width: math.max(1, barW * 0.55),\n                          height: bh,\n                          decoration: BoxDecoration(\n                            borderRadius: BorderRadius.circular(999),\n                            color: ((i * barW) <= activeX) ? active : inactive,\n                          ),\n                        );\n                      },\n                    ),\n                  ),\n              ],\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}\n",
  "{installPath}/components/form/slider/_impl/styles/shad_slider_presets.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:flutter/material.dart' hide Theme;\n\nimport '../../../../../shared/theme/theme.dart';\n\nimport '../core/shad_slider_models.dart';\nimport 'shad_slider_defaults.dart';\n\nenum ShadSliderPreset { brightness, rangeSoft, stepsDots, waveform }\n\n/// Resolved preset output: builders + tuned layout values.\nclass ShadPresetResolved {\n  const ShadPresetResolved({\n    /// Resolved base track builder.\n    required this.trackBuilder,\n\n    /// Resolved fill builder.\n    required this.fillBuilder,\n\n    /// Resolved thumb builder.\n    required this.thumbBuilder,\n\n    /// Resolved ticks builder.\n    required this.ticksBuilder,\n\n    /// Resolved overlay builder.\n    required this.overlayBuilder,\n\n    /// Resolved track height.\n    required this.trackHeight,\n\n    /// Resolved thumb inset.\n    required this.thumbInset,\n\n    /// Resolved fill edge bias.\n    required this.fillEdgeBiasPx,\n  });\n\n  /// Base track builder selected after preset + overrides.\n  final ShadTrackBuilder trackBuilder;\n\n  /// Fill builder selected after preset + overrides.\n  final ShadFillBuilder fillBuilder;\n\n  /// Thumb builder selected after preset + overrides.\n  final ShadThumbBuilder thumbBuilder;\n\n  /// Ticks builder selected after preset + overrides.\n  final ShadTicksBuilder ticksBuilder;\n\n  /// Overlay builder selected after preset + overrides.\n  final ShadOverlayBuilder overlayBuilder;\n\n  /// Track height selected by preset.\n  final double trackHeight;\n\n  /// Thumb inset selected by preset.\n  final double thumbInset;\n\n  /// Fill edge bias selected by preset.\n  final double fillEdgeBiasPx;\n}\n\n/// Resolves final builder/layout values for a given [preset].\n///\n/// Explicit widget/theme overrides win first; preset fills only missing pieces.\nShadPresetResolved resolveShadSliderPreset(\n  BuildContext context, {\n\n  /// Preset identity to resolve.\n  required ShadSliderPreset preset,\n\n  /// Base track height before preset adjustments.\n  required double trackHeight,\n\n  /// Base thumb inset before preset adjustments.\n  required double thumbInset,\n\n  /// Base fill bias before preset adjustments.\n  required double fillEdgeBiasPx,\n\n  /// Optional track builder override.\n  ShadTrackBuilder? trackBuilder,\n\n  /// Optional fill builder override.\n  ShadFillBuilder? fillBuilder,\n\n  /// Optional thumb builder override.\n  ShadThumbBuilder? thumbBuilder,\n\n  /// Optional ticks builder override.\n  ShadTicksBuilder? ticksBuilder,\n\n  /// Optional overlay builder override.\n  ShadOverlayBuilder? overlayBuilder,\n}) {\n  // Presets only fill missing inputs; explicit widget/theme inputs win.\n  final defaults = ShadSliderDefaults.of(context);\n\n  ShadTrackBuilder tb = trackBuilder ?? defaults.trackBuilder;\n  ShadFillBuilder fb = fillBuilder ?? defaults.fillBuilder;\n  ShadThumbBuilder thb = thumbBuilder ?? defaults.thumbBuilder;\n  ShadTicksBuilder tix = ticksBuilder ?? defaults.ticksBuilder;\n  ShadOverlayBuilder ob = overlayBuilder ?? defaults.overlayBuilder;\n\n  double h = trackHeight;\n  double inset = thumbInset;\n  double bias = fillEdgeBiasPx;\n\n  switch (preset) {\n    case ShadSliderPreset.brightness:\n      break;\n    case ShadSliderPreset.rangeSoft:\n      h = trackHeight + 2;\n      thb = thumbBuilder ?? ShadSliderDefaults.circleThumb;\n      bias = 0;\n      break;\n    case ShadSliderPreset.stepsDots:\n      h = (trackHeight - 2).clamp(16.0, 9999.0);\n      thb = thumbBuilder ?? ShadSliderDefaults.circleThumb;\n      tix = ticksBuilder ?? ShadSliderDefaults.dotsTicks;\n      bias = 0;\n      break;\n    case ShadSliderPreset.waveform:\n      thb = thumbBuilder ?? ShadSliderDefaults.circleThumb;\n      tix = ticksBuilder ?? ShadSliderDefaults.subtleBarsTicks;\n      bias = 0;\n      break;\n  }\n\n  return ShadPresetResolved(\n    trackBuilder: tb,\n    fillBuilder: fb,\n    thumbBuilder: thb,\n    ticksBuilder: tix,\n    overlayBuilder: ob,\n    trackHeight: h,\n    thumbInset: inset,\n    fillEdgeBiasPx: bias,\n  );\n}\n",
  "{installPath}/components/form/slider/_impl/themes/base/slider_theme.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:flutter/widgets.dart';\n\nimport '../../../../../../shared/theme/theme.dart';\nimport '../../core/shad_slider_renderers.dart';\nimport '../../core/shad_slider_models.dart';\n\n/// Theme data for [Slider] and [WaveSlider].\nclass SliderTheme extends ComponentThemeData {\n  /// Track height in logical pixels.\n  final double? trackHeight;\n\n  /// Track radius in logical pixels. Clamped by runtime to half track height.\n  final double? trackRadius;\n\n  /// Base horizontal inset used for value-to-position mapping.\n  final double? thumbInset;\n\n  /// Thumb layout size used for paint and hit calculations.\n  final Size? thumbSize;\n\n  /// Optional corner radius for default bar thumb.\n  final double? thumbRadius;\n\n  /// Horizontal thumb edge offset.\n  ///\n  /// - `0`: inside track\n  /// - positive: moves toward/outside edges\n  /// - negative: moves further inside\n  final double? thumbEdgeOffsetPx;\n\n  /// Vertical thumb offset from track center.\n  ///\n  /// - positive: down\n  /// - negative: up\n  final double? thumbVerticalOffsetPx;\n\n  /// Gap between active and remaining segments around thumb centers.\n  final double? joinGapPx;\n\n  /// Whether fill computations align to thumb centers.\n  final bool? fillStopsAtThumbCenter;\n\n  /// Extra fill edge bias in logical pixels.\n  final double? fillEdgeBiasPx;\n\n  /// Preset name (`brightness`, `rangeSoft`, `stepsDots`, `waveform`).\n  final String? preset;\n\n  /// Optional custom track builder.\n  final ShadTrackBuilder? trackBuilder;\n\n  /// Optional custom fill builder.\n  final ShadFillBuilder? fillBuilder;\n\n  /// Optional custom thumb builder.\n  final ShadThumbBuilder? thumbBuilder;\n\n  /// Optional custom ticks builder.\n  final ShadTicksBuilder? ticksBuilder;\n\n  /// Optional custom overlay builder.\n  final ShadOverlayBuilder? overlayBuilder;\n\n  /// Optional segment geometry strategy.\n  final ShadSegmentLayout? segmentLayout;\n\n  /// Optional unified track renderer.\n  final ShadTrackRenderer? trackRenderer;\n\n  /// Optional drag popover builder shown for active thumb while dragging.\n  final ShadPopoverBuilder? dragPopoverBuilder;\n\n  /// Popover anchor offset in logical pixels.\n  final Offset? dragPopoverOffset;\n\n  /// Visibility behavior for slider popovers.\n  final ShadPopoverVisibility? dragPopoverVisibility;\n\n  /// Popover shape used by built-in popover helpers.\n  final ShadPopoverShape? popoverShape;\n\n  /// Popover background color used by built-in popover helpers.\n  final Color? popoverBackgroundColor;\n\n  /// Popover foreground color used by built-in popover helpers.\n  final Color? popoverForegroundColor;\n\n  /// Guide line color used by default track builder.\n  final Color? guideColor;\n\n  /// Active fill color used by default fill builder.\n  final Color? fillActiveColor;\n\n  /// Remaining fill color used by default fill builder.\n  final Color? fillInactiveColor;\n\n  /// Default thumb fill color (applies to bar/square/circle helpers).\n  final Color? thumbFillColor;\n\n  /// Default thumb border color (applies to bar/square/circle helpers).\n  final Color? thumbBorderColor;\n\n  /// Active color for default dots ticks.\n  final Color? dotsActiveColor;\n\n  /// Inactive color for default dots ticks.\n  final Color? dotsInactiveColor;\n\n  /// Active inner-bar color for default waveform ticks.\n  final Color? waveformTicksActiveColor;\n\n  /// Inactive inner-bar color for default waveform ticks.\n  final Color? waveformTicksInactiveColor;\n\n  /// Wave variant height in logical pixels.\n  final double? waveHeight;\n\n  /// Wave variant content padding.\n  final EdgeInsets? wavePadding;\n\n  /// Wave bar width in logical pixels.\n  final double? waveBarWidth;\n\n  /// Wave bar gap in logical pixels.\n  final double? waveBarGap;\n\n  /// Wave minimum bar height in logical pixels.\n  final double? waveMinBarHeight;\n\n  /// Wave maximum bar height in logical pixels.\n  final double? waveMaxBarHeight;\n\n  /// Wave bar corner radius.\n  final double? waveCornerRadius;\n\n  /// Wave active/progressed color.\n  final Color? waveActiveColor;\n\n  /// Wave inactive/remaining color.\n  final Color? waveInactiveColor;\n\n  /// Wave disabled opacity.\n  final double? waveDisabledOpacity;\n\n  /// Whether wave slider shows thumb.\n  final bool? waveShowThumb;\n\n  /// Wave thumb radius.\n  final double? waveThumbRadius;\n\n  /// Wave thumb fill color.\n  final Color? waveThumbColor;\n\n  /// Wave thumb border color.\n  final Color? waveThumbBorderColor;\n\n  /// Wave thumb border width.\n  final double? waveThumbBorderWidth;\n\n  /// Wave hit slop for easier dragging.\n  final double? waveHitSlop;\n\n  /// Enables wave interaction.\n  final bool? waveEnabled;\n\n  /// Optional popover builder for [WaveSlider].\n  final ShadPopoverBuilder? wavePopoverBuilder;\n\n  /// Wave popover anchor offset.\n  final Offset? wavePopoverOffset;\n\n  /// Visibility behavior for [WaveSlider] popover.\n  final ShadPopoverVisibility? wavePopoverVisibility;\n\n  /// Creates theme overrides for [Slider] and [WaveSlider].\n  const SliderTheme({\n    /// Density token override for this component scope.\n    super.themeDensity,\n\n    /// Spacing token override for this component scope.\n    super.themeSpacing,\n\n    /// Shadow token override for this component scope.\n    super.themeShadows,\n\n    /// See [trackHeight].\n    this.trackHeight,\n\n    /// See [trackRadius].\n    this.trackRadius,\n\n    /// See [thumbInset].\n    this.thumbInset,\n\n    /// See [thumbSize].\n    this.thumbSize,\n\n    /// See [thumbRadius].\n    this.thumbRadius,\n\n    /// See [thumbEdgeOffsetPx].\n    this.thumbEdgeOffsetPx,\n\n    /// See [thumbVerticalOffsetPx].\n    this.thumbVerticalOffsetPx,\n\n    /// See [joinGapPx].\n    this.joinGapPx,\n\n    /// See [fillStopsAtThumbCenter].\n    this.fillStopsAtThumbCenter,\n\n    /// See [fillEdgeBiasPx].\n    this.fillEdgeBiasPx,\n\n    /// See [preset].\n    this.preset,\n\n    /// See [trackBuilder].\n    this.trackBuilder,\n\n    /// See [fillBuilder].\n    this.fillBuilder,\n\n    /// See [thumbBuilder].\n    this.thumbBuilder,\n\n    /// See [ticksBuilder].\n    this.ticksBuilder,\n\n    /// See [overlayBuilder].\n    this.overlayBuilder,\n\n    /// See [segmentLayout].\n    this.segmentLayout,\n\n    /// See [trackRenderer].\n    this.trackRenderer,\n\n    /// See [dragPopoverBuilder].\n    this.dragPopoverBuilder,\n\n    /// See [dragPopoverOffset].\n    this.dragPopoverOffset,\n\n    /// See [dragPopoverVisibility].\n    this.dragPopoverVisibility,\n\n    /// See [popoverShape].\n    this.popoverShape,\n\n    /// See [popoverBackgroundColor].\n    this.popoverBackgroundColor,\n\n    /// See [popoverForegroundColor].\n    this.popoverForegroundColor,\n\n    /// See [guideColor].\n    this.guideColor,\n\n    /// See [fillActiveColor].\n    this.fillActiveColor,\n\n    /// See [fillInactiveColor].\n    this.fillInactiveColor,\n\n    /// See [thumbFillColor].\n    this.thumbFillColor,\n\n    /// See [thumbBorderColor].\n    this.thumbBorderColor,\n\n    /// See [dotsActiveColor].\n    this.dotsActiveColor,\n\n    /// See [dotsInactiveColor].\n    this.dotsInactiveColor,\n\n    /// See [waveformTicksActiveColor].\n    this.waveformTicksActiveColor,\n\n    /// See [waveformTicksInactiveColor].\n    this.waveformTicksInactiveColor,\n\n    /// See [waveHeight].\n    this.waveHeight,\n\n    /// See [wavePadding].\n    this.wavePadding,\n\n    /// See [waveBarWidth].\n    this.waveBarWidth,\n\n    /// See [waveBarGap].\n    this.waveBarGap,\n\n    /// See [waveMinBarHeight].\n    this.waveMinBarHeight,\n\n    /// See [waveMaxBarHeight].\n    this.waveMaxBarHeight,\n\n    /// See [waveCornerRadius].\n    this.waveCornerRadius,\n\n    /// See [waveActiveColor].\n    this.waveActiveColor,\n\n    /// See [waveInactiveColor].\n    this.waveInactiveColor,\n\n    /// See [waveDisabledOpacity].\n    this.waveDisabledOpacity,\n\n    /// See [waveShowThumb].\n    this.waveShowThumb,\n\n    /// See [waveThumbRadius].\n    this.waveThumbRadius,\n\n    /// See [waveThumbColor].\n    this.waveThumbColor,\n\n    /// See [waveThumbBorderColor].\n    this.waveThumbBorderColor,\n\n    /// See [waveThumbBorderWidth].\n    this.waveThumbBorderWidth,\n\n    /// See [waveHitSlop].\n    this.waveHitSlop,\n\n    /// See [waveEnabled].\n    this.waveEnabled,\n\n    /// See [wavePopoverBuilder].\n    this.wavePopoverBuilder,\n\n    /// See [wavePopoverOffset].\n    this.wavePopoverOffset,\n\n    /// See [wavePopoverVisibility].\n    this.wavePopoverVisibility,\n  });\n\n  /// Returns a copy with selected fields replaced.\n  ///\n  /// Only non-null getters are evaluated; omitted entries keep prior values.\n  /// To clear an override, pass a getter that returns `null`.\n  SliderTheme copyWith({\n    /// Replacement for [trackHeight].\n    ValueGetter<double?>? trackHeight,\n\n    /// Replacement for [trackRadius].\n    ValueGetter<double?>? trackRadius,\n\n    /// Replacement for [thumbInset].\n    ValueGetter<double?>? thumbInset,\n\n    /// Replacement for [thumbSize].\n    ValueGetter<Size?>? thumbSize,\n\n    /// Replacement for [thumbRadius].\n    ValueGetter<double?>? thumbRadius,\n\n    /// Replacement for [thumbEdgeOffsetPx].\n    ValueGetter<double?>? thumbEdgeOffsetPx,\n\n    /// Replacement for [thumbVerticalOffsetPx].\n    ValueGetter<double?>? thumbVerticalOffsetPx,\n\n    /// Replacement for [joinGapPx].\n    ValueGetter<double?>? joinGapPx,\n\n    /// Replacement for [fillStopsAtThumbCenter].\n    ValueGetter<bool?>? fillStopsAtThumbCenter,\n\n    /// Replacement for [fillEdgeBiasPx].\n    ValueGetter<double?>? fillEdgeBiasPx,\n\n    /// Replacement for [preset].\n    ValueGetter<String?>? preset,\n\n    /// Replacement for [trackBuilder].\n    ValueGetter<ShadTrackBuilder?>? trackBuilder,\n\n    /// Replacement for [fillBuilder].\n    ValueGetter<ShadFillBuilder?>? fillBuilder,\n\n    /// Replacement for [thumbBuilder].\n    ValueGetter<ShadThumbBuilder?>? thumbBuilder,\n\n    /// Replacement for [ticksBuilder].\n    ValueGetter<ShadTicksBuilder?>? ticksBuilder,\n\n    /// Replacement for [overlayBuilder].\n    ValueGetter<ShadOverlayBuilder?>? overlayBuilder,\n\n    /// Replacement for [segmentLayout].\n    ValueGetter<ShadSegmentLayout?>? segmentLayout,\n\n    /// Replacement for [trackRenderer].\n    ValueGetter<ShadTrackRenderer?>? trackRenderer,\n\n    /// Replacement for [dragPopoverBuilder].\n    ValueGetter<ShadPopoverBuilder?>? dragPopoverBuilder,\n\n    /// Replacement for [dragPopoverOffset].\n    ValueGetter<Offset?>? dragPopoverOffset,\n\n    /// Replacement for [dragPopoverVisibility].\n    ValueGetter<ShadPopoverVisibility?>? dragPopoverVisibility,\n\n    /// Replacement for [popoverShape].\n    ValueGetter<ShadPopoverShape?>? popoverShape,\n\n    /// Replacement for [popoverBackgroundColor].\n    ValueGetter<Color?>? popoverBackgroundColor,\n\n    /// Replacement for [popoverForegroundColor].\n    ValueGetter<Color?>? popoverForegroundColor,\n\n    /// Replacement for [guideColor].\n    ValueGetter<Color?>? guideColor,\n\n    /// Replacement for [fillActiveColor].\n    ValueGetter<Color?>? fillActiveColor,\n\n    /// Replacement for [fillInactiveColor].\n    ValueGetter<Color?>? fillInactiveColor,\n\n    /// Replacement for [thumbFillColor].\n    ValueGetter<Color?>? thumbFillColor,\n\n    /// Replacement for [thumbBorderColor].\n    ValueGetter<Color?>? thumbBorderColor,\n\n    /// Replacement for [dotsActiveColor].\n    ValueGetter<Color?>? dotsActiveColor,\n\n    /// Replacement for [dotsInactiveColor].\n    ValueGetter<Color?>? dotsInactiveColor,\n\n    /// Replacement for [wave