  "{installPath}/components/form/text_area/_impl/core/text_area_handle.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../text_area.dart';\n\n/// _TextAreaDragHandlePainter represents a form-related type in the registry.\nclass _TextAreaDragHandlePainter extends CustomPainter {\n  /// Field storing `color` for this form implementation.\n  final Color color;\n\n  _TextAreaDragHandlePainter(this.color);\n\n  /// Performs `paint` logic for this form component.\n  @override\n  void paint(Canvas canvas, Size size) {\n    final paint = Paint()\n      ..color = color\n      ..strokeWidth = 1\n      ..strokeCap = StrokeCap.round;\n    final start = Offset(size.width, 0);\n    final end = Offset(0, size.height);\n    final start2 = Offset(size.width, size.height / 2);\n    final end2 = Offset(size.width / 2, size.height);\n    canvas.drawLine(start, end, paint);\n    canvas.drawLine(start2, end2, paint);\n  }\n\n  /// Performs `shouldRepaint` logic for this form component.\n  @override\n  bool shouldRepaint(covariant _TextAreaDragHandlePainter oldDelegate) {\n    return color != oldDelegate.color;\n  }\n}\n",
  "{installPath}/components/form/text_area/_impl/state/text_area_state.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../text_area.dart';\n\n/// _TextAreaState stores and manages mutable widget state.\nclass _TextAreaState extends State<TextArea> {\n  /// Field storing `_height` for this form implementation.\n  late double _height;\n\n  /// Field storing `_width` for this form implementation.\n  late double _width;\n\n  /// Initializes stateful resources for this widget.\n  @override\n  void initState() {\n    super.initState();\n    _height = widget.initialHeight;\n    _width = widget.initialWidth;\n  }\n\n  /// Reacts to widget configuration updates from the parent.\n  @override\n  void didUpdateWidget(covariant TextArea oldWidget) {\n    super.didUpdateWidget(oldWidget);\n    if (widget.initialHeight != oldWidget.initialHeight) {\n      _height = widget.initialHeight;\n    }\n    if (widget.initialWidth != oldWidget.initialWidth) {\n      _width = widget.initialWidth;\n    }\n  }\n\n  /// Builds the widget tree for this component state.\n  @override\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n    final scaling = theme.scaling;\n    return SizedBox(\n      height: _height,\n      width: _width,\n      child: Stack(\n        fit: StackFit.passthrough,\n        clipBehavior: Clip.none,\n        children: [\n          Positioned.fill(\n            child: widget.copyWith(\n              expands: () => true,\n              maxLines: () => null,\n              minLines: () => null,\n            ),\n          ),\n          Positioned(\n            bottom: -1 * scaling,\n            right: -1 * scaling,\n            width: (8 + 8) * scaling,\n            height: (8 + 8) * scaling,\n            child: MouseRegion(\n              hitTestBehavior: HitTestBehavior.translucent,\n              cursor: widget.expandableWidth\n                  ? widget.expandableHeight\n                        ? SystemMouseCursors.resizeDownRight\n                        : SystemMouseCursors.resizeLeftRight\n                  : widget.expandableHeight\n                  ? SystemMouseCursors.resizeUpDown\n                  : SystemMouseCursors.basic,\n              child: GestureDetector(\n                behavior: HitTestBehavior.translucent,\n                onPanUpdate: (details) {\n                  if (widget.expandableHeight && _height.isFinite) {\n                    /// Triggers a rebuild after mutating local state.\n                    setState(() {\n                      _height += details.delta.dy;\n                      _height = _height.clamp(\n                        widget.minHeight,\n                        widget.maxHeight,\n                      );\n                      widget.onHeightChanged?.call(_height);\n                    });\n                  }\n                  if (widget.expandableWidth && _width.isFinite) {\n                    /// Triggers a rebuild after mutating local state.\n                    setState(() {\n                      _width += details.delta.dx;\n                      _width = _width.clamp(widget.minWidth, widget.maxWidth);\n                      widget.onWidthChanged?.call(_width);\n                    });\n                  }\n                },\n                child: Padding(\n                  padding: EdgeInsets.all(\n                    theme.density.baseGap * scaling * 0.5,\n                  ),\n                  child: CustomPaint(\n                    painter: _TextAreaDragHandlePainter(\n                      theme.colorScheme.foreground,\n                    ),\n                  ),\n                ),\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}\n",
  "{installPath}/components/form/text_area/text_area.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:flutter/widgets.dart';\n\nimport '../text_field/text_field.dart';\nimport '../../../shared/theme/theme.dart';\n\npart '_impl/state/text_area_state.dart';\npart '_impl/core/text_area_handle.dart';\n\n/// Multi-line text input with resizable dimensions.\nclass TextArea extends TextInputStatefulWidget {\n  /// Field storing `expandableHeight` for this form implementation.\n  final bool expandableHeight;\n\n  /// Field storing `expandableWidth` for this form implementation.\n  final bool expandableWidth;\n\n  /// Field storing `initialHeight` for this form implementation.\n  final double initialHeight;\n\n  /// Field storing `initialWidth` for this form implementation.\n  final double initialWidth;\n\n  /// Callback invoked for `onHeightChanged` events.\n  final ValueChanged<double>? onHeightChanged;\n\n  /// Callback invoked for `onWidthChanged` events.\n  final ValueChanged<double>? onWidthChanged;\n\n  /// Field storing `minWidth` for this form implementation.\n  final double minWidth;\n\n  /// Field storing `minHeight` for this form implementation.\n  final double minHeight;\n\n  /// Field storing `maxWidth` for this form implementation.\n  final double maxWidth;\n\n  /// Field storing `maxHeight` for this form implementation.\n  final double maxHeight;\n\n  /// Constructs `TextArea` with the provided parameters.\n  const TextArea({\n    super.key,\n    super.groupId,\n    super.controller,\n    super.focusNode,\n    super.decoration,\n    super.padding,\n    super.placeholder,\n    super.crossAxisAlignment,\n    super.clearButtonSemanticLabel,\n    super.keyboardType,\n    super.textInputAction,\n    super.textCapitalization,\n    super.style,\n    super.strutStyle,\n    super.textAlign,\n    super.textAlignVertical,\n    super.textDirection,\n    super.readOnly,\n    super.showCursor,\n    super.autofocus,\n    super.obscuringCharacter,\n    super.obscureText,\n    super.autocorrect,\n    super.smartDashesType,\n    super.smartQuotesType,\n    super.enableSuggestions,\n    super.maxLines,\n    super.minLines,\n    super.expands,\n    super.maxLength,\n    super.maxLengthEnforcement,\n    super.onChanged,\n    super.onEditingComplete,\n    super.onSubmitted,\n    super.onTapOutside,\n    super.onTapUpOutside,\n    super.inputFormatters,\n    super.enabled,\n    super.cursorWidth,\n    super.cursorHeight,\n    super.cursorRadius,\n    super.cursorOpacityAnimates,\n    super.cursorColor,\n    super.selectionHeightStyle,\n    super.selectionWidthStyle,\n    super.keyboardAppearance,\n    super.scrollPadding,\n    super.enableInteractiveSelection,\n    super.selectionControls,\n    super.dragStartBehavior,\n    super.scrollController,\n    super.scrollPhysics,\n    super.onTap,\n    super.autofillHints,\n    super.clipBehavior,\n    super.restorationId,\n    super.stylusHandwritingEnabled,\n    super.enableIMEPersonalizedLearning,\n    super.contentInsertionConfiguration,\n    super.contextMenuBuilder,\n    super.initialValue,\n    super.hintText,\n    super.border,\n    super.borderRadius,\n    super.filled,\n    super.statesController,\n    super.magnifierConfiguration,\n    super.spellCheckConfiguration,\n    super.undoController,\n    super.features,\n    super.submitFormatters,\n    super.skipInputFeatureFocusTraversal,\n    this.expandableHeight = false,\n    this.expandableWidth = false,\n    this.initialHeight = 100,\n    this.initialWidth = double.infinity,\n    this.onHeightChanged,\n    this.onWidthChanged,\n    this.minWidth = 100,\n    this.minHeight = 100,\n    this.maxWidth = double.infinity,\n    this.maxHeight = double.infinity,\n  });\n\n  /// Creates the `State` object for this widget.\n  @override\n  State<TextArea> createState() => _TextAreaState