  "{installPath}/components/form/text_field/_impl/core/text_field_gestures.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../text_field.dart';\n\n/// _TextFieldSelectionGestureDetectorBuilder represents a form-related type in the registry.\nclass _TextFieldSelectionGestureDetectorBuilder\n    extends TextSelectionGestureDetectorBuilder {\n  _TextFieldSelectionGestureDetectorBuilder({required TextFieldState state})\n    : _state = state,\n      super(delegate: state);\n\n  final TextFieldState _state;\n\n  /// Performs `onSingleTapUp` logic for this form component.\n  @override\n  void onSingleTapUp(TapDragUpDetails details) {\n    // Because TextSelectionGestureDetector listens to taps that happen on\n    // widgets in front of it, tapping the clear button will also trigger\n    // this handler. If the clear button widget recognizes the up event,\n    // then do not handle it.\n    if (_state._clearGlobalKey.currentContext != null) {\n      final RenderBox renderBox =\n          _state._clearGlobalKey.currentContext!.findRenderObject()!\n              as RenderBox;\n      final Offset localOffset = renderBox.globalToLocal(\n        details.globalPosition,\n      );\n      if (renderBox.hitTest(BoxHitTestResult(), position: localOffset)) {\n        return;\n      }\n    }\n    super.onSingleTapUp(details);\n    _state.widget.onTap?.call();\n  }\n\n  /// Performs `onDragSelectionEnd` logic for this form component.\n  @override\n  void onDragSelectionEnd(TapDragEndDetails details) {\n    _state._requestKeyboard();\n    super.onDragSelectionEnd(details);\n  }\n}\n",
  "{installPath}/components/form/text_field/_impl/core/text_field_widget.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../text_field.dart';\n\n/// TextField represents a form-related type in the registry.\nclass TextField extends TextInputStatefulWidget {\n  /// Returns a native platform context menu builder.\n  ///\n  /// Uses the platform's default text selection toolbar.\n  static EditableTextContextMenuBuilder nativeContextMenuBuilder() {\n    return (context, editableTextState) {\n      return material.AdaptiveTextSelectionToolbar.editableText(\n        editableTextState: editableTextState,\n      );\n    };\n  }\n\n  /// Returns a Cupertino-style context menu builder.\n  ///\n  /// Uses iOS-style text selection toolbar.\n  static EditableTextContextMenuBuilder cupertinoContextMenuBuilder() {\n    return (context, editableTextState) {\n      return cupertino.CupertinoAdaptiveTextSelectionToolbar.editableText(\n        editableTextState: editableTextState,\n      );\n    };\n  }\n\n  /// Returns a Material Design context menu builder.\n  ///\n  /// Uses Material Design text selection toolbar.\n  static EditableTextContextMenuBuilder materialContextMenuBuilder() {\n    return (context, editableTextState) {\n      final anchors = editableTextState.contextMenuAnchors;\n      return material.TextSelectionToolbar(\n        anchorAbove: anchors.primaryAnchor,\n        anchorBelow: anchors.secondaryAnchor == null\n            ? anchors.primaryAnchor\n            : anchors.secondaryAnchor!,\n        children: _getMaterialButtons(\n          context,\n          editableTextState.contextMenuButtonItems,\n        ),\n      );\n    };\n  }\n\n  static List<Widget> _getMaterialButtons(\n    BuildContext context,\n    List<ContextMenuButtonItem> buttonItems,\n  ) {\n    final List<Widget> buttons = <Widget>[];\n    for (int i = 0; i < buttonItems.length; i++) {\n      final ContextMenuButtonItem buttonItem = buttonItems[i];\n      buttons.add(\n        material.TextSelectionToolbarTextButton(\n          padding: material.TextSelectionToolbarTextButton.getPadding(\n            i,\n            buttonItems.length,\n          ),\n          onPressed: buttonItem.onPressed,\n          alignment: AlignmentDirectional.centerStart,\n          child: Text(_getMaterialButtonLabel(context, buttonItem)),\n        ),\n      );\n    }\n    return buttons;\n  }\n\n  static String _getMaterialButtonLabel(\n    BuildContext context,\n    ContextMenuButtonItem buttonItem,\n  ) {\n    final localizations = material.MaterialLocalizations.of(context);\n    return switch (buttonItem.type) {\n      ContextMenuButtonType.cut => localizations.cutButtonLabel,\n      ContextMenuButtonType.copy => localizations.copyButtonLabel,\n      ContextMenuButtonType.paste => localizations.pasteButtonLabel,\n      ContextMenuButtonType.selectAll => localizations.selectAllButtonLabel,\n      ContextMenuButtonType.delete =>\n        localizations.deleteButtonTooltip.toUpperCase(),\n      ContextMenuButtonType.lookUp => localizations.lookUpButtonLabel,\n      ContextMenuButtonType.searchWeb => localizations.searchWebButtonLabel,\n      ContextMenuButtonType.share => localizations.shareButtonLabel,\n      ContextMenuButtonType.liveTextInput => localizations.scanTextButtonLabel,\n      ContextMenuButtonType.custom => '',\n    };\n  }\n\n  /// Creates a text input field widget.\n  ///\n  /// A comprehensive text field implementation with support for various input\n  /// types, validation, formatting, and interactive features. All parameters\n  /// are forwarded to the parent [TextInputStatefulWidget] constructor.\n  ///\n  /// This constructor provides extensive customization options matching Flutter's\n  /// [EditableText] while adding custom features like input decorations, features,\n  /// and form integration.\n  ///\n  /// Example:\n  /// ```dart\n  /// TextField(\n  ///   controller: myController,\n  ///   hintText: 'Enter text',\n  ///   keyboardType: TextInputType.text,\n  ///   maxLines: 3,\n  ///   onChanged: (value) => print(value),\n  /// )\n  /// ```\n  ///\n  /// See [TextInputStatefulWidget] and [TextInput] for parameter details.\n  const TextField({\n    super.key,\n    super.groupId,\n    super.controller,\n    super.initialValue,\n    super.focusNode,\n    super.undoController,\n    super.decoration,\n    super.padding,\n    super.placeholder,\n    super.crossAxisAlignment,\n    super.clearButtonSemanticLabel,\n    super.keyboardType,\n    super.textInputAction,\n    super.textCapitalization,\n    super.style,\n    super.strutStyle,\n    super.textAlign,\n    super.textAlignVertical,\n    super.textDirection,\n    super.readOnly,\n    super.showCursor,\n    super.autofocus,\n    super.obscuringCharacter,\n    super.obscureText,\n    super.autocorrect,\n    super.smartDashesType,\n    super.smartQuotesType,\n    super.enableSuggestions,\n    super.maxLines,\n    super.minLines,\n    super.expands,\n    super.maxLength,\n    super.maxLengthEnforcement,\n    super.onChanged,\n    super.onEditingComplete,\n    super.onSubmitted,\n    super.onTapOutside,\n    super.onTapUpOutside,\n    super.inputFormatters,\n    super.enabled,\n    super.cursorWidth,\n    super.cursorHeight,\n    super.cursorRadius,\n    super.cursorOpacityAnimates,\n    super.cursorColor,\n    super.selectionHeightStyle,\n    super.selectionWidthStyle,\n    super.keyboardAppearance,\n    super.scrollPadding,\n    super.enableInteractiveSelection,\n    super.selectionControls,\n    super.dragStartBehavior,\n    super.scrollController,\n    super.scrollPhysics,\n    super.onTap,\n    super.autofillHints,\n    super.clipBehavior,\n    super.restorationId,\n    super.stylusHandwritingEnabled,\n    super.enableIMEPersonalizedLearning,\n    super.contentInsertionConfiguration,\n    super.contextMenuBuilder = defaultContextMenuBuilder,\n    super.hintText,\n    super.border,\n    super.borderRadius,\n    super.filled,\n    super.statesController,\n    super.magnifierConfiguration,\n    super.spellCheckConfiguration,\n    super.features,\n    super.submitFormatters,\n    super.skipInputFeatureFocusTraversal,\n  });\n\n  /// Default context menu builder for editable text.\n  ///\n  /// Builds the standard context menu for text selection operations.\n  static Widget defaultContextMenuBuilder(\n    BuildContext context,\n    EditableTextState editableTextState,\n  ) {\n    return buildEditableTextContextMenu(context, editableTextState);\n  }\n\n  /// Default spell check suggestions toolbar builder.\n  ///\n  /// Builds the toolbar showing spell check suggestions.\n  @visibleForTesting\n  static Widget defaultSpellCheckSuggestionsToolbarBuilder(\n    BuildContext context,\n    EditableTextState editableTextState,\n  ) {\n    return CupertinoSpellCheckSuggestionsToolbar.editableText(\n      editableTextState: editableTextState,\n    );\n  }\n\n  /// Creates the `State` object for this widget.\n  @override\n  State<TextField> createState() => TextFieldState();\n\n  /// Performs `debugFillProperties` logic for this form component.\n  @override\n  void debugFillProperties(DiagnosticPropertiesBuilder properties) {\n    super.debugFillProperties(properties);\n    properties.add(\n      DiagnosticsProperty<TextEditingController>(\n        'controller',\n        controller,\n        defaultValue: null,\n      ),\n    );\n    properties.add(\n      DiagnosticsProperty<FocusNode>(\n        'focusNode',\n        focusNode,\n        defaultValue: null,\n      ),\n    );\n    properties.add(\n      DiagnosticsProperty<UndoHistoryController>(\n        'undoController',\n        undoController,\n        defaultValue: null,\n      ),\n    );\n    properties.add(\n      DiagnosticsProperty<BoxDecoration>('decoration', decoration),\n    );\n    properties.add(DiagnosticsProperty<EdgeInsetsGeometry>('padding', padding));\n    properties.add(\n      DiagnosticsProperty<String>(\n        'clearButtonSemanticLabel',\n        clearButtonSemanticLabel,\n      ),\n    );\n    properties.add(\n      DiagnosticsProperty<TextInputType>(\n        'keyboardType',\n        keyboardType,\n        defaultValue: TextInputType.text,\n      ),\n    );\n    properties.add(\n      DiagnosticsProperty<TextStyle>('style', style, defaultValue: null),\n    );\n    properties.add(\n      DiagnosticsProperty<bool>('autofocus', autofocus, defaultValue: false),\n    );\n    properties.add(\n      DiagnosticsProperty<String>(\n        'obscuringCharacter',\n        obscuringCharacter,\n        defaultValue: '•',\n      ),\n    );\n    properties.add(\n      DiagnosticsProperty<bool>(\n        'obscureText',\n        obscureText,\n        defaultValue: false,\n      ),\n    );\n    properties.add(\n      DiagnosticsProperty<bool>('autocorrect', autocorrect, defaultValue: true),\n    );\n    properties.add(\n      EnumProperty<SmartDashesType>(\n        'smartDashesType',\n        smartDashesType,\n        defaultValue: obscureText\n            ? SmartDashesType.disabled\n            : SmartDashesType.enabled,\n      ),\n    );\n    properties.add(\n      EnumProperty<SmartQuotesType>(\n        'smartQuotesType',\n        smartQuotesType,\n        defaultValue: obscureText\n            ? SmartQuotesType.disabled\n            : SmartQuotesType.enabled,\n      ),\n    );\n    properties.add(\n      DiagnosticsProperty<bool>(\n        'enableSuggestions',\n        enableSuggestions,\n        defaultValue: true,\n      ),\n    );\n    properties.add(IntProperty('maxLines', maxLines, defaultValue: 1));\n    properties.add(IntProperty('minLines', minLines, defaultValue: null));\n    properties.add(\n      DiagnosticsProperty<bool>('expands', expands, defaultValue: false),\n    );\n    properties.add(IntProperty('maxLength', maxLength, defaultValue: null));\n    properties.add(\n      EnumProperty<MaxLengthEnforcement>(\n        'maxLengthEnforcement',\n        maxLengthEnforcement,\n        defaultValue: null,\n      ),\n    );\n    properties.add(\n      DoubleProperty('cursorWidth', cursorWidth, defaultValue: 2.0),\n    );\n    properties.add(\n      DoubleProperty('cursorHeight', cursorHeight, defaultValue: null),\n    );\n    properties.add(\n      DiagnosticsProperty<Radius>(\n        'cursorRadius',\n        cursorRadius,\n        defaultValue: null,\n      ),\n    );\n    properties.add(\n      DiagnosticsProperty<bool>(\n        'cursorOpacityAnimates',\n        cursorOpacityAnimates,\n        defaultValue: true,\n      ),\n    );\n    properties.add(ColorProperty('cursorColor', cursorColor));\n    properties.add(\n      DiagnosticsProperty<TextSelectionControls>(\n        'selectionControls',\n        selectionControls,\n        defaultValue: null,\n      ),\n    );\n    properties.add(\n      DiagnosticsProperty<ScrollController>(\n        'scrollController',\n        scrollController,\n        defaultValue: null,\n      ),\n    );\n    properties.add(\n      DiagnosticsProperty<ScrollPhysics>(\n        'scrollPhysics',\n        scrollPhysics,\n        defaultValue: null,\n      ),\n    );\n    properties.add(\n      EnumProperty<TextAlign>(\n        'textAlign',\n        textAlign,\n        defaultValue: TextAlign.start,\n      ),\n    );\n    properties.add(\n      DiagnosticsProperty<TextAlignVertical>(\n        'textAlignVertical',\n        textAlignVertical,\n        defaultValue: null,\n      ),\n    );\n    properties.add(\n      EnumProperty<TextDirection>(\n        'textDirection',\n        textDirection,\n        defaultValue: null,\n      ),\n    );\n    properties.add(\n      DiagnosticsProperty<Clip>(\n        'clipBehavior',\n        clipBehavior,\n        defaultValue: Clip.hardEdge,\n      ),\n    );\n    properties.add(\n      DiagnosticsProperty<bool>(\n        'stylusHandwritingEnabled',\n        stylusHandwritingEnabl