  "{installPath}/components/navigation/breadcrumb/_impl/core/breadcrumb_2.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../breadcrumb.dart';\n\n/// Breadcrumb defines a reusable type for this registry module.\nclass Breadcrumb extends StatelessWidget {\n  /// Arrow separator (>).\n  static const Widget arrowSeparator = _ArrowSeparator();\n\n  /// Slash separator (/).\n  static const Widget slashSeparator = _SlashSeparator();\n\n  /// The breadcrumb items rendered from root to current location.\n  final List<Widget> children;\n\n  /// Separator inserted between items.\n  final Widget? separator;\n\n  /// Padding around the breadcrumb strip.\n  final EdgeInsetsGeometry? padding;\n\n  /// Creates a breadcrumb navigation row.\n  const Breadcrumb({\n    super.key,\n    required this.children,\n    this.separator,\n    this.padding,\n  });\n\n  @override\n  /// Executes `build` behavior for this component/composite.\n  Widget build(BuildContext context) {\n    final compTheme = ComponentTheme.maybeOf<BreadcrumbTheme>(context);\n\n    /// Stores `sep` state/configuration for this implementation.\n    final sep = separator ?? compTheme?.separator ?? Breadcrumb.arrowSeparator;\n    final pad = styleValue(\n      widgetValue: padding,\n      themeValue: compTheme?.padding,\n      defaultValue: EdgeInsets.zero,\n    );\n    return ScrollConfiguration(\n      behavior: ScrollConfiguration.of(\n        context,\n      ).copyWith(scrollbars: false, dragDevices: {PointerDeviceKind.touch}),\n      child: SingleChildScrollView(\n        scrollDirection: Axis.horizontal,\n        child: Padding(\n          padding: pad,\n          child: Row(\n            children: [\n              if (children.length == 1) children[0].medium().foreground(),\n              if (children.length > 1)\n                for (var i = 0; i < children.length; i++)\n                  if (i == children.length - 1)\n                    children[i].medium().foreground()\n                  else\n                    /// Creates a `Row` instance.\n                    Row(children: [children[i].medium(), sep]),\n            ],\n          ).small(),\n        ),\n      ),\n    );\n  }\n}\n",
  "{installPath}/components/navigation/breadcrumb/breadcrumb.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'dart:ui';\n\nimport 'package:flutter/widgets.dart';\n\nimport '../../../shared/icons/radix_icons.dart';\nimport '../../../shared/primitives/text.dart';\nimport '../../../shared/theme/theme.dart';\nimport '../../../shared/utils/style_value.dart';\npart '_impl/core/breadcrumb_2.dart';\npart '_impl/core/_slash_separator.dart';\npart '_impl/core/_arrow_separator.dart';\n\n/// Theme for [Breadcrumb].\nclass BreadcrumbTheme extends ComponentThemeData {\n  /// Separator widget between breadcrumb items.\n  final Widget? separator;\n\n  /// Padding surrounding the breadcrumb row.\n  final EdgeInsetsGeometry? padding;\n\n  /// Creates a [BreadcrumbTheme].\n  const BreadcrumbTheme({\n    super.themeDensity,\n    super.themeSpacing,\n    super.themeShadows,\n    this.separator,\n    this.padding,\n  });\n\n  /// Returns a copy of this theme with the given values replaced.\n  BreadcrumbTheme copyWith({\n    ValueGetter<Widget?>? separator,\n    ValueGetter<EdgeInsetsGeometry?>? padding,\n  }) {\n    return BreadcrumbTheme(\n      separator: separator == null ? this.separator : separator(),\n      padding: padding == null ? this.padding : padding(),\n    );\n  }\n\n  @override\n  /// Executes `operator ==` behavior for this component/composite.\n  bool operator ==(Object other) {\n    if (identical(this, other)) return true;\n    return other is BreadcrumbTheme &&\n        other.separator == separator &&\n        other.padding == padding;\n  }\n\n  @override\n  int get hashCode => Object.hash(separator, padding);\n}\n\n/// Navigation breadcrumb trail showing hierarchical path with customizable separators.\n",
  "{installPath}/components/navigation/pagination/_impl/core/pagination_2.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../pagination.dart';\n\n/// Pagination defines a reusable type for this registry module.\nclass Pagination extends StatelessWidget {\n  /// Stores `page` state/configuration for this implementation.\n  final int page;\n\n  /// Stores `totalPages` state/configuration for this implementation.\n  final int totalPages;\n\n  /// Stores `onPageChanged` state/configuration for this implementation.\n  final ValueChanged<int> onPageChanged;\n\n  /// Stores `maxPages` state/configuration for this implementation.\n  final int maxPages;\n\n  /// Stores `showSkipToFirstPage` state/configuration for this implementation.\n  final bool showSkipToFirstPage;\n\n  /// Stores `showSkipToLastPage` state/configuration for this implementation.\n  final bool showSkipToLastPage;\n\n  /// Stores `hidePreviousOnFirstPage` state/configuration for this implementation.\n  final bool hidePreviousOnFirstPage;\n\n  /// Stores `hideNextOnLastPage` state/configuration for this implementation.\n  final bool hideNextOnLastPage;\n\n  /// Stores `showLabel` state/configuration for this implementation.\n  final bool? showLabel;\n\n  /// Stores `gap` state/configuration for this implementation.\n  final double? gap;\n\n  /// Creates a `Pagination` instance.\n  const Pagination({\n    super.key,\n    required this.page,\n    required this.totalPages,\n    required this.onPageChanged,\n    this.maxPages = 3,\n    this.showSkipToFirstPage = true,\n    this.showSkipToLastPage = true,\n    this.hidePreviousOnFirstPage = false,\n    this.hideNextOnLastPage = false,\n    this.showLabel,\n    this.gap,\n  });\n\n  /// Stores `hasPrevious` state/configuration for this implementation.\n  bool get hasPrevious => page > 1;\n\n  /// Stores `hasNext` state/configuration for this implementation.\n  bool get hasNext => page < totalPages;\n\n  Iterable<int> get pages sync* {\n    if (totalPages <= maxPages) {\n      yield* List.generate(totalPages, (index) => index + 1);\n    } else {\n      /// Stores `start` state/configuration for this implementation.\n      final start = page - maxPages ~/ 2;\n\n      /// Stores `end` state/configuration for this implementation.\n      final end = page + maxPages ~/ 2;\n      if (start < 1) {\n        yield* List.generate(maxPages, (index) => index + 1);\n      } else if (end > totalPages) {\n        yield* List.generate(\n          maxPages,\n          (index) => totalPages - maxPages + index + 1,\n        );\n      } else {\n        yield* List.generate(maxPages, (index) => start + index);\n      }\n    }\n  }\n\n  int get firstShownPage {\n    if (totalPages <= maxPages) {\n      return 1;\n    } else {\n      /// Stores `start` state/configuration for this implementation.\n      final start = page - maxPages ~/ 2;\n      return start < 1 ? 1 : start;\n    }\n  }\n\n  int get lastShownPage {\n    if (totalPages <= maxPages) {\n      return totalPages;\n    } else {\n      /// Stores `end` state/configuration for this implementation.\n      final end = page + maxPages ~/ 2;\n      return end > totalPages ? totalPages : end;\n    }\n  }\n\n  /// Stores `hasMorePreviousPages` state/configuration for this implementation.\n  bool get hasMorePreviousPages => firstShownPage > 1;\n\n  /// Stores `hasMoreNextPages` state/configuration for this implementation.\n  bool get hasMoreNextPages => lastShownPage < totalPages;\n\n  Widget _buildPreviousLabel(\n    ShadcnLocalizations localizations,\n    bool showLabel,\n  ) {\n    if (showLabel) {\n      return GhostButton(\n        onPressed: hasPrevious ? () => onPageChanged(page - 1) : null,\n        leading: const Icon(RadixIcons.chevronLeft).iconXSmall(),\n        child: Text(localizations.buttonPrevious),\n      );\n    }\n    return GhostButton(\n      onPressed: hasPrevious ? () => onPageChanged(page - 1) : null,\n      child: const Icon(RadixIcons.chevronLeft).iconXSmall(),\n    );\n  }\n\n  /// Executes `_buildNextLabel` behavior for this component/composite.\n  Widget _buildNextLabel(ShadcnLocalizations localizations, bool showLabel) {\n    if (showLabel) {\n      return GhostButton(\n        onPressed: hasNext ? () => onPageChanged(page + 1) : null,\n        trailing: const Icon(RadixIcons.chevronRight).iconXSmall(),\n        child: Text(localizations.buttonNext),\n      );\n    }\n    return GhostButton(\n      onPressed: hasNext ? () => onPageChanged(page + 1) : null,\n      child: const Icon(RadixIcons.chevronRight).iconXSmall(),\n    );\n  }\n\n  @override\n  /// Executes `build` behavior for this component/composite.\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n\n    /// Stores `scaling` state/configuration for this implementation.\n    final scaling = theme.scaling;\n    final compTheme = ComponentTheme.maybeOf<PaginationTheme>(context);\n    final gapValue = styleValue(\n      widgetValue: gap,\n      themeValue: compTheme?.gap,\n      defaultValue: 4 * scaling,\n    );\n    final showLabel = styleValue(\n      widgetValue: this.showLabel,\n      themeValue: compTheme?.showLabel,\n      defaultValue: true,\n    );\n    final localizations = ShadcnLocalizations.of(context);\n\n    /// Stores `rowChildren` state/configuration for this implementation.\n    final rowChildren = <Widget>[];\n    if (!hidePreviousOnFirstPage || hasPrevious) {\n      rowChildren.add(_buildPreviousLabel(localizations, showLabel));\n    }\n    if (hasMorePreviousPages) {\n      if (showSkipToFirstPage && firstShownPage - 1 > 1) {\n        /// Creates a `rowChildren.add` instance.\n        rowChildren.add(\n          /// Creates a `GhostButton` instance.\n          GhostButton(\n            onPressed: () => onPageChanged(1),\n            child: const Text('1'),\n          ),\n        );\n      }\n\n      /// Creates a `rowChildren.add` instance.\n      rowChildren.add(\n        /// Creates a `GhostButton` instance.\n        GhostButton(\n          onPressed: () => onPageChanged(firstShownPage - 1),\n          child: const MoreDots(),\n        ),\n      );\n    }\n    for (final p in pages) {\n      if (p == page) {\n        /// Creates a `rowChildren.add` instance.\n        rowChildren.add(\n          /// Creates a `OutlineButton` instance.\n          OutlineButton(onPressed: () => onPageChanged(p), child: Text('\$p')),\n        );\n      } else {\n        /// Creates a `rowChildren.add` instance.\n        rowChildren.add(\n          /// Creates a `GhostButton` instance.\n          GhostButton(onPressed: () => onPageChanged(p), child: Text('\$p')),\n        );\n      }\n    }\n    if (hasMoreNextPages) {\n      /// Creates a `rowChildren.add` instance.\n      rowChildren.add(\n        /// Creates a `GhostButton` instance.\n        GhostButton(\n          onPressed: () => onPageChanged(lastShownPage + 1),\n          child: const MoreDots(),\n        ),\n      );\n      if (showSkipToLastPage && lastShownPage + 1 < totalPages) {\n        /// Creates a `rowChildren.add` instance.\n        rowChildren.add(\n          /// Creates a `GhostButton` instance.\n          GhostButton(\n            onPressed: () => onPageChanged(totalPages),\n            child: Text('\$totalPages'),\n          ),\n        );\n      }\n    }\n    if (!hideNextOnLastPage || hasNext) {\n      rowChildren.add(_buildNextLabel(localizations, showLabel));\n    }\n\n    return IntrinsicHeight(\n      child: Row(\n        mainAxisSize: MainAxisSize.min,\n        crossAxisAlignment: CrossAxisAlignment.stretch,\n        children: _applyGap(rowChildren, gapValue),\n      ),\n    );\n  }\n\n  /// Executes `_applyGap` behavior for this component/composite.\n  static List<Widget> _applyGap(List<Widget> children, double gap) {\n    if (gap <= 0 || children.length <= 1) {\n      return children;\n    }\n\n    /// Stores `spaced` state/configuration for this implementation.\n    final spaced = <Widget>[];\n    for (var i = 0; i < children.length; i++) {\n      spaced.add(children[i]);\n      if (i < children.length - 1) {\n        spaced.add(SizedBox(width: gap));\n      }\n    }\n    return spaced;\n  }\n}\n",
  "{installPath}/components/navigation/pagination/pagination.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:flutter/widgets.dart';\n\nimport '../../../shared/icons/radix_icons.dart';\nimport '../../../shared/localizations/shadcn_localizations.dart';\nimport '../../../shared/primitives/icon_extensions.dart';\nimport '../../../shared/theme/theme.dart';\nimport '../../../shared/utils/style_value.dart';\nimport '../../control/button/button.dart';\nimport '../../display/triple_dots/triple_dots.dart';\npart '_impl/core/pagination_2.dart';\n\n/// Theme data for customizing [Pagination] appearance.\nclass PaginationTheme extends ComponentThemeData {\n  /// Stores `gap` state/configuration for this implementation.\n  final double? gap;\n\n  /// Stores `showLabel` state/configuration for this implementation.\n  final bool? showLabel;\n\n  /// Creates a `PaginationTheme` instance.\n  const PaginationTheme({\n    super.themeDensity,\n    super.themeSpacing,\n    super.themeShadows,\n    this.gap,\n    this.showLabel,\n  });\n\n  /// Creates a `PaginationTheme` instance.\n  PaginationTheme copyWith({\n    ValueGetter<double?>? gap,\n    ValueGetter<bool?>? showLabel,\n  }) {\n    return PaginationTheme(\n      gap: gap == null ? this.gap : gap(),\n      showLabel: showLabel == null ? this.showLabel : showLabel(),\n    );\n  }\n\n  @override\n  /// Executes `operator ==` behavior for this component/composite.\n  bool operator ==(Object other) {\n    if (identical(this, other)) return true;\n    return other is PaginationTheme &&\n        other.gap == gap &&\n        other.showLabel == showLabel;\n  }\n\n  @override\n  int get hashCode => Object.hash(gap, showLabel);\n}\n\n/// Widget that renders pagination controls with page buttons and navigation arrows.\n",
