  "{installPath}/components/utility/color/_impl/core/sweep_color_gradient.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../color.dart';\n\n/// A sweep (angular/conical) gradient for color values.\n///\n/// Creates a gradient that sweeps around a center point.\nclass SweepColorGradient extends ColorGradient {\n  /// The color stops defining the gradient.\n  final List<ColorStop> colors;\n\n  /// How the gradient tiles beyond its bounds.\n  final TileMode tileMode;\n\n  /// The center point of the gradient.\n  final AlignmentGeometry center;\n\n  /// The starting angle in radians.\n  final double startAngle;\n\n  /// The ending angle in radians.\n  final double endAngle;\n\n  /// Creates a sweep color gradient.\n  const SweepColorGradient({\n    required this.colors,\n    this.tileMode = TileMode.clamp,\n    this.center = Alignment.center,\n    this.startAngle = 0.0,\n    this.endAngle = pi * 2,\n  });\n\n  @override\n  /// Creates a `SweepColorGradient` instance.\n  SweepColorGradient copyWith({\n    List<ColorStop>? colors,\n    TileMode? tileMode,\n    AlignmentGeometry? center,\n    double? startAngle,\n    double? endAngle,\n  }) {\n    return SweepColorGradient(\n      colors: colors ?? this.colors,\n      tileMode: tileMode ?? this.tileMode,\n      center: center ?? this.center,\n      startAngle: startAngle ?? this.startAngle,\n      endAngle: endAngle ?? this.endAngle,\n    );\n  }\n\n  @override\n  /// Executes `changeColorAt` behavior for this component/composite.\n  SweepColorGradient changeColorAt(int index, ColorDerivative color) {\n    List<ColorStop> newColors = List.from(colors);\n    newColors[index] = ColorStop(\n      color: color,\n      position: newColors[index].position,\n    );\n    return copyWith(colors: newColors);\n  }\n\n  @override\n  /// Executes `changePositionAt` behavior for this component/composite.\n  SweepColorGradient changePositionAt(int index, double position) {\n    List<ColorStop> newColors = List.from(colors);\n    newColors[index] = ColorStop(\n      color: newColors[index].color,\n      position: position,\n    );\n    return copyWith(colors: newColors);\n  }\n\n  @override\n  /// Creates a `SweepColorGradient` instance.\n  SweepColorGradient changeColorAndPositionAt(\n    int index,\n    ColorDerivative color,\n    double position,\n  ) {\n    List<ColorStop> newColors = List.from(colors);\n    newColors[index] = ColorStop(color: color, position: position);\n    return copyWith(colors: newColors);\n  }\n\n  @override\n  ({SweepColorGradient gradient, int index}) insertColorAt(\n    ColorDerivative color,\n    Offset position,\n    Size size,\n    TextDirection textDirection,\n  ) {\n    Alignment alignCenter = center.resolve(textDirection);\n    final px = (position.dx / size.width) * 2 - 1;\n    final py = (position.dy / size.height) * 2 - 1;\n\n    /// Stores `dx` state/configuration for this implementation.\n    final dx = px - alignCenter.x;\n\n    /// Stores `dy` state/configuration for this implementation.\n    final dy = py - alignCenter.y;\n    final angle = atan2(dy, dx);\n\n    /// Stores `normalizedAngle` state/configuration for this implementation.\n    double normalizedAngle = angle;\n    if (normalizedAngle < startAngle) {\n      normalizedAngle += pi * 2;\n    }\n\n    /// Stores `totalAngle` state/configuration for this implementation.\n    final totalAngle = endAngle - startAngle;\n    final pos = ((normalizedAngle - startAngle) / totalAngle).clamp(0.0, 1.0);\n    List<ColorStop> newColors = List.from(colors);\n\n    /// Stores `insertIndex` state/configuration for this implementation.\n    int insertIndex = 0;\n    for (int i = 0; i < newColors.length; i++) {\n      if (newColors[i].position < pos) {\n        insertIndex = i + 1;\n      }\n    }\n    newColors.insert(insertIndex, ColorStop(color: color, position: pos));\n    return (gradient: copyWith(colors: newColors), index: insertIndex);\n  }\n\n  @override\n  /// Executes `toGradient` behavior for this component/composite.\n  SweepGradient toGradient() {\n    return SweepGradient(\n      colors: colors.map((e) => e.color.toColor()).toList(),\n      stops: colors.map((e) => e.position).toList(),\n      center: center,\n      startAngle: startAngle,\n      endAngle: endAngle,\n      tileMode: tileMode,\n    );\n  }\n}\n",
  "{installPath}/components/utility/color/_impl/utils/color_stop.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../color.dart';\n\n/// Represents a color stop in a gradient with a specific color and position.\n///\n/// A color stop defines where a particular color appears along a gradient.\n/// The position is typically a value between 0.0 (start) and 1.0 (end).\n///\n/// Example:\n/// ```dart\n/// const stop = ColorStop(\n///   color: ColorDerivative.fromColor(Colors.blue),\n///   position: 0.5, // Middle of the gradient\n/// );\n/// ```\nclass ColorStop {\n  /// The color at this stop.\n  final ColorDerivative color;\n\n  /// The position of this stop along the gradient, typically from 0.0 to 1.0.\n  final double position;\n\n  /// Creates a [ColorStop] with the specified [color] and [position].\n  const ColorStop({required this.color, required this.position});\n}\n",
  "{installPath}/components/utility/color/_impl/utils/directional_gradient_angle.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../color.dart';\n\n/// A directional gradient angle that is aware of text direction.\n///\n/// [DirectionalGradientAngle] uses [AlignmentDirectional] for its alignments,\n/// making it responsive to the text direction (LTR or RTL). The angle is specified\n/// in radians and determines the direction of the gradient.\n///\n/// Example:\n/// ```dart\n/// const angle = DirectionalGradientAngle(0.0); // 0 radians (horizontal)\n/// final begin = angle.begin; // Start alignment\n/// final end = angle.end;     // End alignment\n/// ```\nclass DirectionalGradientAngle extends GradientAngleGeometry {\n  @override\n  /// The angle of the gradient in radians.\n  final double angle;\n\n  /// Creates a [DirectionalGradientAngle] with the specified [angle] in radians.\n  const DirectionalGradientAngle(this.angle);\n\n  @override\n  /// The beginning alignment calculated from the angle.\n  AlignmentGeometry get begin {\n    final x = 0.5 + 0.5 * cos(angle);\n    final y = 0.5 + 0.5 * sin(angle);\n    return AlignmentDirectional(x * 2 - 1, y * 2 - 1);\n  }\n\n  @override\n  /// The ending alignment calculated from the angle.\n  AlignmentGeometry get end {\n    final x = 0.5 + 0.5 * cos(angle + pi);\n    final y = 0.5 + 0.5 * sin(angle + pi);\n    return AlignmentDirectional(x * 2 - 1, y * 2 - 1);\n  }\n}\n",
  "{installPath}/components/utility/color/_impl/utils/gradient_angle.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../color.dart';\n\n/// A non-directional gradient angle that uses standard [Alignment].\n///\n/// Unlike [DirectionalGradientAngle], this class uses non-directional [Alignment]\n/// and is not affected by text direction. The angle is specified in radians.\n///\n/// Example:\n/// ```dart\n/// const angle = GradientAngle(pi / 4); // 45 degrees\n/// final begin = angle.begin;\n/// final end = angle.end;\n/// ```\nclass GradientAngle extends GradientAngleGeometry {\n  @override\n  /// The angle of the gradient in radians.\n  final double angle;\n\n  /// Creates a [GradientAngle] with the specified [angle] in radians.\n  const GradientAngle(this.angle);\n\n  @override\n  /// The beginning alignment calculated from the angle.\n  AlignmentGeometry get begin {\n    final x = 0.5 + 0.5 * cos(angle);\n    final y = 0.5 + 0.5 * sin(angle);\n    return Alignment(x * 2 - 1, y * 2 - 1);\n  }\n\n  @override\n  /// The ending alignment calculated from the angle.\n  AlignmentGeometry get end {\n    final x = 0.5 + 0.5 * cos(angle + pi);\n    final y = 0.5 + 0.5 * sin(angle + pi);\n    return Alignment(x * 2 - 1, y * 2 - 1);\n  }\n}\n",
  "{installPath}/components/utility/color/_impl/utils/gradient_angle_geometry.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../color.dart';\n\n/// An abstract base class for representing gradient angles with alignment geometry.\n///\n/// [GradientAngleGeometry] provides an interface for converting between angular\n/// representation and alignment-based gradients. It supports both directional\n/// (text-direction-aware) and non-directional gradient angles.\n///\n/// Subclasses should implement how to calculate begin and end alignments based\n/// on the angle value.\nabstract class GradientAngleGeometry {\n  /// Creates a const [GradientAngleGeometry].\n  const GradientAngleGeometry();\n\n  /// The angle of the gradient in radians.\n  double get angle;\n\n  /// The beginning alignment of the gradient.\n  AlignmentGeometry get begin;\n\n  /// The ending alignment of the gradient.\n  AlignmentGeometry get end;\n\n  /// Converts this to a directional gradient angle.\n  ///\n  /// Returns: A [DirectionalGradientAngle] based on this angle.\n  DirectionalGradientAngle toDirectional() {\n    return DirectionalGradientAngle(angle);\n  }\n\n  /// Converts this to a non-directional gradient angle.\n  ///\n  /// Returns: A [GradientAngle] based on this angle.\n  GradientAngle toNonDirectional() {\n    return GradientAngle(angle);\n  }\n}\n",
  "{installPath}/components/utility/color/color.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'dart:math';\n\nimport 'package:flutter/foundation.dart';\nimport 'package:flutter/painting.dart';\n\npart '_impl/core/color_derivative.dart';\npart '_impl/core/color_gradient.dart';\npart '_impl/core/hsl_color_derivative.dart';\npart '_impl/core/hsv_color_derivative.dart';\npart '_impl/core/linear_color_gradient.dart';\npart '_impl/core/radial_color_gradient.dart';\npart '_impl/core/sweep_color_gradient.dart';\npart '_impl/utils/color_stop.dart';\npart '_impl/utils/directional_gradient_angle.dart';\npart '_impl/utils/gradient_angle.dart';\npart '_impl/utils/gradient_angle_geometry.dart';\n\n/// Converts a [Color] to its hexadecimal string representation.\n///\n/// This function transforms a Flutter [Color] object into a hex string format\n/// commonly used in CSS and design tools. The output can optionally include\n/// the alpha (transparency) channel and a hash (#) prefix.\n///\n/// Parameters:\n/// - [color]: The color to convert to hexadecimal format.\n/// - [showAlpha]: Whether to include the alpha channel in the output. Defaults to `false`.\n///   When `true`, the alpha value is prepended to the RGB values (ARGB format).\n/// - [hashPrefix]: Whether to prefix the output with '#'. Defaults to `true`.\n///\n/// Returns:\n/// A hexadecimal string representation of the color. Format varies based on parameters:\n/// - With alpha and hash: `#AARRGGBB` (e.g., `#FF0080FF`)\n/// - Without alpha, with hash: `#RRGGBB` (e.g., `#0080FF`)\n/// - With alpha, no hash: `AARRGGBB`\n/// - Without alpha, no hash: `RRGGBB`\n///\n/// Example:\n/// ```dart\n/// final color = Color.fromARGB(255, 0, 128, 255);\n/// print(colorToHex(color)); // Output: #0080FF\n/// print(colorToHex(color, true)); // Output: #FF0080FF\n/// print(colorToHex(color, false, false)); // Output: 0080FF\n/// ```\nString colorToHex(\n  Color color, [\n  bool showAlpha = false,\n  bool hashPrefix = true,\n]) {\n  String r = ((color.r * 255).round() & 0xFF).toRadixString(16).padLeft(2, '0');\n  String g = ((color.g * 255).round() & 0xFF).toRadixString(16).padLeft(2, '0');\n  String b = ((color.b * 255).round() & 0xFF).toRadixString(16).padLeft(2, '0');\n  if (showAlpha) {\n    String a = ((color.a * 255).round() & 0xFF)\n        .toRadixString(16)\n        .padLeft(2, '0');\n    return hashPrefix ? '#\$a\$r\$g\$b' : '\$a\$r\$g\$b';\n  } else {\n    return hashPrefix ? '#\$r\$g\$b' : '\$r\$g\$b';\n  }\n}\n",
  "{installPath}/components/utility/locale_utils/_impl/core/date_part.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../locale_utils.dart';\n\n/// Represents a part of a date (year, month, or day).\n///\n/// Provides metadata and operations for individual date components.\nenum DatePart {\n  /// Year component (4 digits).\n  year(_getYear, _computeYearValueRange, length: 4),\n\n  /// Month component.\n  month(_getMonth, _computeMonthValueRange),\n\n  /// Day component.\n  day(_getDay, _computeDayValueRange);\n\n  /// Function that extracts the date/time component value from a DateTime.\n  final int Function(DateTime dateTime) getter;\n\n  /// Maximum number of digits for this date component.\n  final int length;\n\n  /// Function that computes the valid value range for this component.\n  ///\n  /// Takes a map of already-set date component values and returns the\n  /// minimum and maximum valid values for this component, considering\n  /// constraints like month lengths or leap years.\n  final (int? min, int? max) Function(Map<DatePart, int> values)\n  computeValueRange;\n\n  const DatePart(this.getter, this.computeValueRange, {this.length = 2});\n}\n",
  "{installPath}/components/utility/locale_utils/_impl/core/duration_part.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../locale_utils.dart';\n\n/// Represents a part of a duration (day, hour, minute, or second).\nenum DurationPart {\n  /// Day component.\n  day(_getDurationDay, _computeDurationDayValueRange),\n\n  /// Hour component.\n  hour(_getDurationHour, _computeDurationHourValueRange),\n\n  /// Minute component.\n  minute(_getDurationMinute, _computeDurationMinuteValueRange),\n\n  /// Second component.\n  second(_getDurationSecond, _computeDurationSecondValueRange);\n\n  /// Function that extracts the duration component value from a Duration.\n  final int Function(Duration duration) getter;\n\n  /// Function that computes the valid value range for this component.\n  final (int? min, int? max) Function(Map<DurationPart, int> values)\n  computeValueRange;\n\n  const DurationPart(this.getter, this.computeValueRange);\n}\n",
  "{installPath}/components/utility/locale_utils/_impl/core/time_part.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../locale_utils.dart';\n\n/// Represents a part of a time (hour, minute, or second).\nenum TimePart {\n  /// Hour component.\n  hour(_getTimeHour, _computeTimeHourValueRange),\n\n  /// Minute component.\n  minute(_getTimeMinute, _computeTimeMinuteValueRange),\n\n  /// Second component.\n  second(_getTimeSecond, _computeTimeSecondValueRange);\n\n  /// Function that extracts the time component value from a TimeOfDay.\n  final int Function(TimeOfDay time) getter;\n\n  /// Function that computes the valid value range for this component.\n  final (int? min, int? max) Function(Map<TimePart, int> values)\n  computeValueRange;\n\n  const TimePart(this.getter, this.computeValueRange);\n}\n",
  "{installPath}/components/utility/locale_utils/locale_utils.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'dart:math';\n\nimport '../../../shared/utils/util.dart';\n\npart '_impl/core/date_part.dart';\npart '_impl/core/duration_part.dart';\npart '_impl/core/time_part.dart';\n\n/// Configuration for file size unit formatting.\n///\n/// Defines the base (1024 for binary) and unit labels for formatting\n/// file sizes and data volumes.\nclass SizeUnitLocale {\n  /// Base for unit conversion (typically 1024 for binary units).\n  final int base;\n\n  /// List of unit labels (e.g., ['B', 'KB', 'MB', 'GB']).\n  final List<String> units;\n\n  /// Separator for digit grouping (e.g., ',' for 1,000,000).\n  final String separator;\n\n  /// Creates a [SizeUnitLocale].\n  ///\n  /// Parameters:\n  /// - [base] (`int`, required): Base for unit conversion.\n  /// - [units] (`List<String>`, required): Unit labels.\n  /// - [separator] (`String`, default: ','): Digit separator.\n  const SizeUnitLocale(this.base, this.units, {this.separator = ','});\n\n  /// Standard file size units in bytes (B, KB, MB, GB, etc.).\n  static const SizeUnitLocale fileBytes = _fileByteUnits;\n\n  /// Binary file size units (Bi, KiB, MiB, GiB, etc.).\n  static const SizeUnitLocale fileBits = _fileBitUnits;\n\n  /// Gets the appropriate unit label for a value.\n  ///\n  /// Parameters:\n  /// - [value] (`int`, required): The value to get unit for.\n  ///\n  /// Returns: `String` — the unit label.\n  String getUnit(int value) {\n    if (value <= 0) return '0 \${units[0]}';\n    var log10 = _log10(value);\n    final digitGroups = (log10 / _log10(base)).floor();\n    final unitIndex = min(digitGroups, units.length - 1);\n    return units[unitIndex];\n  }\n}\n\nconst _fileByteUnits = SizeUnitLocale(1024, [\n  'B',\n  'KB',\n  'MB',\n  'GB',\n  'TB',\n  'PB',\n  'EB',\n  'ZB',\n  'YB',\n]);\nconst _fileBitUnits = SizeUnitLocale(1024, [\n  'Bi',\n  'KiB',\n  'MiB',\n  'GiB',\n  'TiB',\n  'PiB',\n  'EiB',\n  'ZiB',\n  'YiB',\n]);\n\n/// Executes `_log10` behavior for this component/composite.\ndouble _log10(num x) {\n  return log(x) / ln10;\n}\n\n/// Formats a file size in bytes to a human-readable string.\n///\n/// Converts byte values to appropriate units (B, KB, MB, GB, etc.) based\n/// on the provided locale unit configuration.\n///\n/// Parameters:\n/// - [bytes] (`int`, required): File size in bytes.\n/// - [unit] (`SizeUnitLocale`, required): Unit locale configuration.\n///\n/// Returns: `String` — formatted file size with unit.\n///\n/// Example:\n/// ```dart\n/// formatFileSize(1024, SizeUnitLocale.fileBytes) // \"1 KB\"\n/// formatFileSize(1536, SizeUnitLocale.fileBytes) // \"1.5 KB\"\n/// ```\nString formatFileSize(int bytes, SizeUnitLocale unit) {\n  if (bytes <= 0) return '0 \${unit.units[0]}';\n\n  /// Stores `base` state/configuration for this implementation.\n  final base = unit.base;\n\n  /// Stores `units` state/configuration for this implementation.\n  final units = unit.units;\n  int digitGroups = (_log10(bytes) / _log10(base)).floor();\n  // return '\${NumberFormat('#,##0.#').format(bytes / pow(base, digitGroups))} \${units[digitGroups]}';\n  // do it without NumberFormat, but format to #,##0.# format\n  final value = bytes / pow(base, digitGroups);\n  final formattedValue = value.toStringAsFixed(\n    /// Creates a `value.truncateToDouble` instance.\n    value.truncateToDouble() == value ? 0 : 1,\n  );\n  return '\$formattedValue \${units[digitGroups]}';\n}\n\n/// Executes `_getYear` behavior for this component/composite.\nint _getYear(DateTime dateTime) => dateTime.year;\n\n/// Executes `_getMonth` behavior for this component/composite.\nint _getMonth(DateTime dateTime) => dateTime.month;\n\n/// Executes `_getDay` behavior for this component/composite.\nint _getDay(DateTime dateTime) => dateTime.day;\n\n(int? min, int? max) _computeYearValueRange(Map<DatePart, int> values) {\n  return (null, null);\n}\n\n(int? min, int? max) _computeMonthValueRange(Map<DatePart, int> values) {\n  return (1, 12);\n}\n\n(int? min, int? max) _computeDayValueRange(Map<DatePart, int> values) {\n  /// Stores `year` state/configuration for this implementation.\n  final year = values[DatePart.year];\n\n  /// Stores `month` state/configuration for this implementation.\n  final month = values[DatePart.month];\n  if (year == null || month == null) return (1, 31);\n  final daysInMonth = DateTime(year, month + 1, 0).day;\n  return (1, daysInMonth);\n}\n\n/// Executes `_getDurationDay` behavior for this component/composite.\nint _getDurationDay(Duration duration) => duration.inDays;\n\n/// Executes `_getDurationHour` behavior for this component/composite.\nint _getDurationHour(Duration duration) => duration.inHours % 24;\n\n/// Executes `_getDurationMinute` behavior for this component/composite.\nint _getDurationMinute(Duration duration) => duration.inMinutes % 60;\n\n/// Executes `_getDurationSecond` behavior for this component/composite.\nint _getDurationSecond(Duration duration) => duration.inSeconds % 60;\n\n(int? min, int? max) _computeDurationDayValueRange(\n  Map<DurationPart, int> values,\n) => (0, null);\n(int? min, int? max) _computeDurationHourValueRange(\n  Map<DurationPart, int> values,\n) => (0, 23);\n(int? min, int? max) _computeDurationMinuteValueRange(\n  Map<DurationPart, int> values,\n) => (0, 59);\n(int? min, int? max) _computeDurationSecondValueRange(\n  Map<DurationPart, int> values,\n) => (0, 59);\n\n/// Executes `_getTimeHour` behavior for this component/composite.\nint _getTimeHour(TimeOfDay time) => time.hour;\n\n/// Executes `_getTimeMinute` behavior for this component/composite.\nint _getTimeMinute(TimeOfDay time) => time.minute;\n\n/// Executes `_getTimeSecond` behavior for this component/composite.\nint _getTimeSecond(TimeOfDay time) => time.second;\n\n(int? min, int? max) _computeTimeHourValueRange(Map<TimePart, int> values) =>\n    (0, 23);\n(int? min, int? max) _computeTimeMinuteValueRange(Map<TimePart, int> values) =>\n    (0, 59);\n(int? min, int? max) _computeTimeSecondValueRange(Map<TimePart, int> values) =>\n    (0, 59);\n",
