\n    /// Stores `anchorSize` state/configuration for this implementation.\n    Size? anchorSize;\n    if (position == null) {\n      RenderBox renderBox = context.findRenderObject() as RenderBox;\n      Offset pos = renderBox.localToGlobal(Offset.zero);\n      anchorSize ??= renderBox.size;\n      position = Offset(\n        pos.dx +\n            anchorSize.width / 2 +\n            anchorSize.width / 2 * resolvedAnchorAlignment.x,\n        pos.dy +\n            anchorSize.height / 2 +\n            anchorSize.height / 2 * resolvedAnchorAlignment.y,\n      );\n    }\n    final OverlayPopoverEntry<T> popoverEntry = OverlayPopoverEntry();\n\n    /// Stores `completer` state/configuration for this implementation.\n    final completer = popoverEntry.completer;\n\n    /// Stores `animationCompleter` state/configuration for this implementation.\n    final animationCompleter = popoverEntry.animationCompleter;\n    ValueNotifier<bool> isClosed = ValueNotifier(false);\n\n    /// Stores `barrierEntry` state/configuration for this implementation.\n    OverlayEntry? barrierEntry;\n\n    /// Stores `overlayEntry` state/configuration for this implementation.\n    late OverlayEntry overlayEntry;\n    if (modal) {\n      if (consumeOutsideTaps) {\n        barrierEntry = OverlayEntry(\n          builder: (context) {\n            return GestureDetector(\n              onTap: () {\n                if (!barrierDismissable || isClosed.value) return;\n                isClosed.value = true;\n                completer.complete();\n              },\n            );\n          },\n        );\n      } else {\n        barrierEntry = OverlayEntry(\n          builder: (context) {\n            return Listener(\n              behavior: HitTestBehavior.translucent,\n              onPointerDown: (event) {\n                if (!barrierDismissable || isClosed.value) return;\n                isClosed.value = true;\n                completer.complete();\n              },\n            );\n          },\n        );\n      }\n    }\n\n    overlayEntry = OverlayEntry(\n      builder: (innerContext) {\n        return RepaintBoundary(\n          child: AnimatedBuilder(\n            animation: isClosed,\n            builder: (innerContext, child) {\n              return FocusScope(\n                autofocus: dismissBackdropFocus,\n                canRequestFocus: !isClosed.value,\n                child: AnimatedValueBuilder<double>(\n                  value: isClosed.value ? 0.0 : 1.0,\n                  initialValue: 0.0,\n                  curve: isClosed.value\n                      ? const Interval(0, 2 / 3)\n                      : Curves.linear,\n                  duration: isClosed.value\n                      ? (showDuration ?? kDefaultDuration)\n                      : (dismissDuration ?? const Duration(milliseconds: 100)),\n                  onEnd: (value) {\n                    if (value == 0.0 && isClosed.value) {\n                      popoverEntry.remove();\n                      popoverEntry.dispose();\n                      animationCompleter.complete();\n                    }\n                  },\n                  builder: (innerContext, animation, child) {\n                    var popoverAnchor = PopoverOverlayWidget(\n                      animation: animation,\n                      onTapOutside: () {\n                        if (isClosed.value) return;\n                        if (!modal) {\n                          isClosed.value = true;\n                          completer.complete();\n                        }\n                      },\n                      key: key,\n                      anchorContext: context,\n                      position: position!,\n                      alignment: resolvedAlignment,\n                      themes: themes,\n                      builder: builder,\n                      anchorSize: anchorSize,\n                      // anchorAlignment: anchorAlignment ?? alignment * -1,\n                      anchorAlignment: resolvedAnchorAlignment,\n                      widthConstraint: widthConstraint,\n                      heightConstraint: heightConstraint,\n                      regionGroupId: regionGroupId,\n                      offset: offset,\n                      transitionAlignment: transitionAlignment,\n                      margin: margin,\n                      follow: follow,\n                      consumeOutsideTaps: consumeOutsideTaps,\n                      onTickFollow: onTickFollow,\n                      allowInvertHorizontal: allowInvertHorizontal,\n                      allowInvertVertical: allowInvertVertical,\n                      data: data,\n                      onClose: () {\n                        if (isClosed.value) return Future.value();\n                        isClosed.value = true;\n                        completer.complete();\n                        return animationCompleter.future;\n                      },\n                      onImmediateClose: () {\n                        popoverEntry.remove();\n                        completer.complete();\n                      },\n                      onCloseWithResult: (value) {\n                        if (isClosed.value) return Future.value();\n                        isClosed.value = true;\n                        completer.complete(value as T);\n                        return animationCompleter.future;\n                      },\n                    );\n                    return popoverAnchor;\n                  },\n                ),\n              );\n            },\n          ),\n        );\n      },\n    );\n    popoverEntry.initialize(overlayEntry, barrierEntry);\n    if (barrierEntry != null) {\n      overlay.insert(barrierEntry);\n    }\n    overlay.insert(overlayEntry);\n    return popoverEntry;\n  }\n}\n\n/// Internal widget for rendering popover overlays.\n///\n/// Manages positioning, constraints, and lifecycle of popover content\n/// relative to an anchor widget.\n",
  "{sharedPath}/primitives/animated_value_builder.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:flutter/widgets.dart';\n\npart '_impl/core/animated_value_builder.dart';\npart '_impl/state/__animated_value_builder_state.dart';\n\n/// Type alias for `AnimatedValueWidgetBuilder` used by public or internal APIs.\ntypedef AnimatedValueWidgetBuilder<T> =\n    Widget Function(BuildContext context, T value, Widget? child);\n\n/// Type alias for `AnimatedValueLerp` used by public or internal APIs.\ntypedef AnimatedValueLerp<T> = T? Function(T? a, T? b, double t);\n",
  "{sharedPath}/primitives/basic.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:flutter/widgets.dart';\n\nimport 'text.dart';\nimport '../theme/theme.dart';\nimport '../utils/style_value.dart';\n\npart '_impl/core/basic.dart';\npart '_impl/core/basic_layout.dart';\npart '_impl/core/label.dart';\npart '_impl/themes/basic_theme.dart';\n\n/// Theme configuration for [Basic] layout widgets.\n///\n/// Defines default alignment, spacing, and padding properties for Basic\n/// layout components. These properties control how leading, trailing, title,\n/// subtitle, and content elements are positioned and spaced.\n",
  "{sharedPath}/primitives/clickable.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:data_widget/data_widget.dart';\nimport 'package:flutter/foundation.dart';\nimport 'package:flutter/rendering.dart';\nimport 'package:flutter/scheduler.dart';\nimport 'package:flutter/services.dart';\nimport 'package:flutter/widgets.dart';\n\nimport 'animated_value_builder.dart';\nimport 'focus_outline.dart';\nimport '../theme/theme.dart';\nimport '../utils/constants.dart';\nimport '../utils/platform_utils.dart';\n\npart '_impl/core/__builder_stated_widget.dart';\npart '_impl/core/__map_stated_widget.dart';\npart '_impl/core/__param_stated_widget.dart';\npart '_impl/core/clickable.dart';\npart '_impl/core/stated_widget.dart';\npart '_impl/core/widget_states_data.dart';\npart '_impl/core/widget_states_provider.dart';\npart '_impl/state/__clickable_state.dart';\n\n/// Extension on `Set<WidgetState>` providing convenient boolean getters for common states.\n///\n/// This extension simplifies checking for widget states by providing readable\n/// property accessors instead of using `contains()` calls.\n///\n/// ## Example\n///\n/// ```dart\n/// Set<WidgetState> states = {WidgetState.hovered, WidgetState.focused};\n///\n/// if (states.hovered) {\n///   // Handle hover state\n/// }\n/// if (states.disabled) {\n///   // Handle disabled state\n/// }\n/// ```\nextension WidgetStateExtension on Set<WidgetState> {\n  /// Whether the widget is in a disabled state.\n  bool get disabled => contains(WidgetState.disabled);\n\n  /// Whether the widget is in an error state.\n  bool get error => contains(WidgetState.error);\n\n  /// Whether the widget is in a selected state.\n  bool get selected => contains(WidgetState.selected);\n\n  /// Whether the widget is in a pressed state.\n  bool get pressed => contains(WidgetState.pressed);\n\n  /// Whether the widget is in a hovered state.\n  bool get hovered => contains(WidgetState.hovered);\n\n  /// Whether the widget is in a focused state.\n  bool get focused => contains(WidgetState.focused);\n}\n\n/// An abstract widget that provides state-aware visual variations.\n///\n/// Enables widgets to display different appearances based on their current\n/// interactive state (disabled, selected, pressed, hovered, focused, error).\n/// The widget automatically selects the appropriate visual representation\n/// from provided alternatives based on a configurable state priority order.\n///\n/// Three factory constructors provide different approaches to state handling:\n/// - Default constructor: Explicit widgets for each state\n/// - `.map()`: Map-based state-to-widget associations\n/// - `.builder()`: Function-based dynamic state handling\n///\n/// The state resolution follows a priority order where earlier states in the\n/// order take precedence over later ones. This ensures consistent behavior\n/// when multiple states are active simultaneously.\n///\n/// Example:\n/// ```dart\n/// StatedWidget(\n///   child: Text('Default'),\n///   disabled: Text('Disabled State'),\n///   hovered: Text('Hovered State'),\n///   pressed: Text('Pressed State'),\n///   selected: Text('Selected State'),\n/// )\n/// ```\n",
