  "{sharedPath}/primitives/icon_extensions.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:flutter/widgets.dart';\n\nimport '../theme/theme.dart';\n\n/// Icon extension utilities used by command and other registry components.\nextension IconExtensions on Widget {\n  /// Applies the small icon theme to this widget.\n  Widget iconSmall() {\n    return Builder(\n      builder: (context) {\n        final theme = Theme.of(context);\n        final inherited = IconTheme.of(context);\n        return IconTheme(\n          data: theme.iconTheme.small.merge(inherited),\n          child: this,\n        );\n      },\n    );\n  }\n\n  /// Applies the extra-small icon theme to this widget.\n  Widget iconXSmall() {\n    return Builder(\n      builder: (context) {\n        final theme = Theme.of(context);\n        final inherited = IconTheme.of(context);\n        return IconTheme(\n          data: theme.iconTheme.xSmall.merge(inherited),\n          child: this,\n        );\n      },\n    );\n  }\n\n  /// Applies the extra-extra-extra-small icon theme to this widget.\n  Widget iconX3Small() {\n    return Builder(\n      builder: (context) {\n        final theme = Theme.of(context);\n        final inherited = IconTheme.of(context);\n        return IconTheme(\n          data: theme.iconTheme.x3Small.merge(inherited),\n          child: this,\n        );\n      },\n    );\n  }\n\n  /// Applies the muted foreground icon theme to this widget.\n  Widget iconMutedForeground() {\n    return Builder(\n      builder: (context) {\n        final theme = Theme.of(context);\n        final inherited = IconTheme.of(context);\n        return IconTheme(\n          data: IconThemeData(\n            color: theme.colorScheme.mutedForeground,\n          ).merge(inherited),\n          child: this,\n        );\n      },\n    );\n  }\n}\n",
  "{sharedPath}/primitives/menu_group.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:flutter/widgets.dart';\n\n/// Minimal menu group metadata shared across components.\n///\n/// This lightweight shape is enough for menu-aware components (like buttons)\n/// to adapt padding based on menu layout direction.\nclass MenuGroupData {\n  /// Layout direction (horizontal or vertical).\n  final Axis direction;\n\n  const MenuGroupData({required this.direction});\n}\n",
