  "{sharedPath}/primitives/sheet_overlay.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:data_widget/data_widget.dart';\nimport 'package:flutter/widgets.dart';\n\n/// Minimal helper for checking sheet overlay context.\nclass SheetOverlayHandler {\n  /// Returns true when the widget tree is inside a sheet overlay.\n  static bool isSheetOverlay(BuildContext context) {\n    return Model.maybeOf<bool>(context, #shadcn_flutter_sheet_overlay) == true;\n  }\n}\n",
  "{sharedPath}/primitives/slider_value.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'dart:ui';\n\n/// Represents a single-thumb or range slider value.\nclass SliderValue {\n  /// Stores `_start` state/configuration for this implementation.\n  final double? _start;\n\n  /// Stores `_end` state/configuration for this implementation.\n  final double _end;\n\n  /// Creates a `SliderValue.single` instance.\n  const SliderValue.single(double value) : _start = null, _end = value;\n\n  /// Creates a `SliderValue.ranged` instance.\n  const SliderValue.ranged(double start, double end)\n    : _start = start,\n      _end = end;\n\n  /// Stores `isRanged` state/configuration for this implementation.\n  bool get isRanged => _start != null;\n\n  /// Stores `start` state/configuration for this implementation.\n  double get start => _start ?? _end;\n\n  /// Stores `end` state/configuration for this implementation.\n  double get end => _end;\n\n  /// Stores `value` state/configuration for this implementation.\n  double get value => _end;\n\n  /// Executes `lerp` behavior for this component/composite.\n  static SliderValue? lerp(SliderValue? a, SliderValue? b, double t) {\n    if (a == null || b == null) return null;\n    if (a.isRanged && b.isRanged) {\n      return SliderValue.ranged(\n        /// Creates a `lerpDouble` instance.\n        lerpDouble(a.start, b.start, t)!,\n\n        /// Creates a `lerpDouble` instance.\n        lerpDouble(a.end, b.end, t)!,\n      );\n    } else if (!a.isRanged && !b.isRanged) {\n      return SliderValue.single(lerpDouble(a.value, b.value, t)!);\n    }\n    return null;\n  }\n\n  /// Executes `roundToDivisions` behavior for this component/composite.\n  SliderValue roundToDivisions(int divisions) {\n    if (!isRanged) {\n      return SliderValue.single((_end * divisions).round() / divisions);\n    }\n    return SliderValue.ranged(\n      (_start! * divisions).round() / divisions,\n      (_end * divisions).round() / divisions,\n    );\n  }\n\n  @override\n  /// Executes `operator ==` behavior for this component/composite.\n  bool operator ==(Object other) {\n    if (identical(this, other)) return true;\n    return other is SliderValue && other._start == _start && other._end == _end;\n  }\n\n  @override\n  int get hashCode => Object.hash(_start, _end);\n}\n",
  "{sharedPath}/primitives/subfocus.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:data_widget/data_widget.dart';\nimport 'package:flutter/widgets.dart';\n\npart '_impl/core/sub_focus.dart';\npart '_impl/core/sub_focus_scope.dart';\npart '_impl/state/__sub_focus_scope_state.dart';\npart '_impl/state/__sub_focus_state.dart';\n\n/// Callback function type for building SubFocusScope widgets.\n///\n/// Receives the build context and the scope state for managing focus\n/// within the scope's widget tree.\ntypedef SubFocusScopeBuilder =\n    Widget Function(BuildContext context, SubFocusScopeState state);\n\n/// Hierarchical focus management system for complex widget trees.\n///\n/// Creates a focus scope that manages keyboard navigation and focus traversal\n/// for child widgets. Provides centralized control over which child widget\n/// has focus and handles focus navigation between multiple focusable elements.\n///\n/// Key Features:\n/// - **Focus Hierarchy**: Manages focus relationships between parent and child widgets\n/// - **Keyboard Navigation**: Handles arrow key and tab navigation between elements\n/// - **Action Delegation**: Routes keyboard actions to currently focused child\n/// - **Auto-focus Support**: Automatically focuses first child when enabled\n/// - **Focus State Management**: Tracks and updates focus state across widget rebuilds\n/// - **Scroll Integration**: Ensures focused elements remain visible in scrollable areas\n///\n/// The scope maintains a list of attached [SubFocus] widgets and manages which\n/// one currently has focus. It handles focus traversal, action routing, and\n/// ensures focused widgets remain visible through scroll positioning.\n///\n/// Used commonly in:\n/// - Lists with keyboard navigation\n/// - Form field traversal\n/// - Menu and dropdown navigation\n/// - Tree view navigation\n/// - Tab panel systems\n///\n/// Example:\n/// ```dart\n/// SubFocusScope(\n///   autofocus: true,\n///   builder: (context, state) => Column(\n///     children: [\n///       SubFocus(\n///         builder: (context, focusState) => Container(\n///           color: focusState.isFocused ? Colors.blue : Colors.grey,\n///           child: Text('Item 1'),\n///         ),\n///       ),\n///       SubFocus(\n///         builder: (context, focusState) => Container(\n///           color: focusState.isFocused ? Colors.blue : Colors.grey,\n///           child: Text('Item 2'),\n///         ),\n///       ),\n///     ],\n///   ),\n/// )\n/// ```\n",
  "{sharedPath}/primitives/text.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'package:data_widget/data_widget.dart';\nimport 'package:flutter/material.dart' show SelectableText;\nimport 'package:flutter/widgets.dart';\n\nimport '../theme/theme.dart';\n\npart '_impl/core/__bullet_painter.dart';\npart '_impl/core/__rich_text_then_widget.dart';\npart '_impl/core/__selectable_text_then_widget.dart';\npart '_impl/core/__text_then_widget.dart';\npart '_impl/core/text_modifier.dart';\npart '_impl/core/unordered_list_data.dart';\npart '_impl/core/wrapped_text.dart';\n\n/// Abstract base class for text modifier widgets.\n///\n/// Text modifiers provide a fluent API for applying text styles and\n/// transformations. They extend [Widget] and can be called as functions\n/// to apply additional style properties.\n///\n/// Use the [TextExtension] methods to create and chain text modifiers.\n",
  "{sharedPath}/theme/_impl/core/adaptive_scaler.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../theme.dart';\n\n/// AdaptiveScaler defines a reusable type for this registry module.\nclass AdaptiveScaler extends StatelessWidget {\n  /// Gets the default adaptive scaling for the current context.\n  ///\n  /// Returns [AdaptiveScaling.mobile] for iOS/Android platforms,\n  /// [AdaptiveScaling.desktop] for other platforms.\n  static AdaptiveScaling defaultScalingOf(BuildContext context) {\n    final theme = Theme.of(context);\n    return defaultScaling(theme);\n  }\n\n  /// Gets the default adaptive scaling for the given theme.\n  ///\n  /// Returns [AdaptiveScaling.mobile] for iOS/Android platforms,\n  /// [AdaptiveScaling.desktop] for other platforms.\n  static AdaptiveScaling defaultScaling(ThemeData theme) {\n    switch (theme.platform) {\n      case TargetPlatform.iOS:\n      case TargetPlatform.android:\n        return AdaptiveScaling.mobile;\n      default:\n        return AdaptiveScaling.desktop;\n    }\n  }\n\n  /// The scaling to apply.\n  final AdaptiveScaling scaling;\n\n  /// The widget below this widget in the tree.\n  final Widget child;\n\n  /// Creates an [AdaptiveScaler].\n  ///\n  /// Parameters:\n  /// - [scaling] (`AdaptiveScaling`, required): Scaling factors to apply.\n  /// - [child] (`Widget`, required): Child widget.\n  const AdaptiveScaler({super.key, required this.scaling, required this.child});\n\n  @override\n  /// Executes `build` behavior for this component/composite.\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n    return Theme(data: scaling.scale(theme), child: child);\n  }\n}\n\n/// The theme data for shadcn_flutter.\n///\n/// Contains all theming information including colors, typography,\n/// scaling, and platform-specific settings.\n",
  "{sharedPath}/theme/_impl/core/adaptive_scaling.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../theme.dart';\n\n/// AdaptiveScaling defines a reusable type for this registry module.\nclass AdaptiveScaling {\n  /// Default scaling for desktop layouts (1.0).\n  static const AdaptiveScaling desktop = AdaptiveScaling();\n\n  /// Default scaling for mobile layouts (1.25x).\n  static const AdaptiveScaling mobile = AdaptiveScaling(1.25);\n\n  /// Scaling factor for border radius.\n  final double radiusScaling;\n\n  /// Scaling factor for component sizes.\n  final double sizeScaling;\n\n  /// Scaling factor for text.\n  final double textScaling;\n\n  /// Creates uniform [AdaptiveScaling] with the same factor for all properties.\n  ///\n  /// Parameters:\n  /// - [scaling] (`double`, default: 1): Scaling factor for radius, size, and text.\n  const AdaptiveScaling([double scaling = 1])\n    : this.only(\n        radiusScaling: scaling,\n        sizeScaling: scaling,\n        textScaling: scaling,\n      );\n\n  /// Creates [AdaptiveScaling] with individual scaling factors.\n  ///\n  /// Parameters:\n  /// - [radiusScaling] (`double`, default: 1): Border radius scaling factor.\n  /// - [sizeScaling] (`double`, default: 1): Size and spacing scaling factor.\n  /// - [textScaling] (`double`, default: 1): Text and icon scaling factor.\n  const AdaptiveScaling.only({\n    this.radiusScaling = 1,\n    this.sizeScaling = 1,\n    this.textScaling = 1,\n  });\n\n  /// Applies this scaling to a theme.\n  ///\n  /// Returns a new ThemeData with radius, sizing, typography, and icon theme\n  /// scaled according to this AdaptiveScaling's factors.\n  ///\n  /// Parameters:\n  /// - [theme] (ThemeData, required): Theme to scale\n  ///\n  /// Returns scaled ThemeData.\n  ThemeData scale(ThemeData theme) {\n    return theme.copyWith(\n      radius: radiusScaling == 1 ? null : () => theme.radius * radiusScaling,\n      scaling: sizeScaling == 1 ? null : () => theme.scaling * sizeScaling,\n      typography: textScaling == 1\n          ? null\n          : () => theme.typography.scale(textScaling),\n      iconTheme: textScaling == 1\n          ? null\n          : () => theme.iconTheme.scale(textScaling),\n    );\n  }\n\n  /// Linearly interpolates between two AdaptiveScaling instances.\n  ///\n  /// Creates a new AdaptiveScaling that represents a transition between [a] and [b]\n  /// at position [t]. When t=0, returns [a]; when t=1, returns [b].\n  ///\n  /// Parameters:\n  /// - [a] (AdaptiveScaling, required): Start scaling\n  /// - [b] (AdaptiveScaling, required): End scaling\n  /// - [t] (double, required): Interpolation position (0.0 to 1.0)\n  ///\n  /// Returns interpolated AdaptiveScaling.\n  static AdaptiveScaling lerp(AdaptiveScaling a, AdaptiveScaling b, double t) {\n    return AdaptiveScaling.only(\n      radiusScaling: lerpDouble(a.radiusScaling, b.radiusScaling, t)!,\n      sizeScaling: lerpDouble(a.sizeScaling, b.sizeScaling, t)!,\n      textScaling: lerpDouble(a.textScaling, b.textScaling, t)!,\n    );\n  }\n}\n\n/// A widget that applies adaptive scaling to its descendants.\n",
  "{sharedPath}/theme/_impl/core/chart_color_scheme.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../color_scheme.dart';\n\n/// ChartColorScheme defines a reusable type for this registry module.\nclass ChartColorScheme {\n  /// The list of chart colors.\n  final List<Color> chartColors;\n\n  /// Creates a chart color scheme with the given colors.\n  const ChartColorScheme(this.chartColors);\n\n  /// Creates a chart color scheme using a single color for all elements.\n  factory ChartColorScheme.single(Color color) {\n    return SingleChartColorScheme(color);\n  }\n\n  /// Color for the first chart series.\n  Color get chart1 => chartColors[0];\n\n  /// Color for the second chart series.\n  Color get chart2 => chartColors[1];\n\n  /// Color for the third chart series.\n  Color get chart3 => chartColors[2];\n\n  /// Color for the fourth chart series.\n  Color get chart4 => chartColors[3];\n\n  /// Color for the fifth chart series.\n  Color get chart5 => chartColors[4];\n}\n\n/// A collection of color shades from light to dark.\n///\n/// Implements both [Color] and [ColorSwatch] to provide a primary color\n/// and access to different shade values (50, 100, 200, ..., 950).\n",
  "{sharedPath}/theme/_impl/core/color_scheme.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\npart of '../../color_scheme.dart';\n\n/// ColorScheme defines a reusable type for this registry module.\nclass ColorScheme implements ChartColorScheme {\n  /// Returns the color scheme for the given context.\n  ///\n  /// Parameters:\n  /// - [context] (BuildContext, required): The build context.\n  ///\n  /// Returns the color scheme for the given context.\n  static ColorScheme of(BuildContext context) {\n    return Theme.of(context).colorScheme;\n  }\n\n  /// Set of recognized color key names for the color scheme.\n  ///\n  /// Contains all valid color property names that can be used when\n  /// constructing or serializing a ColorScheme.\n  static const Set<String> colorKeys = {\n    'background',\n    'foreground',\n    'card',\n    'cardForeground',\n    'popover',\n    'popoverForeground',\n    'primary',\n    'primaryForeground',\n    'secondary',\n    'secondaryForeground',\n    'muted',\n    'mutedForeground',\n    'accent',\n    'accentForeground',\n    'destructive',\n    'destructiveForeground',\n    'border',\n    'input',\n    'ring',\n    'chart1',\n    'chart2',\n    'chart3',\n    'chart4',\n    'chart5',\n  };\n\n  /// The brightness of this color scheme (light or dark).\n  final Brightness brightness;\n\n  /// The background color.\n  final Color background;\n\n  /// The foreground color (typically text).\n  final Color foreground;\n\n  /// The card background color.\n  final Color card;\n\n  /// The card foreground color.\n  final Color cardForeground;\n\n  /// The popover background color.\n  final Color popover;\n\n  /// The popover foreground color.\n  final Color popoverForeground;\n\n  /// The primary brand color.\n  final Color primary;\n\n  /// The foreground color for primary elements.\n  final Color primaryForeground;\n\n  /// The secondary color.\n  final Color secondary;\n\n  /// The foreground color for secondary elements.\n  final Color secondaryForeground;\n\n  /// The muted background color.\n  final Color muted;\n\n  /// The muted foreground color.\n  final Color mutedForeground;\n\n  /// The accent color.\n  final Color accent;\n\n  /// The foreground color for accented elements.\n  final Color accentForeground;\n\n  /// The destructive action color (typically red).\n  final Color destructive;\n\n  /// The foreground color for destructive elements.\n  @Deprecated('Legacy color')\n  final Color destructiveForeground;\n\n  /// The border color.\n  final Color border;\n\n  /// The input field border color.\n  final Color input;\n\n  /// The focus ring color.\n  final Color ring;\n\n  /// The sidebar background color.\n  final Color sidebar;\n\n  /// The sidebar foreground color.\n  final Color sidebarForeground;\n\n  /// The sidebar primary color.\n  final Color sidebarPrimary;\n\n  /// The sidebar primary foreground color.\n  final Color sidebarPrimaryForeground;\n\n  /// The sidebar accent color.\n  final Color sidebarAccent;\n\n  /// The sidebar accent foreground color.\n  final Color sidebarAccentForeground;\n\n  /// The sidebar border color.\n  final Color sidebarBorder;\n\n  /// The sidebar ring color.\n  final Color sidebarRing;\n\n  @override\n  /// Stores `chart1` state/configuration for this implementation.\n  final Color chart1;\n  @override\n  /// Stores `chart2` state/configuration for this implementation.\n  final Color chart2;\n  @override\n  /// Stores `chart3` state/configuration for this implementation.\n  final Color chart3;\n  @override\n  /// Stores `chart4` state/configuration for this implementation.\n  final Color chart4;\n  @override\n  /// Stores `chart5` state/configuration for this implementation.\n  final Color chart5;\n\n  /// Creates a color scheme with all required colors.\n  const ColorScheme({\n    required this.brightness,\n    required this.background,\n    required this.foreground,\n    required this.card,\n    required this.cardForeground,\n    required this.popover,\n    required this.popoverForeground,\n    required this.primary,\n    required this.primaryForeground,\n    required this.secondary,\n    required this.secondaryForeground,\n    required this.muted,\n    required this.mutedForeground,\n    required this.accent,\n    required this.accentForeground,\n    required this.destructive,\n    this.destructiveForeground = Colors.transparent,\n    required this.border,\n    required this.input,\n    required this.ring,\n    required this.chart1,\n    required this.chart2,\n    required this.chart3,\n    required this.chart4,\n    required this.chart5,\n    required this.sidebar,\n    required this.sidebarForeground,\n    required this.sidebarPrimary,\n    required this.sidebarPrimaryForeground,\n    required this.sidebarAccent,\n    required this.sidebarAccentForeground,\n    required this.sidebarBorder,\n    required this.sidebarRing,\n  });\n\n  /// Creates a color scheme from a map of color names to values.\n  ColorScheme.fromMap(Map<String, dynamic> map)\n    : background = map._col('background'),\n      foreground = map._col('foreground'),\n      card = map._col('card'),\n      cardForeground = map._col('cardForeground'),\n      popover = map._col('popover'),\n      popoverForeground = map._col('popoverForeground'),\n      primary = map._col('primary'),\n      primaryForeground = map._col('primaryForeground'),\n      secondary = map._col('secondary'),\n      secondaryForeground = map._col('secondaryForeground'),\n      muted = map._col('muted'),\n      mutedForeground = map._col('mutedForeground'),\n      accent = map._col('accent'),\n      accentForeground = map._col('accentForeground'),\n      destructive = map._col('destructive'),\n      // ignore: deprecated_member_use_from_same_package\n      destructiveForeground = map._col('destructiveForeground'),\n      border = map._col('border'),\n      input = map._col('input'),\n      ring = map._col('ring'),\n      chart1 = map._col('chart1'),\n      chart2 = map._col('chart2'),\n      chart3 = map._col('chart3'),\n      chart4 = map._col('chart4'),\n      chart5 = map._col('chart5'),\n      sidebar = map._col('sidebar'),\n      sidebarForeground = map._col('sidebarForeground'),\n      sidebarPrimary = map._col('sidebarPrimary'),\n      sidebarPrimaryForeground = map._col('sidebarPrimaryForeground'),\n      sidebarAccent = map._col('sidebarAccent'),\n      sidebarAccentForeground = map._col('sidebarAccentForeground'),\n      sidebarBorder = map._col('sidebarBorder'),\n      sidebarRing = map._col('sidebarRing'),\n      brightness =\n          Brightness.values\n              .where((element) => element.name == map['brightness'])\n              .firstOrNull ??\n          Brightness.light;\n\n  /// Converts the color scheme to a map of hex color strings.\n  ///\n  /// Returns a map where keys are color property names and values are\n  /// hex-encoded color strings (e.g., \"#RRGGBB\").\n  ///\n  /// Useful for serialization or CSS generation.\n  Map<String, String> toMap() {\n    return {\n      'background': hexFromColor(background),\n      'foreground': hexFromColor(foreground),\n      'card': hexFromColor(card),\n      'cardForeground': hexFromColor(cardForeground),\n      'popover': hexFromColor(popover),\n      'popoverForeground': hexFromColor(popoverForeground),\n      'primary': hexFromColor(primary),\n      'primaryForeground': hexFromColor(primaryForeground),\n      'secondary': hexFromColor(secondary),\n      'secondaryForeground': hexFromColor(secondaryForeground),\n      'muted': hexFromColor(muted),\n      'mutedForeground': hexFromColor(mutedForeground),\n      'accent': hexFromColor(accent),\n      'accentForeground': hexFromColor(accentForeground),\n      'destructive': hexFromColor(destructive),\n      // ignore: deprecated_member_use_from_same_package\n      'destructiveForeground': hexFromColor(destructiveForeground),\n      'border': hexFromColor(border),\n      'input': hexFromColor(input),\n      'ring': hexFromColor(ring),\n      'chart1': hexFromColor(chart1),\n      'chart2': hexFromColor(chart2),\n      'chart3': hexFromColor(chart3),\n      'chart4': hexFromColor(chart4),\n      'chart5': hexFromColor(chart5),\n      'sidebar': hexFromColor(sidebar),\n      'sidebarForeground': hexFromColor(sidebarForeground),\n      'sidebarPrimary': hexFromColor(sidebarPrimary),\n      'sidebarPrimaryForeground': hexFromColor(sidebarPrimaryForeground),\n      'sidebarAccent': hexFromColor(sidebarAccent),\n      'sidebarAccentForeground': hexFromColor(sidebarAccentForeground),\n      'sidebarBorder': hexFromColor(sidebarBorder),\n      'sidebarRing': hexFromColor(sidebarRing),\n      'brightness': brightness.name,\n    };\n  }\n\n  /// Converts the color scheme to a map of Color objects.\n  ///\n  /// Returns a map where keys are color property names and values are\n  /// Flutter Color objects.\n  ///\n  /// Useful for programmatic color access.\n  Map<String, Color> toColorMap() {\n    return {\n      'background': background,\n      'foreground': foreground,\n      'card': card,\n      'cardForeground': cardForeground,\n      'popover': popover,\n      'popoverForeground': popoverForeground,\n      'primary': primary,\n      'primaryForeground': primaryForeground,\n      'secondary': secondary,\n      'secondaryForeground': secondaryForeground,\n      'muted': muted,\n      'mutedForeground': mutedForeground,\n      'accent': accent,\n      'accentForeground': accentForeground,\n      'destructive': destructive,\n      // ignore: deprecated_member_use_from_same_package\n      'destructiveForeground': destructiveForeground,\n      'border': border,\n      'input': input,\n      'ring': ring,\n      'chart1': chart1,\n      'chart2': chart2,\n      'chart3': chart3,\n      'chart4': chart4,\n      'chart5': chart5,\n      'sidebar': sidebar,\n      'sidebarForeground': sidebarForeground,\n      'sidebarPrimary': sidebarPrimary,\n      'sidebarPrimaryForeground': sidebarPrimaryForeground,\n      'sidebarAccent': sidebarAccent,\n      'sidebarAccentForeground': sidebarAccentForeground,\n      'sidebarBorder': sidebarBorder,\n      'sidebarRing': sidebarRing,\n    };\n  }\n\n  /// Creates a ColorScheme from a map of colors.\n  ///\n  /// Constructs a ColorScheme by looking up color values from a map.\n  ///\n  /// Parameters:\n  /// - [colors] (`Map<String, Color>`, required): Map of color name to Color\n  /// - [brightness] (Brightness, required): Theme brightness (light or dark)\n  ///\n  /// Example:\n  /// ```dart\n  /// ColorScheme.fromColors(\n  ///   colors: {'background': Colors.white, 'foreground': Colors.black, ...},\n  ///   brightness: Brightness.light,\n  /// )\n  /// ```\n  ColorScheme.fromColors({\n    required Map<String, Color> colors,\n    required Brightness brightness,\n  }) : this(\n         brightness: brightness,\n         background: colors._col('background'),\n         foreground: colors._col('foreground'),\n         card: colors._col('card'),\n         cardForeground: colors._col('cardForeground'),\n         popover: colors._col('popover'),\n         popoverForeground: colors._col('popoverForeground'),\n         primary: colors._col('primary'),\n         primaryForeground: colors._col('primaryForeground'),\n         secondary: colors._col('secondary'),\n         secondaryForeground: colors._col('secondaryForeground'),\n         muted: colors._col('muted'),\n         mutedForeground: colors._col('mutedForeground'),\n         accent: colors._col('accent'),\n         accentForeground: colors._col('accentForeground'),\n         destructive: colors._col('destructive'),\n         destructiveForeground: colors._col('destructiveForeground'),\n         border: colors._col('border'),\n         input: colors._col('input'),\n         ring: colors._col('ring'),\n         chart1: colors._col('chart1'),\n         chart2: colors._col('chart2'),\n         chart3: colors._col('chart3'),\n         chart4: colors._col('chart4'),\n         chart5: colors._col('chart5'),\n         sidebar: colors._col('sidebar'),\n         sidebarForeground: colors._col('sidebarForeground'),\n         sidebarPrimary: colors._col('sidebarPrimary'),\n         sidebarPrimaryForeground: colors._col('sidebarPrimaryForeground'),\n         sidebarAccent: colors._col('sidebarAccent'),\n         sidebarAccentForeground: colors._col('sidebarAccentForeground'),\n         sidebarBorder: colors._col('sidebarBorder'),\n         sidebarRing: colors._col('sidebarRing'),\n       );\n\n  /// Creates a copy of this ColorScheme with specified properties replaced.\n  ///\n  /// Returns a new ColorScheme with any provided properties replaced.\n  /// Uses ValueGetter for each property to allow lazy evaluation.\n  ///\n  /// Parameters are ValueGetters for all color scheme properties. Only\n  /// provided parameters will be replaced in the copy.\n  ///\n  /// Example:\n  /// ```dart\n  /// scheme.copyWith(\n  ///   background: () => Colors.white,\n  ///   foreground: () => Colors.black,\n  /// )\n  /// ```\n  ColorScheme copyWith({\n    ValueGetter<Brightness>? brightness,\n    ValueGetter<Color>? background,\n    ValueGetter<Color>? foreground,\n    ValueGetter<Color>? card,\n    ValueGetter<Color>? cardForeground,\n    ValueGetter<Color>? popover,\n    ValueGetter<Color>? popoverForeground,\n    ValueGetter<Color>? primary,\n    ValueGetter<Color>? primaryForeground,\n    ValueGetter<Color>? secondary,\n    ValueGetter<Color>? secondaryForeground,\n    ValueGetter<Color>? muted,\n    ValueGetter<Color>? mutedForeground,\n    ValueGetter<Color>? accent,\n    ValueGetter<Color>? accentForeground,\n    ValueGetter<Color>? destructive,\n    ValueGetter<Color>? destructiveForeground,\n    ValueGetter<Color>? border,\n    ValueGetter<Color>? input,\n    ValueGetter<Color>? ring,\n    ValueGetter<Color>? chart1,\n    ValueGetter<Color>? chart2,\n    ValueGetter<Color>? chart3,\n    ValueGetter<Color>? chart4,\n    ValueGetter<Color>? chart5,\n    ValueGetter<Color>? sidebar,\n    ValueGetter<Color>? sidebarForeground,\n    ValueGetter<Color>? sidebarPrimary,\n    ValueGetter<Color>? sidebarPrimaryForeground,\n    ValueGetter<Color>? sidebarAccent,\n    ValueGetter<Color>? sidebarAccentForeground,\n    ValueGetter<Color>? sidebarBorder,\n    ValueGetter<Color>? sidebarRing,\n  }) {\n    return ColorScheme(\n      brightness: brightness == null ? this.brightness : brightness(),\n      background: background == null ? this.background : background(),\n      foreground: foreground == null ? this.foreground : foreground(),\n      card: card == null ? this.card : card(),\n      cardForeground: cardForeground == null\n          ? this.cardForeground\n          : cardForeground(),\n      popover: popover == null ? this.popover : popover(),\n      popoverForeground: popoverForeground == null\n          ? this.popoverForeground\n          : popoverForeground(),\n      primary: primary == null ? this.primary : primary(),\n      primaryForeground: primaryForeground == null\n          ? this.primaryForeground\n          : primaryForeground(),\n      secondary: secondary == null ? this.secondary : secondary(),\n      secondaryForeground: secondaryForeground == null\n          ? this.secondaryForeground\n          : secondaryForeground(),\n      muted: muted == null ? this.muted : muted(),\n      mutedForeground: mutedForeground == null\n          ? this.mutedForeground\n          : mutedForeground(),\n      accent: accent == null ? this.accent : accent(),\n      accentForeground: accentForeground == null\n          ? this.accentForeground\n          : accentForeground(),\n      destructive: destructive == null ? this.destructive : destructive(),\n      destructiveForeground: destructiveForeground == null\n          // ignore: deprecated_member_use_from_same_package\n          