  "{sharedPath}/theme/component_theme_global_registry.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\n/// Global registry for component theme data provided by token config files.\nclass ComponentThemeGlobalRegistry {\n  static final Map<Type, Object? Function()> _resolvers = {};\n\n  /// Registers a resolver for [T].\n  static void register<T>(T? Function() resolver) {\n    _resolvers[T] = resolver;\n  }\n\n  /// Returns whether a resolver has been registered for [T].\n  static bool hasResolver<T>() {\n    return _resolvers.containsKey(T);\n  }\n\n  /// Looks up global component theme data for [T], if registered.\n  static T? maybeOf<T>() {\n    final resolver = _resolvers[T];\n    if (resolver == null) return null;\n    return resolver() as T?;\n  }\n}\n",
  "{sharedPath}/theme/generated_colors.dart": "// ignore_for_file: duplicate_import, unnecessary_import, unused_import, unnecessary_null_comparison, dead_code, deprecated_member_use, use_null_aware_elements, sort_child_properties_last\n\nimport 'dart:ui';\n\nimport 'color_scheme.dart';\n\n/// A collection of color constants and shades for shadcn_flutter.\n///\n/// This class provides predefined colors and color shades that can be used\n/// throughout the application. All colors follow the shadcn design system.\nclass Colors {\n  /// Pure black color.\n  static const Color black = Color(0xff000000);\n\n  /// Pure white color.\n  static const Color white = Color(0xffffffff);\n\n  /// Slate color shades (50-950).\n  static const ColorShades slate = ColorShades.raw({\n    50: Color(0xfff8fafc),\n    100: Color(0xfff1f5f9),\n    200: Color(0xffe2e8f0),\n    300: Color(0xffcbd5e1),\n    400: Color(0xff94a3b8),\n    500: Color(0xff64748b),\n    600: Color(0xff475569),\n    700: Color(0xff334155),\n    800: Color(0xff1e293b),\n    900: Color(0xff0f172a),\n    950: Color(0xff020617),\n  });\n\n  /// Gray color shades (50-950).\n  static const ColorShades gray = ColorShades.raw({\n    50: Color(0xfff9fafb),\n    100: Color(0xfff3f4f6),\n    200: Color(0xffe5e7eb),\n    300: Color(0xffd1d5db),\n    400: Color(0xff9ca3af),\n    500: Color(0xff6b7280),\n    600: Color(0xff4b5563),\n    700: Color(0xff374151),\n    800: Color(0xff1f2937),\n    900: Color(0xff111827),\n    950: Color(0xff030712),\n  });\n\n  /// Zinc color shades (50-950).\n  static const ColorShades zinc = ColorShades.raw({\n    50: Color(0xfffafafa),\n    100: Color(0xfff4f4f5),\n    200: Color(0xffe4e4e7),\n    300: Color(0xffd4d4d8),\n    400: Color(0xffa1a1aa),\n    500: Color(0xff71717a),\n    600: Color(0xff52525b),\n    700: Color(0xff3f3f46),\n    800: Color(0xff27272a),\n    900: Color(0xff18181b),\n    950: Color(0xff09090b),\n  });\n\n  /// Neutral color shades (50-950).\n  static const ColorShades neu